public static <T> boolean compareStreams(Stream<T> s1, Stream<T> s2, Comparator<? super T> comp) {
    List<T> l1 = s1.sorted(comp).collect(Collectors.toList());
    List<T> l2 = s2.sorted(comp).collect(Collectors.toList());
    return l1.equals(l2);
}
