import java.util.*;

public class Grouping {

    public static List<List<String[]>> group(List<String[]> list1, List<String[]> list2, int col) {
        Map<String, List<String[]>> map1 = groupByCol(list1, col);
        Map<String, List<String[]>> map2 = groupByCol(list2, col);
        List<List<String[]>> result = new ArrayList<>();
        for (String key : map1.keySet()) {
            List<String[]> group1 = map1.get(key);
            List<String[]> group2 = map2.get(key);
            if (group2 == null) {
                continue;
            }
            result.addAll(matchGroups(group1, group2));
        }
        return result;
    }

    private static Map<String, List<String[]>> groupByCol(List<String[]> list, int col) {
        Map<String, List<String[]>> map = new HashMap<>();
        for (String[] values : list) {
            String key = values[col];
            List<String[]> group = map.get(key);
            if (group == null) {
                group = new ArrayList<>();
                map.put(key, group);
            }
            group.add(values);
        }
        return map;
    }

    private static List<List<String[]>> matchGroups(List<String[]> group1, List<String[]> group2) {
        List<List<String[]>> result = new ArrayList<>();
        Map<String, List<String[]>> map1 = groupByRemainingCols(group1);
        Map<String, List<String[]>> map2 = groupByRemainingCols(group2);
        for (String key : map1.keySet()) {
            List<String[]> match1 = map1.get(key);
            List<String[]> match2 = map2.get(key);
            if (match2 == null) {
                continue;
            }
            if (allMatch(match1, match2)) {
                result.add(concatLists(match1, match2));
            } else {
                result.addAll(matchGroups(match1, match2));
            }
        }
        for (String key : map2.keySet()) {
            if (!map1.containsKey(key)) {
                result.add(concatLists(map1.get(key), map2.get(key)));
            }
        }
        return result;
    }

    private static Map<String, List<String[]>> groupByRemainingCols(List<String[]> list) {
        Map<String, List<String[]>> map = new HashMap<>();
        for (String[] values : list) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < values.length; i++) {
                if (i != col) {
                    sb.append(values[i]);
                }
            }
            String key = sb.toString();
            List<String[]> group = map.get(key);
            if (group == null) {
                group = new ArrayList<>();
                map.put(key, group);
            }
            group.add(values);
        }
        return map;
    }

    private static boolean allMatch(List<String[]> list1, List<String[]> list2) {
        for (String[] values1 : list1) {
            boolean foundMatch = false;
            for (String[] values2 : list2) {
                if (match(values1, values2)) {
                    foundMatch = true;
                    break;
                }
            }
            if (!foundMatch) {
                return false;
            }
        }
        for (String[] values2 : list2) {
            boolean foundMatch = false;
            for (String[] values1 : list1) {
                if (match(values1, values2)) {
                    foundMatch = true;
                    break;
                }
            }
            if (!foundMatch) {
                return false;
            }
        }
        return true;
    }

    private static boolean match(String[] values1, String[] values2) {
        for (int i = 0; i < values1.length; i++) {
            if (i != col && !Objects.equals(values1[i], values2[i])) {
                return false;
            }
        }
        return true;
    }

    private static List<String[]> concatLists(List<String[]> list1, List<String[]> list2) {
        List<String[]> result = new ArrayList<>(list1);
        result.addAll(list2);
        return result;
    }

}
