            this.credentials.getSubscriptionId(),
            resourceGroupName,
            clusterName);
    Map<String, String> headers = new HashMap<>();
    headers.put("Content-Type", "application/json");
    headers.put("If-Match", "*");
    headers.put("x-ms-version", "2015-03-01-preview");
    String body = "{\"value\":null}";
    return this.restService.sendRequest(url, HttpMethod.PUT, headers, body)
            .map(response -> null);
}
