public static String encodeXML(String in) {

   if (in == null) {
       return null;
   }

   StringBuilder out = new StringBuilder();
   for (int i = 0; i < in.length(); i++) {
       char c = in.charAt(i);
       switch (c) {
       case '<':
           out.append("&lt;");
           break;
       case '>':
           out.append("&gt;");
           break;
       case '\"':
           out.append("&quot;");
           break;
       case '\'':
           out.append("&apos;");
           break;
       case '&':
           out.append("&amp;");
           break;
       default:
           out.append(c);
           break;
       }
   }
   return out.toString();
}
