public void movePointOfView(int deltaX, int deltaY) {
    // Assuming that the Point of view (POV) is represented as a rectangle or reticle
    // Get the current location of the POV
    int currentX = pov.getX();
    int currentY = pov.getY();

    // Calculate the new location of the POV by adding deltaX and deltaY
    int newX = currentX + deltaX;
    int newY = currentY + deltaY;

    // Set the new location of the POV
    pov.setLocation(newX, newY);
}
