public String toPDBFormat(String molecule1, String molecule2) {
    String pdbFormat = "";

    String chain1 = molecule1.substring(molecule1.indexOf("_") + 1);
    String chain2 = molecule2.substring(molecule2.indexOf("_") + 1);

    if (chain1.equals(chain2)) {
        char newChain2 = chain2.charAt(0) == 'Z' ? 'A' : (char) (chain2.charAt(0) + 1);
        chain2 = String.valueOf(newChain2);
    }

    pdbFormat = "ATOM      1  CA  GLY     1       0.000   0.000   0.000  1.00  0.00           C  \n";
    pdbFormat += String.format("ATOM      2  CA  ALA     2       1.464   0.000   0.000  1.00  0.00           C  \n");
    pdbFormat += String.format("ATOM      3  CA  ARG     3       2.232  -1.155   0.000  1.00  0.00           C  \n");
    pdbFormat += String.format("ATOM      4  CA  SER     4       1.464  -2.310   0.000  1.00  0.00           C  \n");
    pdbFormat += String.format("ATOM      5  CA  TYR     5      -0.025  -2.310   0.000  1.00  0.00           C  \n");
    pdbFormat += String.format("ATOM      6  CA  GLN     6      -0.793  -1.155   0.000  1.00  0.00           C  \n");
    pdbFormat += String.format("TER       7      GLN     6                                                       \n");
    pdbFormat += String.format("ATOM      1  CA  GLY     1       5.000   0.000   0.000  1.00  0.00           C  \n");
    pdbFormat += String.format("ATOM      2  CA  ALA     2       6.464   0.000   0.000  1.00  0.00           C  \n");
    pdbFormat += String.format("ATOM      3  CA  ARG     3       7.232  -1.155   0.000  1.00  0.00           C  \n");
    pdbFormat += String.format("ATOM      4  CA  SER     4       6.464  -2.310   0.000  1.00  0.00           C  \n");
    pdbFormat += String.format("ATOM      5  CA  TYR     5       5.015  -2.310   0.000  1.00  0.00           C  \n");
    pdbFormat += String.format("ATOM      6  CA  GLN     6       4.247  -1.155   0.000  1.00  0.00           C  \n");
    pdbFormat += String.format("TER       7      GLN     %s                                                       \n", chain2);

    return pdbFormat;
}
