public static ArrayList<String> expandDifferentialPath(ArrayList<String> paths) {
    ArrayList<String> expandedPaths = new ArrayList<String>();
    for (String path : paths) {
        if (path.contains("(")) {
            int startIndex = path.indexOf("(");
            int endIndex = path.indexOf(")");
            String prefix = path.substring(0, startIndex);
            String[] options = path.substring(startIndex + 1, endIndex).split(",");
            String suffix = path.substring(endIndex + 1);
            for (String option : options) {
                expandedPaths.add(prefix + option.trim() + suffix);
            }
        } else {
            expandedPaths.add(path);
        }
    }
    return expandedPaths;
}
