public Rule replaceDigramWithNonTerminal(Rule r) {
    String original = r.getExpression();
    String newExpression = "";
    int i = 0;
    while (i < original.length()-1) {
        String digram = original.substring(i, i+2);
        Rule digramRule = new Rule(digram, digram);
        NonTerminalSymbol newSymbol = new NonTerminalSymbol();
        newExpression += newSymbol.getName() + " ";
        r.getGrammar().addRule(digramRule);
        r.getGrammar().addRule(new Rule(newSymbol.getName(), digram));
        i++;
    }
    if (i == original.length()-1) {
        newExpression += original.substring(i);
    }       
    return new Rule(r.getLHS(), newExpression.trim());
}
