import javax.servlet.http.HttpSession;
import javax.servlet.http.HttpSessionBindingEvent;
import javax.servlet.http.HttpSessionBindingListener;

public class SessionFieldRemover implements HttpSessionBindingListener {
    private final String fieldName;
    private final long maxTime;

    public SessionFieldRemover(String fieldName, long maxTime) {
        this.fieldName = fieldName;
        this.maxTime = maxTime;
    }

    public void valueBound(HttpSessionBindingEvent event) {
        event.getSession().setAttribute(fieldName, this);
    }

    public void valueUnbound(HttpSessionBindingEvent event) {
        event.getSession().removeAttribute(fieldName);
    }

    public static void removeFieldAfterMaxTime(HttpSession session, String fieldName, long maxTime) {
        session.setAttribute(fieldName, new SessionFieldRemover(fieldName, maxTime));
    }
}
