public MAVector dotProduct(Matrix M, MAVector v) {
    if (M.getNumCols() != v.getSize()) {
        throw new IllegalArgumentException("ncols of matrix M must match vector v's size.");
    }
    double[] result = new double[M.getNumRows()];
    for (int i = 0; i < M.getNumRows(); i++) {
        double sum = 0;
        for (int j = 0; j < M.getNumCols(); j++) {
            sum += M.get(i, j) * v.get(j);
        }
        result[i] = sum;
    }
    return new MAVector(result);
}
