public byte[] getBinaryContent(long rangeValue, FedoraResource resource) throws IOException {
    RangeRequest rangeRequest = new RangeRequest(rangeValue, resource.getSize());
    try (InputStream is = resource.getContent(rangeRequest)) {
        ByteArrayOutputStream os = new ByteArrayOutputStream();
        byte[] buffer = new byte[4096];
        int bytesRead;
        while ((bytesRead = is.read(buffer)) != -1) {
            os.write(buffer, 0, bytesRead);
        }
        return os.toByteArray();
    }
}
