public static URL findRoboconfArtifactUrl(String artifactId, String version) throws IOException {
    String mavenCentralUrl = "https://repo1.maven.org/maven2/";
    String jarPath = artifactId + "/" + version + "/" + artifactId + "-" + version + ".jar";
    URL jarUrl = new URL(mavenCentralUrl + jarPath);
    HttpURLConnection connection = (HttpURLConnection) jarUrl.openConnection();
    connection.setRequestMethod("HEAD");
    connection.connect();
    int code = connection.getResponseCode();
    connection.disconnect();
    return code == HttpURLConnection.HTTP_OK ? jarUrl : null;
}
