import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

public void archive(String parentPath, String[] srcPaths, String dest, boolean append) throws IOException {
    File destDir = new File(dest);
    if (!destDir.exists()) {
        destDir.mkdirs();
    }

    String zipFileName = append ? dest + "/archive.zip" : dest + "/newArchive.zip";
    FileOutputStream fos = new FileOutputStream(zipFileName);
    ZipOutputStream zos = new ZipOutputStream(fos);

    for (String srcPath : srcPaths) {
        Path path = Paths.get(parentPath, srcPath);
        if (!Files.exists(path)) {
            System.out.println("File or directory does not exist: " + path.toString());
            continue;
        }
        if (Files.isDirectory(path)) {
            zipDirectory(path.toFile(), path.getFileName().toString(), zos);
        } else {
            zipFile(path.toFile(), null, zos);
        }
    }

    zos.closeEntry();
    zos.close();
    fos.close();
}

private void zipDirectory(File directory, String parentPath, ZipOutputStream zos) throws IOException {
    for (File file : directory.listFiles()) {
        if (file.isDirectory()) {
            zipDirectory(file, parentPath + "/" + file.getName(), zos);
        } else {
            zipFile(file, parentPath, zos);
        }
    }
}

private void zipFile(File file, String parentPath, ZipOutputStream zos) throws IOException {
    ZipEntry zipEntry;
    if (parentPath != null) {
        zipEntry = new ZipEntry(parentPath + "/" + file.getName());
    } else {
        zipEntry = new ZipEntry(file.getName());
    }
    zos.putNextEntry(zipEntry);

    byte[] bytes = new byte[1024];
    int length;
    FileInputStream fis = new FileInputStream(file);
    while ((length = fis.read(bytes)) >= 0) {
        zos.write(bytes, 0, length);
    }
    fis.close();
}
