public void connectClausesThroughFullOccurrenceLists(List<Clause> clauses) {
   Map<Integer, List<Clause>> occurrencesMap = new HashMap<>();
   for (Clause clause : clauses) {
      for (Literal literal : clause.getLiterals()) {
         int literalValue = literal.getValue();
         if (!occurrencesMap.containsKey(literalValue)) {
            occurrencesMap.put(literalValue, new ArrayList<>());
         }
         occurrencesMap.get(literalValue).add(clause);
      }
   }

   for (Map.Entry<Integer, List<Clause>> entry : occurrencesMap.entrySet()) {
      List<Clause> clausesWithLiteral = entry.getValue();
      for (int i = 0; i < clausesWithLiteral.size(); i++) {
         Clause clause1 = clausesWithLiteral.get(i);
         for (int j = i + 1; j < clausesWithLiteral.size(); j++) {
            Clause clause2 = clausesWithLiteral.get(j);
            clause1.addFullOccurrence(clause2);
            clause2.addFullOccurrence(clause1);
         }
      }
   }
}
