public void restorePostParamsFromSession(HttpServletRequest extRequest, HttpServletRequest req, StringBuffer reqURL) {
    HttpSession session = req.getSession();
    Map<String, String[]> postParams = (Map<String, String[]>) session.getAttribute("postParams");

    if (postParams != null) {
        for (Map.Entry<String, String[]> entry : postParams.entrySet()) {
            String paramName = entry.getKey();
            String[] paramValues = entry.getValue();

            extRequest.setAttribute(paramName, paramValues);
        }

        String queryString = req.getQueryString();
        String fullURL = reqURL.toString();
        if (queryString != null && !queryString.isEmpty()) {
            fullURL += "?" + queryString;
        }

        // Redirect to original URL with POST parameters
        try {
            req.getRequestDispatcher(fullURL).forward(extRequest, req);
        } catch (ServletException | IOException e) {
            // Handle exception
        }
    }
}
