import javax.management.Notification;
import javax.management.ObjectName;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;

public static void encodeNotifications(JsonGenerator out, Notification[] value) throws IOException {
    JsonFactory factory = new JsonFactory();
    out.writeStartArray();
    for (Notification n : value) {
        String source = n.getSource().toString();
        if (!(n.getSource() instanceof ObjectName)) {
            throw new IOException("Expected an ObjectName as source for " + "Notification " + n);
        }
        ObjectName objName = (ObjectName) n.getSource();
        out.writeStartObject();
        out.writeStringField("type", n.getType());
        out.writeNumberField("sequenceNumber", n.getSequenceNumber());
        out.writeNumberField("timestamp", n.getTimeStamp());
        out.writeStringField("message", n.getMessage());
        out.writeStringField("sourceClass", n.getClass().getName());
        out.writeStringField("sourceObjectName", objName.getCanonicalName());
        out.writeEndObject();
    }
    out.writeEndArray();
}
