import org.apache.http.HttpEntity;
import org.apache.http.HttpResponse;
import org.apache.http.client.HttpClient;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;
import org.json.JSONException;
import org.json.JSONObject;

public static Resource executePathQuery(String path) throws Exception {
    HttpClient client = HttpClients.createDefault();
    HttpGet request = new HttpGet(path);
    HttpResponse response = client.execute(request);
    HttpEntity entity = response.getEntity();
    String jsonString = EntityUtils.toString(entity);
    JSONObject jsonObject = new JSONObject(jsonString);
    String uriString = jsonObject.getString("uri");
    HttpGet uriRequest = new HttpGet(uriString);
    HttpResponse uriResponse = client.execute(uriRequest);
    HttpEntity uriEntity = uriResponse.getEntity();
    String text = EntityUtils.toString(uriEntity);
    Resource resource = new Resource(text, "text/plain");
    return resource;
}
