public List<Pair<Integer, Integer>> getAlignmentMismatches(AlignmentPair alignmentPair) {
    if (alignmentPair == null) {
        throw new IllegalArgumentException("alignmentPair must not be null");
    }

    List<Pair<Integer, Integer>> mismatches = new ArrayList<>();

    String reference = alignmentPair.getReference();
    String query = alignmentPair.getQuery();

    int minLen = Math.min(reference.length(), query.length());
    int start = 0;
    int end = 0;

    for (int i = 0; i < minLen; i++) {
        if (reference.charAt(i) != query.charAt(i)) {
            if (start == end) {
                start = i;
            }
            end = i + 1;
        } else {
            if (start != end) {
                mismatches.add(new Pair<>(start, end));
                start = end = 0;
            }
        }
    }

    if (start != end) {
        mismatches.add(new Pair<>(start, end));
    }

    return mismatches;
}
