public String[] lemmatizeSentence(String[] tokens){
    // import the necessary libraries
    import edu.stanford.nlp.ling.CoreAnnotations.LemmaAnnotation;
    import edu.stanford.nlp.ling.CoreLabel;
    import edu.stanford.nlp.pipeline.Annotation;
    import edu.stanford.nlp.pipeline.StanfordCoreNLP;
    import edu.stanford.nlp.util.CoreMap;
    import java.util.*;

    // create an empty Annotation object
    Annotation sentence = new Annotation(Arrays.toString(tokens));

    // set up properties for the pipeline
    Properties props = new Properties();
    props.setProperty("annotators", "tokenize, ssplit, pos, lemma");
    StanfordCoreNLP pipeline = new StanfordCoreNLP(props);

    // annotate the sentence
    pipeline.annotate(sentence);

    // get the coremap for the sentence
    List<CoreMap> coreMaps = sentence.get(CoreAnnotations.SentencesAnnotation.class);
    List<String> lemmas = new ArrayList<>();

    // iterate over the coremaps and get the lemma for each token
    for(CoreMap coreMap : coreMaps) {
        for(CoreLabel token: coreMap.get(CoreAnnotations.TokensAnnotation.class)) {
            // get the lemma for the token
            String lemma = token.get(LemmaAnnotation.class);
            lemmas.add(lemma);
        }
    }

    // return the lemmas as an array of strings
    return lemmas.toArray(new String[0]);
}
