import org.openscience.cdk.CDKConstants;
import org.openscience.cdk.interfaces.*;

public void labelAllStereoElements(IAtomContainer container) {
    for (IAtom atom : container.atoms()) {
        if (atom.getFlag(CDKConstants.STEREOCENTER)) {
            StereoElement stereoElement = container.getStereoElement(atom);
            if (stereoElement instanceof StereoCenter) {
                StereoCenter stereoCenter = (StereoCenter) stereoElement;
                CIPChirality chirality = stereoCenter.getCIPChirality();
                atom.setProperty(CDKConstants.CIP_DESCRIPTOR, chirality.toString());
            } else if (stereoElement instanceof ExocyclicDoubleBond) {
                ExocyclicDoubleBond exocyclicDoubleBond = (ExocyclicDoubleBond) stereoElement;
                CIPChirality chirality = exocyclicDoubleBond.getCIPChirality();
                atom.setProperty(CDKConstants.CIP_DESCRIPTOR, chirality.toString());
            } else if (stereoElement instanceof TetrahedralChirality) {
                TetrahedralChirality tetrahedralChirality = (TetrahedralChirality) stereoElement;
                CIPChirality chirality = tetrahedralChirality.getCIPChirality();
                atom.setProperty(CDKConstants.CIP_DESCRIPTOR, chirality.toString());
            }
        } else {
            atom.setProperty(CDKConstants.CIP_DESCRIPTOR, null);
        }
    }

    for (IBond bond : container.bonds()) {
        if (bond.getFlag(CDKConstants.STEREO_BOND)) {
            StereoElement stereoElement = container.getStereoElement(bond);
            if (stereoElement instanceof StereoBond) {
                StereoBond stereoBond = (StereoBond) stereoElement;
                CIPChirality chirality = stereoBond.getCIPChirality();
                bond.setProperty(CDKConstants.CIP_DESCRIPTOR, chirality.toString());
            }
        } else {
            bond.setProperty(CDKConstants.CIP_DESCRIPTOR, null);
        }
    }
}
