import java.util.*;

public class CyclicIterator<T> implements Iterator<T> {
    private List<T> items;
    private int currentIndex = 0;
    private int numCyclesRemaining;

    public CyclicIterator(List<T> items, int numCycles) {
        this.items = items;
        this.numCyclesRemaining = numCycles;
    }

    public boolean hasNext() {
        return (numCyclesRemaining != 0);
    }

    public T next() {
        if (!hasNext()) {
            throw new NoSuchElementException("No more elements to iterate");
        }
        T item = items.get(currentIndex);
        currentIndex++;
        if (currentIndex >= items.size()) {
            currentIndex = 0;
            if (numCyclesRemaining > 0) {
                numCyclesRemaining--;
            }
        }
        return item;
    }

    public void remove() {
        throw new UnsupportedOperationException("Remove method not supported");
    }
}

public class Main {
    public static void main(String[] args) {
        List<Integer> items = Arrays.asList(1, 2, 3);
        Iterator<Integer> cyclicIterator = new CyclicIterator<>(items, 3);
        while (cyclicIterator.hasNext()) {
            System.out.println(cyclicIterator.next());
        }
    }
}
