public Map<String, String> createMapFromBuffer(String buffer) {
    // split the buffer by a separator character, assuming each key-value pair is separated by a new line
    String[] pairs = buffer.split(System.getProperty("line.separator"));
    // create a new HashMap object to store the key-value pairs
    Map<String, String> map = new HashMap<String, String>();
    // iterate over each key-value pair
    for (String pair : pairs) {
        // split the pair by a separator character, assuming each key and value are separated by a colon
        String[] keyValue = pair.split(":");
        // add the key-value pair to the map
        map.put(keyValue[0], keyValue[1]);
    }
    return map;
}
