import java.io.IOException;
import java.io.Reader;
import java.io.Writer;

public void unescape(Reader reader, Writer writer) throws IOException {
    int c;
    while ((c = reader.read()) != -1) {
        if (c == '\\') {
            switch (c = reader.read()) {
                case '\\':
                    writer.write('\\');
                    break;
                case 'n':
                    writer.write('\n');
                    break;
                case 't':
                    writer.write('\t');
                    break;
                case 'r':
                    writer.write('\r');
                    break;
                case '\'':
                    writer.write('\'');
                    break;
                case '\"':
                    writer.write('\"');
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escape sequence: \\" + (char) c);
            }
        } else {
            writer.write(c);
        } 
    }
}
