@Override
public Map<Integer, Integer> stringToBoundary(String stringValue, Integer offset) {
    // Initialize the map to store boundaries
    Map<Integer, Integer> boundaries = new LinkedHashMap<>();

    // Split the string value by the colon delimiter
    String[] pairs = stringValue.split(":");

    // Loop through each pair, extract the digits and add them to the map
    for (String pair : pairs) {
        String[] digits = pair.split("-");
        int start = Integer.parseInt(digits[0]) + offset;
        int end = Integer.parseInt(digits[1]) + offset;
        boundaries.put(start, end);
    }

    // Return the map of boundaries
    return boundaries;
