public void readFile(String line, Map<String, List<String>> mapUserRecommendations) {
    try {
        BufferedReader bufferedReader = new BufferedReader(new FileReader("recommended_items.txt"));
        String currentLine;
        while ((currentLine = bufferedReader.readLine()) != null) {
            if (currentLine.equals(line)) {
                String[] values = line.split(":");
                String user = values[0];
                String recommendation = values[1];
                if (mapUserRecommendations.containsKey(user)) {
                    mapUserRecommendations.get(user).add(recommendation);
                } else {
                    List<String> recommendations = new ArrayList<>();
                    recommendations.add(recommendation);
                    mapUserRecommendations.put(user, recommendations);
                }
            }
        }
        bufferedReader.close();
    } catch (IOException e) {
        e.printStackTrace();
    }
}
