public static void callWithLock(final File file,
            final LockedFileRunner runner, final boolean truncate) {
        final RandomAccessFile raf;
        try {
            raf = new RandomAccessFile(file, "rw");
        } catch (final FileNotFoundException e) {
            LOG.error("Could not find torrent data file?", e);
            return;
        }
        final FileChannel fc = raf.getChannel();
        FileLock lock = null;
        try {
            lock = fc.lock();
            if (!lock.isValid()) {
                LOG.error("Lock not valid?");
            }
            runner.callWithLock(fc);
        } catch (final FileNotFoundException e) {
            LOG.error("Could not find lock file?", e);
        } catch (final OverlappingFileLockException e) {
            LOG.debug("Overlapping file lock", e);
        } catch (final ClosedChannelException e) {
            LOG.error("Closed channel?", e);
        } catch (final NonWritableChannelException e) {
            LOG.error("Closed channel?", e);
        } catch (final IOException e) {
            LOG.error("IO Error getting lock?", e);
        } finally {




            if (lock == null) {
                LOG.error("Lock file is null!!");
            }
            if (lock != null && truncate) {
                try {
                    LOG.debug("Truncating file");
                    fc.truncate(0);
                    LOG.debug("Truncated file");
                    if (fc.size() != 0L) {
                        LOG.error("Truncated file to 0 but size is: "
                                + fc.size());
                    }
                } catch (final IOException e) {
                    LOG.warn("Could not truncate the file", e);
                }
            }
            try {
                raf.close();
            } catch (final IOException e) {
                LOG.warn("Could not close RAF", e);
            }
            if (lock != null) {
                try {
                    lock.release();
                } catch (final IOException e) {
                    LOG.debug("IOException releasing lock", e);
                }
            }
        }
    },0

private void generateProfileConcreteClassInfo(CtClass profileConcreteClass) {

		final ClassPool pool = profileComponent.getClassPool();

		CtClass profileClass = null;
		try {
			profileClass = pool.get(Profile.class.getName());
		} catch (NotFoundException e) {
			throw new SLEEException(e.getMessage(), e);
		}

		ProfileConcreteClassInfo profileConcreteClassInfo = profileComponent.getProfileConcreteClassInfo();

		for (CtMethod method : profileClass.getDeclaredMethods()) {
			for (CtMethod profileConcreteMethod : profileConcreteClass
					.getMethods()) {
				if (profileConcreteMethod.getName().equals(
						method.getName())
						&& profileConcreteMethod.getSignature().equals(
								method.getSignature())) {

					profileConcreteClassInfo.setInvokeInfo(profileConcreteMethod
							.getMethodInfo().getName(), !profileConcreteMethod
							.isEmpty());
					break;
				}
			}
		}
