public static void mergeGetToMultiget(String currentCmd, List<String> mergeCommands) throws InterruptedException {
    if (!currentCmd.startsWith("get ")) {
        throw new IllegalArgumentException("Current command should start with 'get'");
    }
    mergeCommands.add(currentCmd);
    // convert all get commands in mergeCommands to a single multi-get command
    String multiGetCmd = "get ";
    for (String cmd : mergeCommands) {
        String[] tokens = cmd.split("\\s+");
        if (tokens.length != 2 || !tokens[0].equals("get")) {
            throw new IllegalArgumentException("Invalid command: " + cmd);
        }
        multiGetCmd += tokens[1] + " ";
    }
    System.out.println("Merged multi-get command: " + multiGetCmd);
    // call the actual multiget command
    //multiget(multiGetCmd);
}
