import java.io.File;
import java.util.ArrayList;
import java.util.List;

public List<File> getFiles(String path, String includeMask) {
    List<File> files = new ArrayList<>();
    File folder = new File(path);
    File[] allFiles = folder.listFiles();

    for (File file : allFiles) {
        if (file.isFile() && file.getName().matches(includeMask)) {
            files.add(file);
        } else if (file.isDirectory()) {
            files.addAll(getFiles(file.getAbsolutePath(), includeMask));
        }
    }

    return files;
}
