public String getExcelExtension(String dataPath) throws TechnicalException {
    String[] extensions = { ".xls", ".xlsx", ".xlsm" };
    File[] dataFiles = new File(dataPath).listFiles();
    Set<String> uniqueExtensions = new HashSet<>();
    for (File file : dataFiles) {
        String extension = getFileExtension(file);
        if (Arrays.asList(extensions).contains(extension)) {
            uniqueExtensions.add(extension);
        } else {
            throw new TechnicalException("Invalid Excel extension: " + extension);
        }
    }
    if (uniqueExtensions.size() == 1) {
        return uniqueExtensions.iterator().next();
    } else {
        throw new TechnicalException("Multiple unique extensions found: " + uniqueExtensions.toString());
    }
}

private static String getFileExtension(File file) {
    String fileName = file.getName();
    if (fileName.lastIndexOf(".") != -1 && fileName.lastIndexOf(".") != 0) {
        return fileName.substring(fileName.lastIndexOf("."));
    } else {
        return "";
    }
}
