        return "com.mysql.jdbc.jdbc2.optional.MysqlDataSource";
    } else if (vendorPropertiesPID.contains("oracle")) {
        return "oracle.jdbc.pool.OracleDataSource";
    } else if (vendorPropertiesPID.contains("microsoft")) {
        return "com.microsoft.sqlserver.jdbc.SQLServerDataSource";
    } else if (vendorPropertiesPID.contains("db2")) {
        return "com.ibm.db2.jcc.DB2SimpleDataSource";
    } else {
        return null;
    }
}
