public boolean offerToPriorityQueue(PriorityQueue<Integer> pq, int element) {
    if (pq.size() < pq.capacity()) { // PriorityQueue is not full
        pq.offer(element);
        return true;
    } else if (!lessThan(element, pq.peek())) { // not lessThan(element, top())
        pq.poll();
        pq.offer(element);
        return true;
    }
    return false;
}

private boolean lessThan(int a, int b) {
    return a < b;
}
