public static <T, R> Iterable<R> apply(Iterable<T> fromIterable, Function<? super T, ? extends R> function) {
    return () -> new Iterator<R>() {
        private final Iterator<T> iterator = fromIterable.iterator();

        @Override
        public boolean hasNext() {
            return iterator.hasNext();
        }

        @Override
        public R next() {
            return function.apply(iterator.next());
        }
    };
}
