public void setupSerialization(ByteBuffer allocated, INDArray arr, boolean rewind) {
    int rank = arr.rank();

    // Put rank as 4 bytes
    allocated.putInt(rank);

    // Put data opType as 4 bytes
    allocated.putInt(arr.data().dataType().toInt());

    // Setup shape information
    long[] shape = arr.shape();
    for (int i = 0; i < rank; i++) {
        allocated.putLong(shape[i]);
    }

    // Setup codec information
    CompressionCodec codec = CompressionCodec.DEFAULT; // default codec
    boolean compressed = false; // no compression by default
    if (compressed) {
        allocated.put((byte) 1); // compressed flag
        allocated.putInt(codec.getCode()); // codec identifier
    } else {
        allocated.put((byte) 0); // uncompressed flag
    }

    if (rewind) {
        allocated.rewind();
    }
}
