public void compactMemory() {
    Runtime runtime = Runtime.getRuntime();
    long memoryUsedBeforeGC = runtime.totalMemory() - runtime.freeMemory();
    runtime.gc();
    long memoryUsedAfterGC = runtime.totalMemory() - runtime.freeMemory();
    byte[] allocation = new byte[(int)memoryUsedAfterGC];
    runtime.gc();
    long memoryUsedAfterAllocation = runtime.totalMemory() - runtime.freeMemory();
    System.out.println("Memory used before GC: " + memoryUsedBeforeGC);
    System.out.println("Memory used after GC: " + memoryUsedAfterGC);
    System.out.println("Memory used after allocation: " + memoryUsedAfterAllocation);
}
