import com.google.gson.Gson;
import okhttp3.FormBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

public TokenSet getNewAccessToken(String refreshToken, String apiSecret) throws IOException, KiteException {
    String url = "https://api.kite.trade/session/token";
    OkHttpClient client = new OkHttpClient();

    RequestBody formBody = new FormBody.Builder()
            .add("refresh_token", refreshToken)
            .add("api_secret", apiSecret)
            .build();
    Request request = new Request.Builder()
            .url(url)
            .post(formBody)
            .build();

    Response response = client.newCall(request).execute();
    String responseBody = response.body().string();

    if (!response.isSuccessful()) {
        throw new KiteException("Unable to get access token");
    }

    Gson gson = new Gson();
    TokenSet tokenSet = gson.fromJson(responseBody, TokenSet.class);

    if (tokenSet.userId == null || tokenSet.refreshToken == null || tokenSet.apiSecret == null) {
        throw new KiteException("Access token is invalid");
    }

    return tokenSet;
}

class TokenSet {
    String userId;
    String refreshToken;
    String apiSecret;
}
