public void patchJdbcUrlProperties(StringBuilder jdbcUrl, Map<String, String> properties) {
    // Check if jdbcUrl is null or empty
    if (jdbcUrl == null || jdbcUrl.length() == 0) {
        throw new IllegalArgumentException("jdbcUrl cannot be null or empty");
    }

    // Check if properties are null or empty
    if (properties == null || properties.isEmpty()) {
        return;
    }

    // Check if jdbcUrl contains existing properties
    boolean hasExistingProperties = jdbcUrl.indexOf("?") != -1;
    boolean isFirstProperty = true;

    // Iterate over properties and add them to jdbcUrl
    for (Map.Entry<String, String> entry : properties.entrySet()) {
        if (entry.getKey() == null || entry.getKey().isEmpty() || entry.getValue() == null || entry.getValue().isEmpty()) {
            continue;
        }

        if (isFirstProperty && !hasExistingProperties) {
            jdbcUrl.append("?");
        } else {
            jdbcUrl.append("&");
        }

        jdbcUrl.append(entry.getKey()).append("=").append(entry.getValue());

        isFirstProperty = false;
    }
}
