public static <T> List<T> transformList(List<T> origList, Class<T> attrType) {
    List<T> transformedList = new ArrayList<>();
    boolean isTransformed = false;
    for (T item : origList) {
        try {
            T transformedItem = attrType.cast(item);
            transformedList.add(transformedItem);
        } catch (ClassCastException ex) {
            transformedList.add(item);
            isTransformed = true;
        }
    }
    return isTransformed ? transformedList : origList;
}
