import java.util.*;

public class MapSorter {
    public static <K, V extends Comparable<? super V>> Map<K, V> sort(Map<K, V> map, Comparator<? super V> sortBy, boolean ascending, boolean nullsFirst) {
        List<Map.Entry<K, V>> entries = new ArrayList<>(map.entrySet());
        Comparator<Map.Entry<K, V>> comparator = Map.Entry.comparingByValue(sortBy);
        if (!ascending) {
            comparator = comparator.reversed();
        }
        if (nullsFirst) {
            comparator = Comparator.nullsFirst(comparator);
        } else {
            comparator = Comparator.nullsLast(comparator);
        }
        entries.sort(comparator);
        Map<K, V> sortedMap = new LinkedHashMap<>();
        for (Map.Entry<K, V> entry : entries) {
            sortedMap.put(entry.getKey(), entry.getValue());
        }
        return sortedMap;
    }
}
