public List<Point> simplify(List<Point> points, double sqTolerance) {
    List<Point> simplifiedPoints = new ArrayList<Point>();
    if (points.size() <= 2) {
        return points;
    }
    int idx = 0;
    int last = points.size() - 1;
    for (int i = 0; i <= last; i++) {
        Point currentPoint = points.get(i);
        if (i == 0 || i == last || shouldKeepPoint(points.get(i - 1), currentPoint, points.get(i + 1), sqTolerance)) {
            simplifiedPoints.add(currentPoint);
        }
    }
    return simplifiedPoints;
}

private boolean shouldKeepPoint(Point previousPoint, Point currentPoint, Point nextPoint, double sqTolerance) {
    double d1 = currentPoint.distanceSq(previousPoint);
    double d2 = currentPoint.distanceSq(nextPoint);
    return (d1 + d2) <= sqTolerance;
}

class Point {
    private double x;
    private double y;

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double distanceSq(Point p) {
        double dx = p.x - this.x;
        double dy = p.y - this.y;
        return dx * dx + dy * dy;
    }
}
