public ClientMessage[] splitMessageIntoFrames(int maxFrameSize, ClientMessage clientMessage) {
    int messageLength = clientMessage.getLength();
    int numOfFrames = (int) Math.ceil((double) messageLength / maxFrameSize);
    ClientMessage[] messageFrames = new ClientMessage[numOfFrames];
    int frameIndex = 0;
    int remainingMessageLength = messageLength;
    byte[] messageData = clientMessage.getData();
    int currentFrameSize;

    while (remainingMessageLength > 0) {
        currentFrameSize = Math.min(maxFrameSize, remainingMessageLength);
        byte[] frameData = new byte[currentFrameSize];
        System.arraycopy(messageData, (messageLength - remainingMessageLength), frameData, 0, currentFrameSize);
        messageFrames[frameIndex] = new ClientMessage(frameData);
        remainingMessageLength -= currentFrameSize;
        frameIndex++;
    }

    return messageFrames;
}
