public ReportValue convertToReportValue(DataConfig type, String dataObject) throws VectorPrintException {
    switch (type.getType()) {
        case BOOLEAN:
            return ReportValue.valueOf(Boolean.parseBoolean(dataObject));
        case DATE:
            try {
                return ReportValue.valueOf(DateUtils.truncate(DateUtils.parseDate(dataObject, "yyyy-MM-dd"), Calendar.DATE));
            } catch (ParseException e) {
                throw new VectorPrintException("Failed to parse date", e);
            }
        case DOUBLE:
            try {
                return ReportValue.valueOf(Double.parseDouble(dataObject));
            } catch (NumberFormatException e) {
                throw new VectorPrintException("Failed to parse double", e);
            }
        case EXPRESSION:
            try {
                return ReportValue.valueOf(MVEL.eval(type.getExpression(), dataObject));
            } catch (RuntimeException e) {
                throw new VectorPrintException("Failed to evaluate expression", e);
            }
        case STRING:
            return ReportValue.valueOf(dataObject);
        case UNKNOWN:
        default:
            throw new VectorPrintException("Unknown data type");
    }
}
