public List<Map<String, Object>> performVariableAssignments(RangeTag action, List<Map<String, Object>> possibleStateList) {
        List<Map<String, Object>> cartesianProduct = new ArrayList<>();

        for (Map<String, Object> possibleState : possibleStateList) {
            for (Map.Entry<String, Range> entry : action.getVariableRanges().entrySet()) {
                String variable = entry.getKey();
                Range range = entry.getValue();

                for (Object value : range.values()) {
                    Map<String, Object> newState = new HashMap<>(possibleState);
                    newState.put(variable, value);
                    cartesianProduct.add(newState);
                }
            }
        }

        return cartesianProduct;
    }
