public static Set<Node> optimizedUnionNodes(Set<Node> set1, Set<Node> set2) {
    // Create a new set to hold the union of the two sets
    Set<Node> union = new HashSet<>(set1);
    // Add all nodes from set2 to the union set
    union.addAll(set2);
    // Loop through each node in union set and remove any nodes that are already in a union set
    for (Node node : union) {
        if (set1.contains(node) && set2.contains(node)) {
            set2.remove(node);
        } else if (set2.contains(node)) {
            set1.add(node);
        }
    }
    // Return the optimized union set
    return union;
}
