public Jingle dispatchPacket(Stanza iq) throws XMPPException, NotConnectedException, InterruptedException {
    // Recognize the stanza type
    if (iq instanceof IQ) {
        IQ.Type type = ((IQ) iq).getType();

        // Depending on the current state, deliver the stanza to the right event handler
        if (type == IQ.Type.set) {
            // handle set stanza
            return handleSetStanza((IQ) iq);
        } else if (type == IQ.Type.get) {
            // handle get stanza
            return handleGetStanza((IQ) iq);
        } else if (type == IQ.Type.result) {
            // handle result stanza
            return handleResultStanza((IQ) iq);
        } else if (type == IQ.Type.error) {
            // handle error stanza
            return handleErrorStanza((IQ) iq);
        }
    } else if (iq instanceof Message) {
        // handle message stanza
        return handleMessageStanza((Message) iq);
    } else if (iq instanceof Presence) {
        // handle presence stanza
        return handlePresenceStanza((Presence) iq);
    }
    return null;
}

