import java.beans.PropertyChangeEvent;
import java.beans.PropertyChangeListener;
import java.util.HashSet;
import java.util.Set;

public class MyClass {

  public static void recursivelyAddPropertyChangeListener(Object object, PropertyChangeListener propertyChangeListener, Set<Object> processedObjects) {
    if (processedObjects.contains(object)) {
      return;
    }
    processedObjects.add(object);
    if (object instanceof MyTypeA) {
      MyTypeA A = (MyTypeA) object;
      A.addPropertyChangeListener(propertyChangeListener);
      recursivelyAddPropertyChangeListener(A.getSubObject(), propertyChangeListener, processedObjects);
    } else if (object instanceof MyTypeB) {
      MyTypeB B = (MyTypeB) object;
      B.addPropertyChangeListener(propertyChangeListener);
      recursivelyAddPropertyChangeListener(B.getSubObject(), propertyChangeListener, processedObjects);
    } else { 
      return;
    }
  }

}

class MyTypeA {
  private MyTypeB subObject;
  private Set<PropertyChangeListener> listeners = new HashSet<>();

  public void addPropertyChangeListener(PropertyChangeListener listener) {
    listeners.add(listener);
  }

  public void removePropertyChangeListener(PropertyChangeListener listener) {
    listeners.remove(listener);
  }

  public void setSubObject(MyTypeB subObject) {
    this.subObject = subObject;
  }

  public MyTypeB getSubObject() {
    return subObject;
  }

  public void firePropertyChangeEvent(String propertyName, Object oldValue, Object newValue) {
    PropertyChangeEvent event = new PropertyChangeEvent(this, propertyName, oldValue, newValue);
    for (PropertyChangeListener listener : listeners) {
      listener.propertyChange(event);
    }
  }
}

class MyTypeB {
  private MyTypeA subObject;
  private Set<PropertyChangeListener> listeners = new HashSet<>();

  public void addPropertyChangeListener(PropertyChangeListener listener) {
    listeners.add(listener);
  }

  public void removePropertyChangeListener(PropertyChangeListener listener) {
    listeners.remove(listener);
  }

  public void setSubObject(MyTypeA subObject) {
    this.subObject = subObject;
  }

  public MyTypeA getSubObject() {
    return subObject;
  }

  public void firePropertyChangeEvent(String propertyName, Object oldValue, Object newValue) {
    PropertyChangeEvent event = new PropertyChangeEvent(this, propertyName, oldValue, newValue);
    for (PropertyChangeListener listener : listeners) {
      listener.propertyChange(event);
    }
  }
}
