    int totalPixelWidth = totalWidth * 256;
    float ratio = (float) pixelWidth / (float) totalPixelWidth;
    int colHeightPoints = cell.getRow().getHeight();
    int colHeight = (int) Math.round(colHeightPoints * ratio);
    row.setHeightInPoints(colHeight);
    return style;
}
