public String applyMatcherToJSON(String jsonString, String matcherString) {
    JsonElement jsonElement = JsonParser.parseString(jsonString);
    JsonElement matchingElement = null;

    if (jsonElement.isJsonObject()) {
        JsonObject jsonObject = jsonElement.getAsJsonObject();

        for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
            if (entry.getValue().toString().contains(matcherString)) {
                matchingElement = entry.getValue();
                break;
            }
        }
    } else if (jsonElement.isJsonArray()) {
        JsonArray jsonArray = jsonElement.getAsJsonArray();

        for (JsonElement element : jsonArray) {
            if (element.toString().contains(matcherString)) {
                matchingElement = element;
                break;
            }
        }
    }

    return (matchingElement != null) ? matchingElement.toString() : "";
}
