public void assignWeights(Node node) {
    if (node == null) {
        return;
    }
    if (node.isLeaf()) {
        node.setWeight(1);
    } else {
        int leftWeight = getWeight(node.getLeft());
        int rightWeight = getWeight(node.getRight());
        node.setWeight(leftWeight + rightWeight);
        assignWeights(node.getLeft());
        assignWeights(node.getRight());
    }
}

private int getWeight(Node node) {
    return node == null ? 0 : node.getWeight();
}
