public boolean addEdge(Edge e, Vertex root) {
    boolean added = false;
    if (e.getSource().equals(root) || e.getDest().equals(root)) {
        for (Edge edge : edges) {
            if ((edge.getSource().equals(e.getSource())
                    && edge.getDest().equals(e.getDest())
                    || (edge.getSource().equals(e.getDest())
                    && edge.getDest().equals(e.getSource())))) {
                edge.setWeight(e.getWeight());
                added = true;
                break;
            }
        }
        if (!added) {
            edges.add(e);
            added = true;
        }
    }
    return added;
}
