import java.util.Arrays;

public class OutlierRemover {

  public static double[] removeOutliers(double[] data) {
    double median = findMedian(data);
    double mad = findMAD(data, median);
    double threshold = 3.5 * mad;

    double[] filteredData = new double[data.length];
    int count = 0;

    for (int i = 0; i < data.length; i++) {
      if (Math.abs(data[i] - median) <= threshold) {
        filteredData[count++] = data[i];
      }
    }

    return Arrays.copyOf(filteredData, count);
  }

  private static double findMedian(double[] data) {
    Arrays.sort(data);
    int middle = data.length / 2;
    return (data.length % 2 == 1) ? data[middle] : (data[middle - 1] + data[middle]) / 2.0;
  }

  private static double findMAD(double[] data, double median) {
    double[] deviations = new double[data.length];
    for (int i = 0; i < data.length; i++) {
      deviations[i] = Math.abs(data[i] - median);
    }
    double medianDeviation = findMedian(deviations);
    return 1.4826 * medianDeviation;
  }

}
