public static int divideAndRound(int dividend, int divisor, int raise) {
   if(dividend == 0) return 0;
   int sign = ((dividend < 0) ^ (divisor < 0)) ? -1 : 1;
   long ldividend = Math.abs((long)dividend), ldivisor = Math.abs((long)divisor);
   long result = 0, remainder = 0;
   while(ldividend >= ldivisor) {
      long temp = ldivisor, tempResult = 1;
      while((temp << 1) <= ldividend) {
         temp <<= 1;
         tempResult <<= 1;
      }
      result += tempResult;
      ldividend -= temp;
   }
   if(sign == -1) result = -result;
   if(result > Integer.MAX_VALUE) return Integer.MAX_VALUE;
   else if(result < Integer.MIN_VALUE) return Integer.MIN_VALUE;
   else return (int)(result * Math.pow(10, raise) / divisor);
}
