public boolean findNextSubsequence(String pattern, String string) {
    if (pattern == null || string == null || pattern.length() > string.length()) {
        return false;
    }
    int patternIndex = 0;
    for (int i = 0; i < string.length(); i++) {
        if (string.charAt(i) == pattern.charAt(patternIndex)) {
            patternIndex++;
            if (patternIndex == pattern.length()) {
                return true;
            }
        }
    }
    return false;
}
