import org.locationtech.jts.geom.Geometry;
import org.locationtech.jts.triangulate.DelaunayTriangulationBuilder;

public static Geometry[] constructTriangleGraph(Geometry[] inputPolys) throws TopologyException {
    // Validate that all input geometries are polygons with exactly 3 vertices
    for(int i = 0; i < inputPolys.length; i++) {
        if(!inputPolys[i].getGeometryType().equals("Polygon")) {
            throw new TopologyException("Input geometry must be a polygon.");
        }
        else if(inputPolys[i].getCoordinates().length != 4) {
            throw new TopologyException("Input polygon must have exactly 3 vertices.");
        }
    }

    // Construct the Delaunay triangulation
    DelaunayTriangulationBuilder builder = new DelaunayTriangulationBuilder();
    builder.setSites(inputPolys);
    Geometry[] triangles = builder.getTriangles();

    // Find the neighbors of each polygon
    for(int i = 0; i < inputPolys.length; i++) {
        Geometry[] neighbors = new Geometry[3];
        for(int j = 0; j < triangles.length; j++) {
            if(triangles[j].intersects(inputPolys[i])) {
                int index = 0;
                for(int k = 0; k < 3; k++) {
                    if(!triangles[j].equals(inputPolys[i]) && triangles[j].touches(inputPolys[i].getBoundary().getGeometryN(k))) {
                        neighbors[index] = triangles[j];
                        index++;
                    }
                }
            }
        }
        inputPolys[i].setUserData(neighbors);
    }

    return inputPolys;
}
