public Request setAuthorizationHeader(String name, String password) {

    String credentials = name + ":" + password;
    byte[] credentialsBytes = credentials.getBytes();
    String encodedCredentials = Base64.getEncoder().encodeToString(credentialsBytes);

    String digest = null;
    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(credentialsBytes);
        byte[] digestBytes = md.digest();
        digest = DatatypeConverter.printHexBinary(digestBytes).toLowerCase();
    } catch (NoSuchAlgorithmException e) {
        e.printStackTrace();
    }

    Request request = new Request();
    request.addHeader("Authorization", "Digest username=\"" + name + "\", realm=\"default\", nonce=\"" + digest + "\"");
    return request;
}
