public List<List<Record>> splitRecordsByTuple(List<Record> batch) throws OnRecordErrorException {
    Map<List<String>, List<Record>> partitions = new HashMap<>();

    for (Record record : batch) {
        Field schemaName = record.getHeader().getAttribute(FieldDictionary.RECORD_ATTRIBUTE_SCHEMA);
        Field tableName = record.getHeader().getAttribute(FieldDictionary.RECORD_ATTRIBUTE_TABLE);

        List<String> tuple = Arrays.asList(schemaName.getValueAsString(), tableName.getValueAsString());

        if (!partitions.containsKey(tuple)) {
            partitions.put(tuple, new ArrayList<Record>());
        }

        partitions.get(tuple).add(record);
    }

    // Transform the map containing partitions into a list of lists containing records
    return partitions.values().stream().collect(Collectors.toList());
}
