public int calculateInterval(int chars) {
    int microSeconds;

    if(chars > 0 && chars <= 10) {
        microSeconds = 500;
    } else if(chars > 10 && chars <= 20) {
        microSeconds = 1000;
    } else if(chars > 20 && chars <= 30) {
        microSeconds = 2000;
    } else if(chars > 30 && chars <= 40) {
        microSeconds = 3000;
    } else {
        microSeconds = 4000;
    }

    return microSeconds;
}
