public String getCallerClassName(int i) {
    StackTraceElement[] stackTrace = Thread.currentThread().getStackTrace();
    if (i < 0 || i > stackTrace.length) {
        return null;
    }
    int index = 2; // Start after getStackTrace and getCallerClassName
    if (i != 0) {
        index += i - 1;
    }
    if (index >= stackTrace.length) {
        return null;
    }
    return stackTrace[index].getClassName();
}
