public static byte[] convertPasswordToBytes(String password, String mode) {
    byte[] passwordBytes = null;

    try {
        if(mode.equals("ASCII")) {
            passwordBytes = password.getBytes("US-ASCII");
        } else if(mode.equals("UTF-8")) {
            passwordBytes = password.getBytes("UTF-8");
        } else if(mode.equals("ISO-8859-1")) {
            passwordBytes = password.getBytes("ISO-8859-1");
        } else {
            System.out.println("Invalid mode!");
        }
    } catch (UnsupportedEncodingException e) {
        e.printStackTrace();
    }

    return passwordBytes;
}
