LocatedBlocksWithMetaInfo updateDatanodeInfo(LocatedBlocks locatedBlocks)
      throws IOException {
    if (locatedBlocks.getLocatedBlocks().size() == 0)
      return new LocatedBlocksWithMetaInfo(locatedBlocks.getFileLength(),
          locatedBlocks.getLocatedBlocks(), false,
          DataTransferProtocol.DATA_TRANSFER_VERSION, getNamespaceId(),
          this.nameNode.getClientProtocolMethodsFingerprint());
    List<LocatedBlock> newBlocks = new ArrayList<LocatedBlock>();
    readLock();
    try {
      for (LocatedBlock locBlock: locatedBlocks.getLocatedBlocks()) {
        Block block = locBlock.getBlock();
        int numNodes = blocksMap.numNodes(block);
        int numCorruptNodes = countNodes(block).corruptReplicas();
        int numCorruptReplicas = corruptReplicas.numCorruptReplicas(block); 
        if (numCorruptNodes != numCorruptReplicas) {
          LOG.warn("Inconsistent number of corrupt replicas for " + 
                   block + "blockMap has " + numCorruptNodes + 
                   " but corrupt replicas map has " + numCorruptReplicas);
        }
        boolean blockCorrupt = numCorruptNodes == numNodes;
        int numMachineSet = blockCorrupt ? numNodes : (numNodes - numCorruptNodes);
        DatanodeDescriptor[] machineSet = new DatanodeDescriptor[numMachineSet];
        if (numMachineSet > 0) {
          numNodes = 0;
          for(Iterator<DatanodeDescriptor> it = blocksMap.nodeIterator(block); 
              it.hasNext();) {
            DatanodeDescriptor dn = it.next();
            boolean replicaCorrupt = corruptReplicas.isReplicaCorrupt(block, dn);
            if (blockCorrupt || (!blockCorrupt && !replicaCorrupt))
              machineSet[numNodes++] = dn;
          }
        }






        Block blockCopy  = null;
        if (block != null) {
          blockCopy = new Block(block);
        }
        LocatedBlock newBlock = new LocatedBlock(blockCopy, machineSet, 0,
            blockCorrupt);
  newBlocks.add(newBlock);
      }
    } finally {
      readUnlock();
    }
    return new LocatedBlocksWithMetaInfo(locatedBlocks.getFileLength(),
        newBlocks, false, DataTransferProtocol.DATA_TRANSFER_VERSION,
        getNamespaceId(), this.nameNode.getClientProtocolMethodsFingerprint());
  },0

public Configuration load(String pu)
    {
        Configuration conf = new Configuration().addProperties(puMetadata.getProperties());
        String propertyFileName = externalProperties != null ? (String) externalProperties
                .get(PersistenceProperties.KUNDERA_CLIENT_PROPERTY) : null;
        if (propertyFileName == null)
        {
            propertyFileName = puMetadata != null ? puMetadata
                    .getProperty(PersistenceProperties.KUNDERA_CLIENT_PROPERTY) : null;
        }
        if (propertyFileName != null)
        {
            PropertyType fileType = PropertyType.value(propertyFileName);
            switch (fileType)
            {
            case xml:
                conf.configure(propertyFileName);
                break;
            case properties:
                Properties props = new Properties();
                InputStream ioStream = puMetadata.getClassLoader().getResourceAsStream(propertyFileName);
                if (ioStream == null)
                {
                    propertyFileName = KunderaCoreUtils.resolvePath(propertyFileName);
                    try
                    {
                        ioStream = new FileInputStream(new File(propertyFileName));
                    }
                    catch (FileNotFoundException e)
                    {
                        log.warn("File {} not found, Caused by ", propertyFileName);
                    }
                }
                try
                {
                    if (ioStream != null)
                    {
                        props.load(ioStream);
                    }
                }
                catch (IOException e)
                {
                    log.error("Skipping as error occurred while loading property file {}, Cause by : {}.",
                            propertyFileName, e);
                }
                conf.addProperties(props);
                break;
            default:
                log.error("Unsupported type{} for file{}, skipping load of properties.", fileType, propertyFileName);
                break;
            }
        }
        return conf;
    },0

