public String extractAttributeValue(String cfxdTag, String attrName) throws EvaluatorException{
    String result = "";

    try {
        Pattern pattern = Pattern.compile(attrName + "=\"(.*?)\"");
        Matcher matcher = pattern.matcher(cfxdTag);

        if (matcher.find()) {
            result = matcher.group(1);
        } else {
            throw new EvaluatorException("Attribute not found.");
        }

    } catch (Exception e) {
        throw new EvaluatorException(e.getMessage());
    }

    return result;
}
