public static double[] improveLinearSolution(double[][] A, double[] b, double[] x) {
    double[] new_x = new double[x.length];
    double error = Double.POSITIVE_INFINITY;
    double tolerance = 1e-10;
    while (error > tolerance) {
        // Perform one iteration of Gauss-Seidel method
        for (int i = 0; i < A.length; i++) {
            double sum = b[i];
            for (int j = 0; j < A[i].length; j++) {
                if (j != i) {
                    sum -= A[i][j] * new_x[j];
                }
            }
            new_x[i] = sum / A[i][i];
        }
        // Calculate error
        error = 0;
        for (int i = 0; i < x.length; i++) {
            error += Math.abs(new_x[i] - x[i]);
        }
        System.arraycopy(new_x, 0, x, 0, x.length); // copy new solution to x
    }
    return x;
}
