public List<RenderingElement> generateElements(Bond bond, RendererModel model) {

    List<RenderingElement> elements = new ArrayList<>();

    if (bond instanceof StereoBond) {
        StereoBond stereoBond = (StereoBond) bond;
        StereoBondRenderingUnit unit = new StereoBondRenderingUnit(stereoBond, model);
        elements.addAll(unit.generate());

    } else if (bond.getOrder() == 2) {
        DoubleBondRenderingUnit unit = new DoubleBondRenderingUnit(bond, model);
        elements.addAll(unit.generate());

    } else if (bond.getOrder() == 3) {
        TripleBondRenderingUnit unit = new TripleBondRenderingUnit(bond, model);
        elements.addAll(unit.generate());

    } else {
        BondRenderingUnit unit = new BondRenderingUnit(bond, model);
        elements.addAll(unit.generate());
    }

    return elements;
}
