      Enumeration<?> enumeration = props.propertyNames();
      while (enumeration.hasMoreElements()) {
        String propertyName = (String) enumeration.nextElement();
        if (propertyName.startsWith(HIVE_CONFIG_KEY_PREFIX)) {
