import com.github.benmanes.caffeine.cache.Cache;
import com.github.benmanes.caffeine.cache.Caffeine;
import io.dropwizard.lifecycle.Managed;
import org.apache.commons.pool2.ObjectPool;
import org.apache.commons.pool2.impl.GenericObjectPool;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.concurrent.TimeUnit;

public class SnowizardIdGenerator implements Managed, IdGenerator {

    private static final Logger LOG = LoggerFactory.getLogger(SnowizardIdGenerator.class);
    private static final int MAX_SLEEP_TIME = 30000;
    private static final int DEFAULT_POOL_SIZE = 2;
    private static final String SNOWIZARD_WORKER_ID = System.getProperty("snowizard.workerId", "1");
    private static final int SNOWIZARD_HOST_RETRY_SLEEP_SECONDS = Integer.getInteger("snowizard.retrySleepSeconds", 10);

    private final SnowizardClientConfig config;
    private ObjectPool<SnowizardHostPort> hostPortPool;
    private Cache<SnowizardHostPort, Boolean> unavailableHosts;
    private SnowizardHostPort lastHostPort;
    private boolean managed;

    public SnowizardIdGenerator(SnowizardClientConfig config) {
        this.config = config;
    }

    @Override
    public long getId() throws IdGeneratorException {
        SnowizardHostPort hostPort = null;
        try {
            hostPort = (lastHostPort == null) ? hostPortPool.borrowObject() : lastHostPort;
            lastHostPort = hostPort;
            long id = getIdentifierFromHostPort(hostPort);
            return (id << 10) | Long.parseLong(SNOWIZARD_WORKER_ID);
        } catch (Exception e) {
            LOG.warn("Cannot get identifier from {}: {}", hostPort, e.getMessage());
            throw new IdGeneratorException(e);
        } finally {
            if (hostPort != null) {
                if (!unavailableHosts.asMap().containsKey(hostPort)) {
                    hostPortPool.returnObject(hostPort);
                }
            }
        }
    }

    private long getIdentifierFromHostPort(SnowizardHostPort hostPort) throws Exception {
        SnowizardClient client = null;
        try {
            client = SnowizardClientFactory.getClient(hostPort.getHost(), hostPort.getPort());
            long id = client.nextId();
            if (id <= 0) {
                throw new IllegalArgumentException("Invalid ID returned: " + id);
            }
            unavailableHosts.invalidate(hostPort);
            LOG.debug("ID {} obtained from {}", id, hostPort);
            return id;
        } catch (SnowizardClientException sce) {
            unavailableHosts.put(hostPort, true);
            LOG.warn("{} when getting ID from {}", sce.getMessage(), hostPort);
            throw sce;
        } finally {
            if (client != null) {
                SnowizardClientFactory.close(client);
            }
        }
    }

    @Override
    public void start() throws Exception {
        hostPortPool = new GenericObjectPool<>(new SnowizardHostPortFactory(config), config.getMaxPoolSize(),
                GenericObjectPool.WHEN_EXHAUSTED_BLOCK, config.getHostPortSocketTimeOut(), false, true);
        unavailableHosts = Caffeine.newBuilder().expireAfterWrite(config.getUnavailableHostCacheSeconds(), TimeUnit.SECONDS).build();
        managed = true;
    }

    @Override
    public void stop() throws Exception {
        if (hostPortPool != null && managed) {
            hostPortPool.close();
        }
        unavailableHosts.invalidateAll();
    }

