import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;

public class QueryExecutor {

    public List<Object> executeQuery(String paramQuery) throws SQLException {
        Connection conn = null;
        PreparedStatement preparedStatement = null;
        ResultSet resultSet = null;
        try {
            conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydatabase", "root", "password");
            preparedStatement = conn.prepareStatement(paramQuery);
            resultSet = preparedStatement.executeQuery();
            List<Object> queryResult = new ArrayList<>();
            while (resultSet.next()) {
                Object result = resultSet.getObject(1);
                queryResult.add(result);
            }
            return queryResult;
        } catch(SQLException e){
            throw new SQLException("Error executing query: " + e.getMessage());  
        } finally {
            try {
                if (resultSet != null) resultSet.close();
                if (preparedStatement != null) preparedStatement.close();
                if (conn != null) conn.close();
            } catch (SQLException e) {
                throw new SQLException("Error closing connections: " + e.getMessage());
            }
        }
    }
}
