import java.io.*;

public class CustomObjectInputStream extends ObjectInputStream {

    public CustomObjectInputStream(InputStream in) throws IOException {
        super(in);
    }

    protected CustomObjectInputStream() throws IOException, SecurityException {
        super();
    }

    @Override
    protected ObjectStreamClass readClassDescriptor() throws IOException, ClassNotFoundException {
        ObjectStreamClass desc = super.readClassDescriptor();
        try {
            Class<?> clazz = Class.forName(desc.getName());
            java.lang.reflect.Field field = null;
            try {
                field = clazz.getDeclaredField("serialVersionUID");
            } catch (NoSuchFieldException e) {
                // ignore
            }
            if (field != null && field.getType() == long.class) {
                field.setAccessible(true);
                long uid = field.getLong(null);
                desc = ObjectStreamClass.lookup(clazz);
            }
        } catch (Exception ex) {
            // just ignore and return the original desc
        }
        return desc;
    }
}
