import org.apache.curator.framework.CuratorFramework;
import org.apache.curator.framework.CuratorFrameworkFactory;
import org.apache.curator.retry.ExponentialBackoffRetry;
import org.apache.curator.utils.CloseableUtils;

public CuratorFramework startCuratorFramework(Configuration configuration) throws Exception {
    CuratorFramework curator;
    String zookeeperQuorum = configuration.getZookeeperQuorum();
    int sessionTimeout = configuration.getSessionTimeout();
    int connectionTimeout = configuration.getConnectionTimeout();
    int maxRetries = configuration.getMaxRetries();
    int baseSleepTimeMs = configuration.getBaseSleepTimeMs();

    ExponentialBackoffRetry retryPolicy = new ExponentialBackoffRetry(baseSleepTimeMs, maxRetries);

    curator = CuratorFrameworkFactory.builder()
            .connectString(zookeeperQuorum)
            .sessionTimeoutMs(sessionTimeout)
            .connectionTimeoutMs(connectionTimeout)
            .retryPolicy(retryPolicy)
            .build();

    curator.start();

    return curator;
}
