public void consumeTokenUntilFunctionBalanced(List<Token> tokens, Token follow) throws Exception {
    int openBrackets = 0;

    for (Token token : tokens) {
        if (follow.equals(token) && openBrackets == 0) {
            // match found, consume the token
            return;
        } else if (token.getTokenType() == TokenType.LEFT_BRACKET) {
            // increase open brackets count
            openBrackets++;
        } else if (token.getTokenType() == TokenType.RIGHT_BRACKET) {
            // decrease open brackets count
            openBrackets--;
        }
    }

    throw new Exception("Function not balanced.");
}
