public <T> void quicksort(List<T> list, Comparator<? super T> c) {
    quicksortHelper(list, 0, list.size() - 1, c);
}

private static <T> void quicksortHelper(List<T> list, int left, int right, Comparator<? super T> c) {
    if (left < right) {
        int pivotIndex = partition(list, left, right, c);
        quicksortHelper(list, left, pivotIndex - 1, c);
        quicksortHelper(list, pivotIndex + 1, right, c);
    }
}

private static <T> int partition(List<T> list, int left, int right, Comparator<? super T> c) {
    T pivot = list.get(right);
    int i = left - 1;
    for (int j = left; j < right; j++) {
        if (c.compare(list.get(j), pivot) < 0) {
            i++;
            swap(list, i, j);
        }
    }
    swap(list, i + 1, right);
    return i + 1;
}

private static <T> void swap(List<T> list, int i, int j) {
    T temp = list.get(i);
    list.set(i, list.get(j));
    list.set(j, temp);
}
