public EventBuilder buildEvent(LogRecord record) {
   EventBuilder eventBuilder = new EventBuilder(); 
   // add required details from the LogRecord to the eventBuilder 
   eventBuilder.setLevel(record.getLevel().toString());
   eventBuilder.setMessage(record.getMessage());
   eventBuilder.setLoggerName(record.getLoggerName());

   // add additional details based on log record's parameters and exception (if any)
   Object[] parameters = record.getParameters();
   if (parameters != null && parameters.length > 0) {
      eventBuilder.setParameters(Arrays.toString(parameters));
   }

   Throwable thrown = record.getThrown();
   if (thrown != null) {
      StringWriter sw = new StringWriter();
      PrintWriter pw = new PrintWriter(sw);
      thrown.printStackTrace(pw);
      eventBuilder.setException(sw.toString());
   }
   return eventBuilder;
}
