public static <T> OngoingStubbing<T> when(Class<T> classToMock) throws Exception {
    Method[] declaredMethods = classToMock.getDeclaredMethods();
    for (Method method : declaredMethods) {
        if (Modifier.isStatic(method.getModifiers()) && Modifier.isPrivate(method.getModifiers())) {
            method.setAccessible(true);
            PowerMockito.stub(PowerMockito.method(classToMock, method.getName())).toReturn(null);
        }
    }
    return PowerMockito.when(classToMock.newInstance());
}
