public void removeAsyncConsumer(MessageConsumer consumer) throws JMSException {
    if (consumer != null && consumer.getMessageListener() != null) {
        consumer.setMessageListener(null);
        if (consumer.getSession().getTransacted()) {
            consumer.getSession().commit();
        }
        consumer.getSession().close();
        consumer.getSession().createConsumer(consumer.getDestination()).setMessageListener(consumer.getMessageListener());
        consumer.getSession().start();
    }
}
