public <T> T getInstance() throws ProvideException {
        T instance;

        if (scopeCache != null && scopeCache.has(getType())) {
            instance = scopeCache.get(getType());
        } else {
            try {
                instance = constructor.newInstance();
            } catch (InstantiationException | IllegalAccessException | IllegalArgumentException | InvocationTargetException e) {
                throw new ProvideException("Exception thrown during constructing the object", e);
            }
            if (scopeCache != null) {
                scopeCache.put(getType(), instance);
            }
        }

        return instance;
    }
