public void convertValueByType(Object devStateValue, DeviceData deviceDataArgin, AttrDataFormat dataType) throws DevFailed {
    try {
        switch (dataType) {
            case AttrEncoded:
                deviceDataArgin.insert(devStateValue.toString());
                break;
            case AttrString:
                deviceDataArgin.insert(devStateValue.toString());
                break;
            case AttrDouble:
                deviceDataArgin.insert(Double.parseDouble(devStateValue.toString()));
                break;
            case AttrFloat:
                deviceDataArgin.insert(Float.parseFloat(devStateValue.toString()));
                break;
            case AttrInteger:
                deviceDataArgin.insert(Integer.parseInt(devStateValue.toString()));
                break;
            case AttrShort:
                deviceDataArgin.insert(Short.parseShort(devStateValue.toString()));
                break;
            case AttrLong:
                deviceDataArgin.insert(Long.parseLong(devStateValue.toString()));
                break;
            case AttrBoolean:
                deviceDataArgin.insert(Boolean.parseBoolean(devStateValue.toString()));
                break;
            default:
                throw new DevFailed("AttrDataFormat not recognized");
        }
    } catch (NumberFormatException nfe) {
        throw new DevFailed("Conversion error: " + nfe.getMessage());
    }
}
