import java.util.Map;

public class FrameHtmlSource {

  public Map<String, String> getFrameHtmlSource(FrameNode currentFrame, String currFrameId) {
    WebDriver driver = new FirefoxDriver();
    driver.switchTo().frame(currentFrame.getFrameElement());
    Map<String, String> frameSources = new HashMap<>();
    String currentFrameSource = "";
    try {
      currentFrameSource = driver.getPageSource();
    } catch (Exception e) {
      e.printStackTrace();
    }
    frameSources.put(currFrameId, currentFrameSource);
    List<WebElement> frames = driver.findElements(By.tagName("frame"));
    for (WebElement frame : frames) {
      String frameId = frame.getAttribute("id");
      if (frameId == null) {
        frameId = frame.getAttribute("name");
        if (frameId == null) {
          frameId = "frame_" + frame.hashCode();
        }
      }
      FrameNode childFrame = new FrameNode();
      childFrame.setFrameElement(frame);
      Map<String, String> childFrameSources = getFrameHtmlSource(childFrame, frameId);
      frameSources.putAll(childFrameSources);
    }
    driver.switchTo().parentFrame();
    return frameSources;
  }

  private static class FrameNode {
    private WebElement frameElement;

    public WebElement getFrameElement() {
      return frameElement;
    }

    public void setFrameElement(WebElement frameElement) {
      this.frameElement = frameElement;
    }
  }
}

