    long startTime = System.currentTimeMillis();
    while (value == null && System.currentTimeMillis() - startTime < unit.toMillis(timeout)) {
        value = getValue(k);
        if (value == null) {
            Thread.sleep(100); // wait to try again
        }
    }
    if (value == null) {
        throw new TimeoutException();
    }
    return value;
}

