public byte[] decodeLTPAToken(CODEC codec, byte[] token_arr) {
    byte[] result = null;
    try {
        byte[] gss_token_bytes = codec.decode(token_arr);
        ByteBuffer gss_token_buffer = ByteBuffer.wrap(gss_token_bytes);
        byte[] oid_bytes = new byte[6];
        gss_token_buffer.get(oid_bytes);
        String oid = new String(oid_bytes, "UTF-8");
        if ("1.2.840.113554.1.2.2.2".equals(oid)) {
            byte[] reserved = new byte[2];
            gss_token_buffer.get(reserved);
            int token_len = gss_token_buffer.getInt();
            if (token_len > 0) {
                byte[] token_data = new byte[token_len];
                gss_token_buffer.get(token_data);
                result = codec.decode(token_data);
            }
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
    return result;
}
