public static Object transformData(Object input, int from, int to) {
    Chainr chainrSpec = // Initialize chainrSpec with appropriate values
    List<Object> chainrSpecList = chainrSpec.getChainrSpec();
    if (from < 0 || to >= chainrSpecList.size() || from >= to) {
        throw new IllegalArgumentException("Invalid from/to parameters");
    }
    List<Object> subChainrSpec = chainrSpecList.subList(from, to);
    Chainr subChainr = Chainr.fromSpec(subChainrSpec);
    return subChainr.transform(input);
}
