public View findEmptyView(View rootView) {
    if (rootView == null) {
        throw new RuntimeException("Root view is null.");
    }

    if (rootView instanceof ViewGroup) {
        ViewGroup rootGroup = (ViewGroup) rootView;
        for (int i = 0; i < rootGroup.getChildCount(); i++) {
            View childView = rootGroup.getChildAt(i);
            if (childView instanceof ViewGroup) {
                View emptyView = findEmptyView(childView);
                if (emptyView != null) {
                    return emptyView;
                }
            } else if (childView instanceof TextView && ((TextView) childView).getText().length() == 0) {
                return childView;
            }
        }
    }

    return null;
}
