            "            <infCons>\n" +
            "               <xServ>CONS-CAD</xServ>\n" +
            "               <UF>" + uf + "</UF>\n" +
            "               <CNPJ>" + cnpj + "</CNPJ>\n" +
            "            </infCons>\n" +
            "         </consCad>\n" +
            "      </ws:consultaCadastro2>\n" +
            "   </soapenv:Body>\n" +
            "</soapenv:Envelope>";

    // create connection to SEFAZ webservice
    String endpoint = "https://www.sefaz." + uf.toLowerCase() + ".gov.br/nfe/services/CadConsulta2";
    URL url = new URL(endpoint);
    HttpsURLConnection conn = (HttpsURLConnection) url.openConnection();
    conn.setRequestMethod("POST");
    conn.setRequestProperty("Content-Type", "text/xml; charset=utf-8");
    conn.setDoOutput(true);

    // send request
    OutputStream os = conn.getOutputStream();
    os.write(xmlRequest.getBytes());
    os.flush();

    // read response
    InputStream is = conn.getInputStream();
    BufferedReader reader = new BufferedReader(new InputStreamReader(is));
    StringBuilder stringBuilder = new StringBuilder();
    String line = null;

    while ((line = reader.readLine()) != null) {
        stringBuilder.append(line);
    }

    String xmlResponse = stringBuilder.toString();

    return xmlResponse;
}
