public double getOxygenFamilyPredictionResult(double[] resultsH) {
    double[] coefficients = {0.19286, 2.59480, 0.90479, -0.92748, -1.17770, -0.48583, -0.26544, -0.30887, 1.05150};
    double intercept = 0.26955;
    double prediction = 0.0;

    for (int i = 0; i < resultsH.length; i++) {
        prediction += coefficients[i] * resultsH[i];
    }

    prediction += intercept;

    return prediction;
}
