public Bundle getBundleForResourceAdapter(ResourceAdapter resourceAdapter) throws ConfigEvaluatorException {
    BundleContext bundleContext = FrameworkUtil.getBundle(ResourceAdapter.class).getBundleContext();
    ServiceReference<ManagedServiceFactory> serviceReference = bundleContext.getServiceReference(ManagedServiceFactory.class);
    ManagedServiceFactory serviceFactory = bundleContext.getService(serviceReference);
    Dictionary<String, String> properties = new Hashtable<>();
    properties.put("service.pid", resourceAdapter.getClass().getName());
    try {
        Configuration configuration = serviceFactory.createService(null, null);
        configuration.update(properties);
        return configuration.getBundle();
    } catch (ConfigurationException e) {
        throw new ConfigEvaluatorException("Could not retrieve the bundle where the resource adapter's Metatype Information exists", e);
    }
}
