/**
 * Sets this to a skew by the specified amount relative to the given plane.
 *
 * @param amount the amount of skew to apply
 * @param plane the plane to skew relative to
 * @return a reference to this matrix, for chaining
 */
public Matrix setSkew(float amount, Plane plane) {
    float[] normal = plane.getNormal();
    float x = normal[0];
    float y = normal[1];
    float z = normal[2];

    float xy = x * y;
    float xz = x * z;
    float yz = y * z;

    float[] elements = getElements();
    elements[0] += amount * (-xy);
    elements[1] += amount * (-xz);
    elements[2] += amount * x;
    elements[3] += amount * (-yz);
    elements[4] += amount * y;
    elements[5] += amount * z;

    return this;
}
