public List<String> getBanners(String urlString) throws com.omertron.thetvdbapi.TvDbException{
    List<String> banners = new ArrayList<>();
    URL url;
    try {
        url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        BufferedReader in = new BufferedReader(
                new InputStreamReader(connection.getInputStream()));
        String inputLine;
        StringBuilder content = new StringBuilder();
        while ((inputLine = in.readLine()) != null) {
            content.append(inputLine);
        }
        in.close();
        Pattern pattern = Pattern.compile("<img src=\"(.*?)\"");
        Matcher matcher = pattern.matcher(content);
        while (matcher.find()) {
            String banner = matcher.group(1);
            if (!banners.contains(banner)) {
                banners.add(banner);
            }
        }

    } catch (MalformedURLException e) {
        throw new com.omertron.thetvdbapi.TvDbException("Invalid URL");
    } catch (IOException e) {
        throw new com.omertron.thetvdbapi.TvDbException("Unable to connect to URL");
    }
    return banners;  
}
