public class JobSpecMaterializer {
    public void addNewJobSpec(JobSpec jobSpec) {
        try {
            // create a new file in the same directory as the main program
            String filename = jobSpec.getUri();
            File file = new File(filename);

            // write the content of the jobSpec object into the file
            FileWriter writer = new FileWriter(file);
            writer.write(jobSpec.toString());
            writer.close();

            System.out.println("JobSpec materialized into file: " + filename);
        } catch (IOException e) {
            System.out.println("An error occurred while materializing the JobSpec.");
            e.printStackTrace();
        }
    }
}
