import javax.jms.ConnectionFactory;
import javax.jms.JMSException;
import javax.jms.Message;
import javax.jms.Queue;
import javax.jms.QueueBrowser;
import javax.jms.Session;
import javax.jms.TextMessage;
import javax.naming.InitialContext;
import javax.naming.NamingException;

public boolean verifyBackoutQueueIsEmpty(String queueName) throws NamingException, JMSException {
    boolean queueIsEmpty = false;

    InitialContext initialContext = new InitialContext();
    ConnectionFactory connectionFactory = (ConnectionFactory) initialContext.lookup("jms/ConnectionFactory");
    Queue queue = (Queue) initialContext.lookup(queueName);

    try {
        Session session = connectionFactory.createConnection().createSession();
        QueueBrowser browser = session.createBrowser(queue);

        for (Enumeration<Message> msgs = browser.getEnumeration(); msgs.hasMoreElements();) {
            TextMessage message = (TextMessage) msgs.nextElement();        
            if (message.getJMSRedelivered()) { // Message delivered before, indicates a backout.
                return false;
            }
        }
        queueIsEmpty = true; // no messages found in the backout queue.
    }
    catch (JMSException jmse) {
        //Print error log if needed.
    }
    return queueIsEmpty;
}
