import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public List<Field> getClassFields(Class<?> beanClass) {
    List<Field> fields = new ArrayList<>();
    while (beanClass != null) {
        fields.addAll(Arrays.asList(beanClass.getDeclaredFields()));
        beanClass = beanClass.getSuperclass();
    }
    filtersyntheticFields(fields);
    return fields;
}

private void filtersyntheticFields(List<Field> fields){
    fields.removeIf(field -> field.isSynthetic());
}
