public List<NSMode> getNSModes() {
    List<NSMode> nsmodes = new ArrayList<NSMode>();
    try {
        String nsmodeURL = "http://netscalerip/nitro/v1/config/nsmode";
        HttpClient client = HttpClientBuilder.create().build();
        HttpGet request = new HttpGet(nsmodeURL);
        request.setHeader("Authorization", "Basic " + getEncodedCredentials());
        HttpResponse response = client.execute(request);

        int statusCode = response.getStatusLine().getStatusCode();
        if (statusCode == HttpStatus.SC_OK) {
            String responseBody = EntityUtils.toString(response.getEntity());
            JSONObject nsmodeRespJsonObj = new JSONObject(responseBody);
            if (nsmodeRespJsonObj.has("nsmode")) {
                JSONArray nsmodeArray = nsmodeRespJsonObj.getJSONArray("nsmode");
                for (int i = 0; i < nsmodeArray.length(); i++) {
                    JSONObject nsmodeJsonObj = nsmodeArray.getJSONObject(i);
                    NSMode nsmode = new NSMode(
                        nsmodeJsonObj.getString("name"),
                        nsmodeJsonObj.optString("comment"));
                    nsmodes.add(nsmode);
                }
            }
        } else {
            throw new RuntimeException("Failed to fetch nsmode resources. Status code: " + statusCode);
        }
    } catch (Exception e) {
        throw new RuntimeException("Error occurred while fetching nsmode resources.", e);
    }
    return nsmodes;
}

class NSMode {
    private final String name;
    private final String comment;

    public NSMode(String name, String comment) {
        this.name = name;
        this.comment = comment;
    }

    public String getName() {
        return name;
    }

    public String getComment() {
        return comment;
    }
}

