public List<EntityMetaData> getWholeTreeDependencies(EntityMetaData entityTypeNode) {
    List<EntityMetaData> dependencies = new ArrayList<EntityMetaData>();
    traverseDependencies(entityTypeNode, dependencies);
    return dependencies;
}

private void traverseDependencies(EntityMetaData entityTypeNode, List<EntityMetaData> dependencies) {
    dependencies.add(entityTypeNode);
    for (EntityMetaData dependency : entityTypeNode.getDependencies()) {
        traverseDependencies(dependency, dependencies);
    }
}
