import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.fs.FileSystem;
import org.apache.hadoop.fs.Path;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.KeyStore;
import java.security.KeyStoreException;
import java.security.NoSuchAlgorithmException;
import java.security.cert.CertificateException;

public void storeKeyStoreOnHDFS(String path, String keyStorePassword) throws KeyStoreException,
        NoSuchAlgorithmException, CertificateException, IOException {

    // Load keystore file.
    KeyStore keyStore = KeyStore.getInstance("JKS");
    FileInputStream inputStream = new FileInputStream(path);
    keyStore.load(inputStream, keyStorePassword.toCharArray());
    inputStream.close();

    // Write the keystore to HDFS.
    Configuration conf = new Configuration();
    FileSystem fs = FileSystem.get(conf);
    Path hdfsPath = new Path("path_on_hdfs");
    if (fs.exists(hdfsPath)) {
        fs.delete(hdfsPath, true);
    }
    fs.create(hdfsPath).close();
    keyStore.store(fs.create(hdfsPath), keyStorePassword.toCharArray());
}
