public void setBackground(int color) {
    // Set the background to a RGB or HSB and alpha value
    // where color is the RGB or HSB value of the background
    // Here, I am assuming that the value of color is in the format of 0xAARRGGBB (hex)
    float alpha = ((float) ((color >> 24) & 0xFF)) / 255.0f;
    float red = ((float) ((color >> 16) & 0xFF)) / 255.0f;
    float green = ((float) ((color >> 8) & 0xFF)) / 255.0f;
    float blue = ((float) ((color) & 0xFF)) / 255.0f;
    setBackground(new Color(red, green, blue, alpha));
}
