        for (int i = 0; i < pieces.length; i++) {
            bytes[i*2] = (byte)((pieces[i] >> 8) & 0xFF);
            bytes[i*2+1] = (byte)(pieces[i] & 0xFF);
        }
        try {
            return InetAddress.getByAddress(bytes);
        } catch (UnknownHostException e) {

            throw new RuntimeException("BUG", e);
        }
