        return false;
    for (GenericsType genericType : node.getGenericsTypes()) {
        if (genericType.isPlaceholder())
            return true;
        if (genericType.getType() != null && isUsingPlaceholderInGenerics(genericType.getType()))
            return true;
    }
    return false;
}
