public static boolean compareStrings(int offset_1, int offset_2, ByteBuffer bb) {
    if (offset_1 < 0 || offset_2 < 0) {
        throw new IllegalArgumentException("Offset values should be non-negative integers.");
    }
    if (offset_1 >= bb.limit() || offset_2 >= bb.limit()) {
        throw new IndexOutOfBoundsException("Offset values exceed the buffer limit.");
    }
    byte[] bytes1 = new byte[bb.limit() - offset_1];
    byte[] bytes2 = new byte[bb.limit() - offset_2];
    bb.position(offset_1);
    bb.get(bytes1);
    bb.position(offset_2);
    bb.get(bytes2);
    return Arrays.equals(bytes1, bytes2);
}
