public static boolean isOverridden(Object instance, Method origin) {
    Class<?> clazz = instance.getClass();
    while (clazz != null) {
        try {
            clazz.getDeclaredMethod(origin.getName(), origin.getParameterTypes());
            return true;
        } catch (NoSuchMethodException e) {
            clazz = clazz.getSuperclass();
        }
    }
    return false;
}
