public void swapNodes(TreeNode root, int a, int b) {
  // Find node corresponding to index a
  TreeNode nodeA = findNode(root, a);

  // Find node corresponding to index b
  TreeNode nodeB = findNode(root, b);

  if(nodeA == null || nodeB == null) {
    // One or both nodes were not found
    throw new IllegalArgumentException("Invalid node index");
  }

  // Swap the values of the two nodes
  int tempValue = nodeA.value;
  nodeA.value = nodeB.value;
  nodeB.value = tempValue;
}

private TreeNode findNode(TreeNode node, int index) {
  if(node == null) {
    return null;
  }

  if(node.value == index) {
    return node;
  }

  TreeNode leftResult = findNode(node.leftChild, index);
  if(leftResult != null) {
    return leftResult;
  }

  TreeNode rightResult = findNode(node.rightChild, index);
  if(rightResult != null) {
    return rightResult;
  }

  return null;
}
