public boolean checkVisibility(Configuration config, ItemInfo info, RenderingScope scope) {
    boolean isHidden = false;
    if (config.hasKey("hidden")) {
        isHidden = config.getBoolean("hidden");
    } else if (config.hasKey("bundles")) {
        Configuration bundles = config.getConfig("bundles");
        if (bundles.hasKey(info.getBundleName())) {
            Configuration bundleConfig = bundles.getConfig(info.getBundleName());
            if (bundleConfig.hasKey("hidden-" + scope.toString().toLowerCase())) {
                isHidden = bundleConfig.getBoolean("hidden-" + scope.toString().toLowerCase());
            } else if (bundleConfig.hasKey("hidden")) {
                isHidden = bundleConfig.getBoolean("hidden");
            }
        }
    }
    return isHidden;
}
