public Class<?> getJavaType(String protoType) throws IllegalArgumentException {
    switch(protoType) {
        case "int":
        case "sint32":
        case "sfixed32":
        case "uint32":
        case "fixed32":
            return Integer.class;
        case "long":
        case "sint64":
        case "sfixed64":
        case "uint64":
        case "fixed64":
            return Long.class;
        case "string":
            return String.class;
        case "bool":
            return Boolean.class;
        case "float":
            return Float.class;
        case "double":
            return Double.class;
        case "bytes":
            return byte[].class;
        default:
            throw new IllegalArgumentException("Unknown protoType: " + protoType);
    }
}
