import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class DitaHRefUpdater {

    public static void updateHRefs(String ditaMapPath, String oldPrefix, String newPrefix) throws IOException {

        // Update href attributes in DITA map file
        updateHRefsInFile(ditaMapPath, oldPrefix, newPrefix);

        // Get a list of all DITA topic files referenced in DITA map
        List<String> topicFiles = getTopicFilesFromDitaMap(ditaMapPath);

        // Update href attributes in each DITA topic file
        for (String topicFilePath : topicFiles) {
            updateHRefsInFile(topicFilePath, oldPrefix, newPrefix);
        }
    }

    private static void updateHRefsInFile(String filePath, String oldPrefix, String newPrefix) throws IOException {
        Path path = Paths.get(filePath);
        List<String> lines = Files.readAllLines(path, StandardCharsets.UTF_8);
        boolean fileChanged = false;

        for (int i = 0; i < lines.size(); i++) {
            String line = lines.get(i);
            if (line.contains("href=\"") && line.contains(oldPrefix)) {
                String updatedLine = line.replace(oldPrefix, newPrefix);
                lines.set(i, updatedLine);
                fileChanged = true;
            }
        }

        if (fileChanged) {
            Files.write(path, lines, StandardCharsets.UTF_8);
            System.out.println("File updated: " + filePath);
        }
    }

    private static List<String> getTopicFilesFromDitaMap(String ditaMapPath) throws IOException {
        List<String> topicFiles = new ArrayList<>();

        Path path = Paths.get(ditaMapPath);
        List<String> lines = Files.readAllLines(path, StandardCharsets.UTF_8);

        for (String line : lines) {
            if (line.contains(".dita\"")) {
                int startPos = line.indexOf("\"") + 1;
                int endPos = line.indexOf(".dita\"") + 5;
                String topicFile = line.substring(startPos, endPos);
                topicFiles.add(topicFile);
            }
        }

        return topicFiles;
    }

}
