public static char unescapeCharAtIndex(String s, int i) {
    if (s == null || i < 0 || i >= s.length()) {
        throw new IllegalArgumentException("Invalid input.");
    }
    if (s.charAt(i) != '\\') {
        return s.charAt(i);
    }
    int j = i + 1;
    if (j >= s.length()) {
        throw new IllegalArgumentException("Invalid input.");
    }
    char c = s.charAt(j);
    if (c == 't') {
        return '\t';
    } else if (c == 'r') {
        return '\r';
    } else if (c == 'n') {
        return '\n';
    } else {
        return c;
    }
}
