public void refreshAmazonInfo() {
    try {
        AmazonEC2MetadataUtils.InstanceInfo info = AmazonEC2MetadataUtils.getInstanceInfo();
        String hostname = info.getPublicHostname();
        String instanceId = info.getInstanceId();
        String instanceType = info.getInstanceType();
        String availabilityZone = info.getAvailabilityZone();
        AmazonInfo.Builder builder = AmazonInfo.Builder.newBuilder();
        builder.addMetadata(AmazonInfo.MetaDataKey.publicHostname.getName(), hostname);
        builder.addMetadata(AmazonInfo.MetaDataKey.instanceId.getName(), instanceId);
        builder.addMetadata(AmazonInfo.MetaDataKey.instanceType.getName(), instanceType);
        builder.addMetadata(AmazonInfo.MetaDataKey.availabilityZone.getName(), availabilityZone);
        AmazonInfo amazonInfo = builder.build();
        ConfigurationManager.getConfigInstance().setProperty("AmazonInfo." + AmazonInfo.MetaDataKey.publicHostname.getName(), hostname);
        ConfigurationManager.getConfigInstance().setProperty("AmazonInfo." + AmazonInfo.MetaDataKey.instanceId.getName(), instanceId);
        ConfigurationManager.getConfigInstance().setProperty("AmazonInfo." + AmazonInfo.MetaDataKey.instanceType.getName(), instanceType);
        ConfigurationManager.getConfigInstance().setProperty("AmazonInfo." + AmazonInfo.MetaDataKey.availabilityZone.getName(), availabilityZone);
        ConfigurationManager.getConfigInstance().setInstance(amazonInfo);
    } catch (IOException e) {
        //handle exceptions
    }
}
