public void setFrameFromDiagonal(double x1, double y1, double x2, double y2) {
    double newX, newY, newWidth, newHeight;

    if (x1 < x2) {
        newX = x1;
        newWidth = x2 - x1;
    }
    else {
        newX = x2;
        newWidth = x1 - x2;
    }
    if (y1 < y2) {
        newY = y1;
        newHeight = y2 - y1;
    }
    else {
        newY = y2;
        newHeight = y1 - y2;
    }
    setFrame(newX, newY, newWidth, newHeight);
}
