public String updateTriples(String path, InputStream updatedProperties, String contentType) throws FedoraException {
    String url = "http://example.com/fedora/rest/" + path;

    try {
        HttpClient client = HttpClientBuilder.create().build();
        HttpPut putRequest = new HttpPut(url);
        putRequest.setHeader(HttpHeaders.CONTENT_TYPE, contentType);

        HttpEntity entity = EntityBuilder.create().setStream(updatedProperties).build();
        putRequest.setEntity(entity);

        HttpResponse response = client.execute(putRequest);

        int statusCode = response.getStatusLine().getStatusCode();
        if (statusCode == HttpStatus.SC_OK) {
            return "success";
        } else {
            throw new FedoraException("Failed to update triples. Status code: " + statusCode);
        }
    } catch (IOException ex) {
        throw new FedoraException("Failed to update triples. Exception: " + ex.getMessage());
    }
}
