public static int[][] generateRandomMatrix(int rows, int columns, int min, int max, Random rng) {
    int[][] matrix = new int[rows][columns];
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < columns; j++) {
            matrix[i][j] = rng.nextInt(max - min + 1) + min;
        }
    }
    return matrix;
}
