import java.io.*;
import java.nio.file.*;
import java.util.zip.*;

public void extractFromZip(String path, String dest, String fileName) throws IOException {
    File destDir = new File(dest);
    if (!destDir.exists()) {
        destDir.mkdirs();
    }
    try (ZipInputStream zipIn = new ZipInputStream(new FileInputStream(path))) {
        ZipEntry entry = zipIn.getNextEntry();
        while (entry != null) {
            String filePath = dest + File.separator + entry.getName();
            if (entry.getName().equals(fileName)) {
                if (!entry.isDirectory()) {
                    extractFile(zipIn, filePath);
                }
            }
            zipIn.closeEntry();
            entry = zipIn.getNextEntry();
        }
    }
}

private static void extractFile(ZipInputStream zipIn, String filePath) throws IOException {
    BufferedOutputStream bos = new BufferedOutputStream(new FileOutputStream(filePath));
    byte[] bytesIn = new byte[4096];
    int read;
    while ((read = zipIn.read(bytesIn)) != -1) {
        bos.write(bytesIn, 0, read);
    }
    bos.close();
}
