public FunctionLib loadFunctionLib(File res, SAXParser saxParser) throws FunctionLibException {
    FunctionLib functionLib = null;
    try {
        SAXParserFactory factory = SAXParserFactory.newInstance();
        saxParser = factory.newSAXParser();
        XMLReader xmlReader = saxParser.getXMLReader();
        FunctionLibHandler functionLibHandler = new FunctionLibHandler();
        xmlReader.setContentHandler(functionLibHandler);
        xmlReader.parse(new InputSource(new FileInputStream(res)));
        functionLib = functionLibHandler.getFunctionLib();
    } catch (ParserConfigurationException | SAXException | IOException e) {
        throw new FunctionLibException("Error loading FunctionLib: " + e.getMessage());
    }
    return functionLib;
}
