import java.util.Map;

public class JsonDeserializer<T> {

    private final Class<T> clazz;

    public JsonDeserializer(Class<T> clazz) {
        this.clazz = clazz;
    }

    public T deserialize(Map<String, Object> json) {
        // Create a new instance of the target class
        T object = null;
        try {
            object = clazz.getDeclaredConstructor().newInstance();
        } catch (Exception e) {
            e.printStackTrace();
        }

        // Set each field of the object with the corresponding value from the JSON
        json.forEach((name, value) -> {
            try {
                clazz.getDeclaredField(name).set(object, value);
            } catch (Exception e) {
                e.printStackTrace();
            }
        });

        return object;
    }
}
