public String getFullMethodName(Method method) {
    StringBuilder sb = new StringBuilder();
    sb.append(method.getReturnType().getSimpleName()).append(" "); // append return type
    sb.append(method.getName()).append("("); // append method name
    Class[] parameterTypes = method.getParameterTypes(); // append parameter types
    for(int i = 0; i < parameterTypes.length; i++) {
        sb.append(parameterTypes[i].getSimpleName());
        if(i != parameterTypes.length - 1) {
            sb.append(", ");
        }
    }
    sb.append(")");
    return sb.toString();
}
