public Map<String, String> extractNameValuePairs(char[] chars, char separator) {
    Map<String, String> map = new HashMap<>();
    StringBuilder name = new StringBuilder();
    StringBuilder value = new StringBuilder();
    boolean isName = true;
    for (char c : chars) {
        if (c == separator) {
            isName = false;
            continue;
        }
        if (c == '\n') {
            map.put(name.toString(), value.toString());
            name = new StringBuilder();
            value = new StringBuilder();
            isName = true;
            continue;
        }
        if (isName) {
            name.append(c);
        } else {
            value.append(c);
        }
    }
    return map;
}
