public byte[] getBytesForValue(String jpaFieldName, EntityMetadata m, Object value) {
    ColumnMetadata column = m.getColumnMetadata(jpaFieldName);
    DataType dataType = column.getDataType();
    ByteArrayOutputStream bos = new ByteArrayOutputStream();
    try {
        switch (dataType) {
            case BYTE_ARRAY:
                bos.write((byte[]) value);
                break;
            case STRING:
                bos.write(((String) value).getBytes(StandardCharsets.UTF_8));
                break;
            case INTEGER:
                bos.write(ByteBuffer.allocate(Integer.BYTES).putInt((Integer) value).array());
                break;
            case LONG:
                bos.write(ByteBuffer.allocate(Long.BYTES).putLong((Long) value).array());
                break;
            case BOOLEAN:
                bos.write(ByteBuffer.allocate(Character.BYTES).putChar((Boolean) value ? 1 : 0).array());
                break;
            case DATE:
                bos.write(ByteBuffer.allocate(Long.BYTES).putLong(((Date) value).getTime()).array());
                break;
            case DECIMAL:
                BigDecimal decimal = (BigDecimal) value;
                bos.write(ByteBuffer.allocate(Long.BYTES).putLong(decimal.unscaledValue().longValue()).array());
                bos.write(decimal.scale());
                break;
            default:
                throw new IllegalArgumentException("Unsupported data type: " + dataType);
        }
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
    return bos.toByteArray();
}
