public void writeSfFileWithDigest(Manifest manifest, MessageDigest digest, OutputStream outputStream) throws IOException {
    final Attributes attributes = manifest.getMainAttributes();
    final Set<String> keys = attributes.keySet();

    final ByteArrayOutputStream buffer = new ByteArrayOutputStream();
    final BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(buffer, "UTF-8"));

    // Write the main section heading
    writer.write("Signature-Version: 1.0\r\n");

    for (String key : keys) {
        if (key.endsWith("-Digest-Manifest")) {
            continue;
        }
        writeAttribute(key, attributes.getValue(key), writer);
    }

    writer.flush();
    buffer.flush();

    // Write the body digest
    final byte[] bodyBytes = buffer.toByteArray();
    final byte[] bodyDigest = digest.digest(bodyBytes);

    outputStream.write("SHA1-Digest-Manifest: ".getBytes("UTF-8"));
    outputStream.write(Base64.getEncoder().encode(bodyDigest));
    outputStream.write("\r\n\r\n".getBytes("UTF-8"));
}

private void writeAttribute(String key, String value, BufferedWriter writer) throws IOException {
    // Do not write the Name attribute, as it is implied by the section
    if (key.equalsIgnoreCase(Name)) {
        return;
    }

    writer.write(key + ": " + value + "\r\n");
}
