import javax.ws.rs.core.Response;

public Response uncheckout(Session session, String path) {
    // Check if the resource exists
    if (!resourceExist(session, path)) {
        return Response.status(Response.Status.NOT_FOUND).build();
    }

    // Check if the resource is currently checked out
    if (!isCheckedOut(session, path)) {
        return Response.status(Response.Status.CONFLICT).entity("The resource is not currently checked out").build();
    }

    // Uncheckout the resource
    DavResource resource = getResource(session, path);
    try {
        resource.getComplianceClass().getUncheckout().execute(resource, null);
    } catch (DavException e) {
        return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Failed to uncheckout the resource").build();
    }

    // Return a success response
    return Response.ok().build();
}

private boolean resourceExist(Session session, String path) {
    // Check if the resource exists
    try {
        DavResource resource = getResource(session, path);
        return resource.exists();
    } catch (DavException e) {
        return false;
    }
}

private boolean isCheckedOut(Session session, String path) {
    // Check if the resource is currently checked out
    try {
        DavResource resource = getResource(session, path);
        return resource.isLocked() && resource.getLock().isExclusive() && resource.getLock().getOwner().equals(session.getUserPrincipal().getName());
    } catch (DavException e) {
        return false;
    }
}

private DavResource getResource(Session session, String path) throws DavException {
    // Get the DavResource object for the given path
    DavResourceLocator locator = session.getWorkspace().getLocatorFactory().createResourceLocator(path);
    return locator.resolveResource(session);
}
