public org.apache.lucene.search.SortField getLuceneSortField(Schema schema) {
    // Your implementation goes here
    // First, create a switch statement to handle different field types appropriately
    switch (this.getType()) {
        case STRING:
            return new org.apache.lucene.search.SortField(schema.getFieldName(this.getField()), org.apache.lucene.search.SortField.Type.STRING, !this.reverse);
        case INT:
            return new org.apache.lucene.search.SortField(schema.getFieldName(this.getField()), org.apache.lucene.search.SortField.Type.INT, this.reverse);
        case LONG:
            return new org.apache.lucene.search.SortField(schema.getFieldName(this.getField()), org.apache.lucene.search.SortField.Type.LONG, this.reverse);
        case FLOAT:
            return new org.apache.lucene.search.SortField(schema.getFieldName(this.getField()), org.apache.lucene.search.SortField.Type.FLOAT, this.reverse);
        case DOUBLE:
            return new org.apache.lucene.search.SortField(schema.getFieldName(this.getField()), org.apache.lucene.search.SortField.Type.DOUBLE, this.reverse);
        case DATE:
            return new org.apache.lucene.search.SortField(schema.getFieldName(this.getField()), org.apache.lucene.search.SortField.Type.LONG, !this.reverse);
        case GEO:
            return new org.apache.lucene.spatial.prefix.RecursivePrefixTreeStrategy(schema.getFieldName(this.getField()));
        default:
            throw new IllegalStateException("Invalid field type: " + this.getType());
    }
}
