public int testOffsetMatch(String text, int offset, String substring) {
    if (text == null || substring == null) {
        throw new NullPointerException();
    }
    int length = text.length();
    int subLength = substring.length();
    if (offset < 0 || offset > length || subLength > length - offset) {
        return -1;
    }
    int endIndex = offset + subLength;
    if (text.regionMatches(offset, substring, 0, subLength)) {
        return endIndex;
    } else {
        return -1;
    }
}
