public void mergeCells(String pos, int rowMerge, int columnMerge) throws FastOdsException, IOException {
    if (rowMerge < 0 || columnMerge < 0) {
        throw new FastOdsException("Row or column index is negative");
    }

    Table[] tables = document.getTableList().getTableArray();

    for (Table table : tables) {
        CellRangeAddress range = new CellRangeAddress(pos, pos);
        CTTable ctTable = table.getCTTable();
        CTTableColumns columns = ctTable.getTableColumns();
        CTTableColumn ctColumn = columns.getTableColumnList().get(range.getFirstColumn());
        ctColumn.setWidth(BigInteger.valueOf(ctColumn.getWidth().longValue() * columnMerge));

        // merge cells
        for (int i = range.getFirstColumn(); i <= range.getLastColumn(); i++) {
            for (int j = range.getFirstRow(); j <= range.getLastRow(); j++) {
                Cell cell = table.getCellByPosition(i, j);
                if (i == range.getFirstColumn() && j == range.getFirstRow()) {
                    cell.setValue("Merged cells");
                } else {
                    cell.setValue(null);
                }
                cell.setFormula(null);
            }
        }

        // set span
        CTSpan span = ctColumn.addNewSpan();
        span.setSpan(BigInteger.valueOf(columnMerge));
    }
}
