public Map<String, Integer> deleteRecords(Statement stmt, Qualifier... qualifiers) {
    Map<String, Integer> result = new HashMap<>();
    int readCount = 0;
    int writeCount = 0;
    try {
        SelectQuery selectQuery = new SelectQuery();
        selectQuery.setNamespace(stmt.getNamespace());
        selectQuery.addSelect("*");
        selectQuery.addStatement(stmt);
        selectQuery.addQualifier(AndQualifier.and(qualifiers));
        RecordSet rs = getRecord(selectQuery);
        readCount = rs.size();
        for (Record rec : rs.getRecords()) {
            DeleteQuery deleteQuery = new DeleteQuery();
            deleteQuery.setNamespace(stmt.getNamespace());
            deleteQuery.setRecordType(stmt.getRecordType());
            deleteQuery.setPrimaryKey(rec.getRecordId().toPrimaryKey());
            performServerQuery(deleteQuery);
            writeCount++;
        }
    } catch (Exception ex) {
        // handle exception as per application requirements
    }
    result.put("read", readCount);
    result.put("write", writeCount);
    return result;
}
