public static<K,V> Map<V,K> invert(Map<K,V> pSource){
     if(pSource == null) {
         throw new IllegalArgumentException("pSource cannot be null");
     }

     Map<V,K> result;
     try {
         result = pSource.getClass().newInstance();
     } catch (Exception e) {
         throw new IllegalArgumentException("Map type not supported: " + e.getMessage());
     }

     for(Map.Entry<K,V> entry : pSource.entrySet()) {
         if(result.containsKey(entry.getValue())) {
             throw new IllegalArgumentException("Map contains duplicates");
         }

         result.put(entry.getValue(), entry.getKey());
     }

     return result;
}
