      if (otherScopeParent == null) {

        checkState(globalScope == null, "Global scopes found at different roots");
      }
      myScope =
          new SymbolScope(
              otherScopeRoot,
              otherScopeParent == null ? null : createScopeFrom(otherScopeParent),
              getTypeOfThis(otherScope),
              null);
