protected boolean moveToRecordStart() throws IOException {











        final int START=0, BRACE=1, TYPE=2, FOUND=3, FAIL=4;
		int next = 0, state = START;
		long resetPosition = readerPosition;
		boolean inEscape = false;
		String fieldName = "";
		while (true) {
			switch(state) {
			case START:

				while (next != '{') {
					next = getChar();

					if (next < 0) {
						return false;
					}
				}
				resetPosition = readerPosition;
				inputReader.mark(100);

				next = getNonWhite();
				if (next < 0) {    
					return false;
				}
				if (next == '"') {
					state = BRACE;
				}   
				break;
			case BRACE:
				fieldName = "";




				while (next != '{') {
					next = getChar();
					if (next < 0) {   
						return false;
					}
					inEscape = (!inEscape && next == '\\');
					if (!inEscape && next == '"') {
						break;
					}
					fieldName += (char)next;
				}
				if (fieldName.equals("properties") || fieldName.equals("geometry")) {

					if ((next = getNonWhite()) < 0) {    
						return false;
					}
					if (next != ':') {
						state = START;
					} else {

						if ((next = getNonWhite()) < 0) {    
							return false;
						}
						state = (next == '{') ? FOUND : START;
					}
				} else if (fieldName.equals("type")) {
					state = TYPE;
				} else {

					state = START;
				}
				break;
			case TYPE:   
					if ((next = getNonWhite()) < 0) {    
						return false;
					}
					if (next != ':') {
						state = START;
					} else {
						if ((next = getNonWhite()) < 0) {    
							return false;
						}
						if (next != '"') {
							state = START;
						} else {
							fieldName = "";
							while (true) {
								if ((next = getChar()) < 0)  return false;   
								inEscape = (!inEscape && next == '\\');
								if (!inEscape && next == '"')  break;
								fieldName += (char)next;
							}
							if (!"feature".equals(fieldName.toLowerCase())) {
								state = START;
							} else {
								if ((next = getNonWhite()) < 0) {    
									return false;
								}
								if (next != ',') {
									state = START;
								} else {
									if ((next = getNonWhite()) < 0) {    
										return false;
									}
									state = (next == '"') ? BRACE : START;
								}
							}
						}
					}
				break;
			case FOUND:
				inputReader.reset();
				readerPosition = resetPosition;
				firstBraceConsumed = true;
				return true;
			case FAIL:
				return false;
			default:
				throw new RuntimeException("Internal error");
			}
		}
	},0

