public UFS getOrCreateUFS(String ufsUri, Configuration ufsConf) throws IOException {
    UFS ufs;
    synchronized (ufsInstances) {
        ufs = ufsInstances.get(ufsUri);
        if (ufs == null) {
            UnderFileSystemFactory factory = UnderFileSystemRegistry.find(ufsUri);
