private final void zeroPaddingNumber(int value, int minDigits, int maxDigits, StringBuffer buffer)
    {




        try {
            if (zeroDigit == 0) {
                zeroDigit = ((DecimalFormat)numberFormat).getDecimalFormatSymbols().getZeroDigit();
            }
            if (value >= 0) {
                if (value < 100 && minDigits >= 1 && minDigits <= 2) {
                    if (value < 10) {
                        if (minDigits == 2) {
                            buffer.append(zeroDigit);
                        }
                        buffer.append((char)(zeroDigit + value));
                    } else {
                        buffer.append((char)(zeroDigit + value / 10));
                        buffer.append((char)(zeroDigit + value % 10));
                    }
                    return;
                } else if (value >= 1000 && value < 10000) {
                    if (minDigits == 4) {
                        buffer.append((char)(zeroDigit + value / 1000));
                        value %= 1000;
                        buffer.append((char)(zeroDigit + value / 100));
                        value %= 100;
                        buffer.append((char)(zeroDigit + value / 10));
                        buffer.append((char)(zeroDigit + value % 10));
                        return;
                    }
                    if (minDigits == 2 && maxDigits == 2) {
                        zeroPaddingNumber(value % 100, 2, 2, buffer);
                        return;
                    }
                }
            }
        } catch (Exception e) {
        }
        numberFormat.setMinimumIntegerDigits(minDigits);
        numberFormat.setMaximumIntegerDigits(maxDigits);
        numberFormat.format((long)value, buffer, DontCareFieldPosition.INSTANCE);
    },0

public Object rehydrateEntity(EntityType entityType, Map<String, Object> dehydratedEntity) throws Exception {
    Object hydratedEntity = entityType.getEntityClass().newInstance();
    for (Field field : entityType.getEntityClass().getDeclaredFields()) {
        field.setAccessible(true);
        String fieldName = field.getName();
        Object fieldValue = dehydratedEntity.get(fieldName);
        if (fieldValue == null) {
            continue;
        }
        if (field.getType().equals(String.class)) {
            field.set(hydratedEntity, fieldValue.toString());
        } else if (field.getType().equals(Boolean.class) || field.getType().equals(boolean.class)) {
            field.set(hydratedEntity, Boolean.parseBoolean(fieldValue.toString()));
        } else if (field.getType().equals(Integer.class) || field.getType().equals(int.class)) {
            field.set(hydratedEntity, Integer.parseInt(fieldValue.toString()));
        } else if (field.getType().equals(Long.class) || field.getType().equals(long.class)) {
            field.set(hydratedEntity, Long.parseLong(fieldValue.toString()));
        } else if (field.getType().equals(Double.class) || field.getType().equals(double.class)) {
            field.set(hydratedEntity, Double.parseDouble(fieldValue.toString()));
        } else if (field.isAnnotationPresent(ComputedAttribute.class)) {
            ComputedAttribute computedAttributeAnnotation = field.getAnnotation(ComputedAttribute.class);
            String expression = computedAttributeAnnotation.expression();
            ExpressionEvaluator expressionEvaluator = new ExpressionEvaluator(dehydratedEntity, entityType.getComputedAttributes());
            Object computedValue = expressionEvaluator.evaluate(expression);
            field.set(hydratedEntity, computedValue);
        } else {
            field.set(hydratedEntity, fieldValue);
        }
    }
    return hydratedEntity;
}
