public double calculateMedian(double[] data) {
    int length = data.length;
    Arrays.sort(data);
    if (length % 2 != 0) {
        return data[length/2];
    } else {
        double middle1 = data[length/2 - 1];
        double middle2 = data[length/2];
        return (middle1 + middle2)/2;
    }
}
