public int readLine(byte[] b, int off, int len) throws IOException {
    if (len <= 0) {
        return 0;
    }
    int count = 0, c;

    while ((c = in.read()) != -1) {
        if (c == '\r') {
            // check for LF
            c = in.read();
            if (c == '\n') {
                break;
            }
            // push back character
            if (!(in instanceof PushbackInputStream)) {
                in = new PushbackInputStream(in);
            }
            ((PushbackInputStream)in).unread(c);
            break;
        }
        else if (c == '\n') {
            break;
        }
        else {
            // store byte
            if (count < len) {
                b[off + count++] = (byte) c;
            }
        }
    }

    if (count == 0 && c == -1) {
        return -1;
    }
    return count;
}
