import com.unboundid.ldap.listener.InMemoryDirectoryServer;
import com.unboundid.ldap.listener.InMemoryDirectoryServerConfig;
import com.unboundid.ldif.LDIFReader;
import java.io.File;
import java.io.IOException;
import java.util.logging.Logger;

public void startServer(Logger logger) throws IOException {
    InMemoryDirectoryServerConfig config = new InMemoryDirectoryServerConfig("dc=test,dc=com");
    config.setEnforceSingleStructuralObjectClass(false);
    config.setSchema(null);
    config.setListenerConfigs(Utils.createListenerConfigs());
    InMemoryDirectoryServer server = new InMemoryDirectoryServer(config);
    LDIFReader ldifReader;
    try {
        File ldifFile = new File("seed.ldif");
        ldifReader = new LDIFReader(ldifFile);
        server.addEntries(ldifReader);
        ldifReader.close();
    } catch (IOException e) {
        logger.severe("Error while loading LDIF seed data: " + e.getMessage());
    }
    server.startListening();
    logger.info("Server started successfully: " + server.getListenAddresses());
}
