import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory;

import java.io.File;
import java.io.IOException;
import java.util.Objects;

public class ChaincodeCollectionConfigurationLoader {

    private final static String YAML_EXTENSION = ".yaml";
    private final static String JSON_EXTENSION = ".json";

    public ChaincodeCollectionConfiguration loadFromFile(String fileName) throws IOException {
        validateFileName(fileName);
        String extension = getFileExtension(fileName);

        if (extension.equalsIgnoreCase(YAML_EXTENSION)) {
            return loadFromYamlFile(fileName);
        }

        if (extension.equalsIgnoreCase(JSON_EXTENSION)) {
            return loadFromJsonFile(fileName);
        }

        throw new IllegalArgumentException("Unsupported file type: " + extension);
    }

    private void validateFileName(String fileName) {
        Objects.requireNonNull(fileName, "File name cannot be null.");
        if (fileName.isBlank()) {
            throw new IllegalArgumentException("File name cannot be empty.");
        }
    }

    private String getFileExtension(String fileName) {
        int dotIndex = fileName.lastIndexOf('.');
        if (dotIndex == -1) {
            throw new IllegalArgumentException("File name must have an extension.");
        }
        return fileName.substring(dotIndex);
    }

    private ChaincodeCollectionConfiguration loadFromYamlFile(String fileName) throws IOException {
        ObjectMapper yamlMapper = new ObjectMapper(new YAMLFactory());
        return yamlMapper.readValue(new File(fileName), ChaincodeCollectionConfiguration.class);
    }

    private ChaincodeCollectionConfiguration loadFromJsonFile(String fileName) throws IOException {
        ObjectMapper jsonMapper = new ObjectMapper();
        return jsonMapper.readValue(new File(fileName), ChaincodeCollectionConfiguration.class);
    }
}
