public void countNodes(Node head) {
    int activeCount = 0, decommissionedCount = 0;
    Node current = head;
    while(current != null) {
        if(current.status == Status.ACTIVE) {
            activeCount++;
        } else if(current.status == Status.DECOMMISSIONED) {
            decommissionedCount++;
        }
        current = current.next;
    }
    System.out.println("Active nodes count: " + activeCount);
    System.out.println("Decommissioned nodes count: " + decommissionedCount);
}
