public void fillProcessorAttributes(List<Processor> processors, Map<String, String> initialAttributes) {
    for (Processor processor : processors) {
        RequireAttributes requireAttributes = processor.getClass().getAnnotation(RequireAttributes.class);
        if (requireAttributes != null) {
            for (String attribute : requireAttributes.value()) {
                if (initialAttributes.containsKey(attribute)) {
                    processor.setAttribute(attribute, initialAttributes.get(attribute));
                }
            }
        }

        ProvideAttributes provideAttributes = processor.getClass().getAnnotation(ProvideAttributes.class);
        if (provideAttributes != null) {
            for (String attribute : provideAttributes.value()) {
                processor.setAttribute(attribute, null);
            }
        }
    }
}
