public static Bitmap clipToSquare(Bitmap bitmap) {
    if (bitmap.getWidth() == bitmap.getHeight()) {
        return bitmap; // if the bitmap is already square, return it as is
    }
    int size = Math.min(bitmap.getWidth(), bitmap.getHeight()); // determine the minimum dimension
    int x = (bitmap.getWidth() - size) / 2;
    int y = (bitmap.getHeight() - size) / 2;
    Bitmap squareBitmap = Bitmap.createBitmap(bitmap, x, y, size, size);
    return squareBitmap;
}
