public BufferedImage convertToBufferedImage(MagickImage pImage) throws MagickException {
    BufferedImage image = new BufferedImage(pImage.getWidth(), pImage.getHeight(), BufferedImage.TYPE_BYTE_BINARY);
    pImage.dispatchImage(0, 0, pImage.getWidth(), pImage.getHeight(), "I", new byte[pImage.getWidth() * pImage.getHeight()]);
    PixelGrabber grabber = new PixelGrabber(pImage, 0, 0, -1, -1, true);
    try {
        grabber.grabPixels();
    } catch (InterruptedException e) {
        throw new MagickException(e.getMessage(), e);
    }
    int[] data = (int[]) grabber.getPixels();
    image.setRGB(0, 0, pImage.getWidth(), pImage.getHeight(), data, 0, pImage.getWidth());
    return image;
}
