import java.math.BigInteger;
import java.net.Inet6Address;
import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.Arrays;

public class IPv6RangeParser {

    public static Range<Inet6Address> parse(String cidr) throws UnknownHostException {
        String[] parts = cidr.split("/");
        String ip = parts[0];
        int prefixLength = Integer.parseInt(parts[1]);
        InetAddress inetAddress = InetAddress.getByName(ip);
        byte[] address = inetAddress.getAddress();
        BigInteger mask = prefixToMask(prefixLength);
        BigInteger network = new BigInteger(address).and(mask);
        BigInteger broadcast = network.add(mask.not());

        byte[] networkAddressBytes = network.toByteArray();
        byte[] broadcastAddressBytes = broadcast.toByteArray();

        // pad the address byte arrays with zeros
        networkAddressBytes = Arrays.copyOfRange(networkAddressBytes, Math.max(0, networkAddressBytes.length - address.length), address.length);
        broadcastAddressBytes = Arrays.copyOfRange(broadcastAddressBytes, Math.max(0, broadcastAddressBytes.length - address.length), address.length);

        Inet6Address networkAddress = (Inet6Address) InetAddress.getByAddress(networkAddressBytes);
        Inet6Address broadcastAddress = (Inet6Address) InetAddress.getByAddress(broadcastAddressBytes);

        return Range.closed(networkAddress, broadcastAddress);
    }

    private static BigInteger prefixToMask(int prefixLength) {
        return BigInteger.valueOf(-1L).shiftLeft(128 - prefixLength);
    }
}
