public void removeJNDIAlias() {
    try {
        // Obtain the JNDI context
        Context ctx = new InitialContext();

        // Lookup the binder service
        BinderService binderService = (BinderService) ctx.lookup("java:jboss/BinderService");

        // Retrieve the list of JNDI aliases
        List<String> aliases = binderService.getJndiBindings();

        // Loop through the aliases and remove them one by one
        for (String alias : aliases) {
            // Skip the first alias which was handled when removing the pooled-connection-factory service
            if (alias.equals("java:jboss/DefaultJMSConnectionFactory")) {
                continue;
            }
            binderService.unbind(alias);
        }
    } catch (NamingException e) {
        // Handle the exception appropriately
    }
}
