public static <T> WeakReference<T> unregisterOnAdapterChange(final ObservableList<T> list, final T callback){
    final WeakReference<T> ref = new WeakReference<>(callback);
    list.addOnPropertyChangedCallback(new Observable.OnPropertyChangedCallback() {
        @Override
        public void onPropertyChanged(Observable observable, int i) {
            T listener = ref.get();
            if (listener == null) {
                list.removeOnPropertyChangedCallback(this);
            } else {
                // assuming the adapter implements Filterable
                ((Filterable) list).getFilter().filter(null);
            }
        }
    });
    return ref;
}
