public void transformRightToLeft(Tree tree) {
    if (tree == null) {
        return;
    }
    // Swap the nodes and their join types
    if (tree.joinType == JoinType.RIGHT) {
        tree.joinType = JoinType.LEFT;
        Node tmp = tree.leftNode;
        tree.leftNode = tree.rightNode;
        tree.rightNode = tmp;
    }
    // Recursively call the same function for the left and the right subtrees
    transformRightToLeft(tree.leftNode);
    transformRightToLeft(tree.rightNode);
}
