import org.json.JSONObject;
import org.json.JSONArray;

public JSONBuilder serializeToJSON(JSONBuilder jb) {

  // Assuming you have a ResultSet named 'rs' containing data from database
  JSONArray resultSetJSON = new JSONArray();

  try {

    ResultSetMetaData metaData = rs.getMetaData();

    while (rs.next()) {

      JSONObject obj = new JSONObject();

      for (int i = 1; i <= metaData.getColumnCount(); i++) {

        String columnName = metaData.getColumnName(i).toLowerCase();
        String value = rs.getString(i);
        obj.put(columnName, value);
      }

      resultSetJSON.put(obj);
    }

    return jb.setJSON(resultSetJSON.toString());

  } catch (SQLException | JSONException ex) {

      ex.printStackTrace();
      return jb;
  }
}
