public void addQueryCriteriaForAllowedResults(QueryWhere queryWhere, String userId, List<String> groupIds) {
    // create a new QueryCriteria instance for the allowed results
    QueryCriteria allowedResultsCriteria = new QueryCriteria();

    // add a condition to only retrieve results where the user id matches
    allowedResultsCriteria.addCondition("user_id", QueryCriteria.Operator.EQUALS, userId);

    // if the user belongs to any groups, add a condition to retrieve results where the group id matches one of the user's group ids
    if (!groupIds.isEmpty()) {
        allowedResultsCriteria.addCondition("group_id", QueryCriteria.Operator.IN, groupIds);
    }

    // add the newly created allowed results criteria to the existing query criteria with an AND operator to intersect the results
    queryWhere.addCriteria(allowedResultsCriteria, QueryCriteria.Operator.AND);
}
