/**
 * Reads problem data from file.
 *
 * @param file the file that contains the problem data
 * @param eps  the precision for comparing doubles
 * @return the read problem instance
 * @throws IOException if there was an error reading from file
 */
public static Problem readProblem(File file, double eps) throws IOException {
    BufferedReader reader = new BufferedReader(new FileReader(file));

    int n = Integer.parseInt(reader.readLine());
    double[][] a = new double[n][n + 1];

    for (int i = 0; i < n; i++) {
        String[] lineTokens = reader.readLine().split(" ");
        for (int j = 0; j < n + 1; j++) {
            a[i][j] = Double.parseDouble(lineTokens[j]);
        }
    }

    reader.close();

    return new Problem(a, eps);
}
