public class Main {
    public static Path getParentPath(Path path) {
        Path parent = path.getParent();
        if (parent != null) {
            return parent;
        } else if (path.getNameCount() > 0) {
            return path.subpath(0, path.getNameCount() - 1);
        } else {
            return null;
        }
    }

    public static void main(String[] args) {
        Path path = Paths.get("/path/to/some/file");
        System.out.println(getParentPath(path)); // Output: /path/to/some
    }
}
