public class MatchingResult {
    private final int startIndex;
    private final int endIndex;
    private final String matchedString;

    public MatchingResult(int startIndex, int endIndex, String matchedString) {
        this.startIndex = startIndex;
        this.endIndex = endIndex;
        this.matchedString = matchedString;
    }

    public int getStartIndex() {
        return startIndex;
    }

    public int getEndIndex() {
        return endIndex;
    }

    public String getMatchedString() {
        return matchedString;
    }
}

public class MalformedPatternException extends Exception {
    public MalformedPatternException(String message) {
        super(message);
    }
}

public MatchingResult findOccurrence(String strPattern, String strInput, int offset, boolean caseSensitive) throws MalformedPatternException {
    if (strPattern == null || strInput == null) {
        throw new IllegalArgumentException("Both pattern and input string must be non-null");
    }

    if (offset < 0 || offset > strInput.length()) {
        throw new IllegalArgumentException("Offset value is out of bounds");
    }

    Pattern pattern;
    if (caseSensitive) {
        pattern = Pattern.compile(strPattern);
    } else {
        pattern = Pattern.compile(strPattern, Pattern.CASE_INSENSITIVE);
    }

    Matcher matcher = pattern.matcher(strInput);
    int foundIndex = -1;
    for (int i = 0; i < offset; i++) {
        if (!matcher.find()) {
            return null;
        }
        foundIndex = matcher.end();
    }

    if (!matcher.find()) {
        return null;
    }

    String matchedString = matcher.group();
    int startIndex = matcher.start();
    int endIndex = matcher.end();

    return new MatchingResult(startIndex, endIndex, matchedString);
}
