public double calculateMetric(Metric metric, int outputNum, String label) {
    double result = 0.0;
    switch (metric) {
        case PRECISION:
            result = calculatePrecision(outputNum, label);
            break;
        case RECALL:
            result = calculateRecall(outputNum, label);
            break;
        case F1_SCORE:
            double precision = calculatePrecision(outputNum, label);
            double recall = calculateRecall(outputNum, label);
            result = 2 * ((precision * recall) / (precision + recall));
            break;
        default:
            throw new IllegalArgumentException("Unknown metric type");
    }
    return result;
}

