public void snapWindowToLocation(Window win, String location) {
    int x = win.getX();
    int y = win.getY();

    if (location.equals("top-left")) {
        x = 0;
        y = 0;
    } else if (location.equals("top-right")) {
        x = win.getToolkit().getScreenSize().width - win.getWidth();
        y = 0;
    } else if (location.equals("bottom-left")) {
        x = 0;
        y = win.getToolkit().getScreenSize().height - win.getHeight();
    } else if (location.equals("bottom-right")) {
        x = win.getToolkit().getScreenSize().width - win.getWidth();
        y = win.getToolkit().getScreenSize().height - win.getHeight();
    }

    win.setLocation(x, y);
}
