public static void setCodePoint(StringBuffer target, int offset16, int char32) {
    if (char32 < Character.MIN_SUPPLEMENTARY_CODE_POINT) {
        target.replace(offset16, offset16 + 1, String.valueOf((char) char32));
    } else {
        char[] surrogatePair = Character.toChars(char32);
        target.replace(offset16, offset16 + 1, String.valueOf(surrogatePair));
    }
}
