public List<String> subtractDroidFlakes(List<String> droidFlakes, int numToSubtract) {
    int size = droidFlakes.size();
    List<String> result = new ArrayList<>();

    if (numToSubtract >= size) {
        return result; // return empty list if there are not enough droidFlakes to subtract
    }

    for (int i = 0; i < size - numToSubtract; i++) {
        result.add(droidFlakes.get(i));
    }

    return result;
}
