public static void suppressMethods(Class<?> clazz, String methodName, String... additionalMethodNames) throws NoSuchMethodException, SecurityException, IllegalAccessException, IllegalArgumentException, InvocationTargetException {
    Method[] methods = clazz.getDeclaredMethods();
    List<Method> methodsToSuppress = new ArrayList<>();
    methodsToSuppress.add(clazz.getDeclaredMethod(methodName));
    for(String additionalMethodName : additionalMethodNames) {
        methodsToSuppress.add(clazz.getDeclaredMethod(additionalMethodName));
    }
    for(Method methodToSuppress : methodsToSuppress) {
        Field field = Method.class.getDeclaredField("modifiers");
        field.setAccessible(true);
        field.setInt(methodToSuppress, methodToSuppress.getModifiers() & ~Modifier.PUBLIC & ~Modifier.PRIVATE & ~Modifier.PROTECTED);
    }
}
