public int calculateHashTreeHeight(Node node, Metadata metadata) throws HashException, KSIException {
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null.");
    }

    // calculate the hash of the node with metadata
    byte[] hash = calculateHash(node, metadata);

    // initialize a counter variable for the height of the hash tree
    int height = 0;

    // loop until the hash is only 1 bit long
    while (hash.length * 8 > 1) {
        // calculate the hash of the current hash
        hash = calculateHash(hash);

        // increment the height counter
        height++;
    }

    // return the height of the hash tree
    return height;
}
