public void drawButton(float llx, float lly, float urx, float ury, String text, PdfFont bf, float size, PdfCanvas canvas) {
    Rectangle rectangle = new Rectangle(llx, lly, urx - llx, ury - lly);
    canvas.saveState()
          .setFillColor(Color.BLUE) // set the fill color of the button
          .setStrokeColor(Color.BLACK) // set the stroke color of the button
          .rectangle(rectangle)
          .fillStroke()
          .beginText()
          .setFontAndSize(bf, size)
          .moveText(llx + 5, ury - 5) // position the text inside the button
          .showText(text)
          .endText()
          .restoreState();
}
