public class FunctionReplacer {

    public static String replace(String input) {
        String result = input;
        int start = input.indexOf("out(");
        int end = -1;
        if (start != -1) {
            start += 4; // length of "out("
            int openBrackets = 1;
            for (int i = start; i < input.length(); i++) {
                if (input.charAt(i) == '(') {
                    openBrackets++;
                } else if (input.charAt(i) == ')') {
                    openBrackets--;
                    if (openBrackets == 0) {
                        end = i;
                        break;
                    }
                }
            }
            if (end != -1) {
                String function = input.substring(start, end);
                String value = getValue(function);
                result = result.replace("out(" + function + ")", value);
                result = replace(result);
            }
        }
        return result;
    }

    private static String getValue(String function) {
        // logic to compute the result of the function
        // and return it as a string
        return "10";
    }

    public static void main(String[] args) {
        // example usage
        String input = "This is a test, out(sum(1, 2), mul(4, 5))";
        String output = FunctionReplacer.replace(input);
        System.out.println(output);
        // expected output: "This is a test, 10"
    }

}
