public void setScatterGraph(double[][] measures, double[] measureStds, double[] variedParamValues, Color[] colors) {
    XYSeriesCollection dataset = new XYSeriesCollection();
    for(int i = 0; i < measures.length; i++) {
        XYSeries series = new XYSeries("Curve " + (i+1));
        for(int j = 0; j < measures[i].length; j++) {
            series.add(variedParamValues[j], measures[i][j]);
        }
        dataset.addSeries(series);
    }

    JFreeChart chart = ChartFactory.createXYLineChart(
        "Scatter graph", // chart title
        "Varied parameter", // x axis label
        "Measures", // y axis label
        dataset, // data
        PlotOrientation.VERTICAL,
        true, // include legend
        true, // tooltips
        false // urls
    );

    chart.setBackgroundPaint(Color.white);

    XYPlot plot = (XYPlot) chart.getPlot();
    plot.setBackgroundPaint(Color.lightGray);
    plot.setDomainGridlinePaint(Color.white);
    plot.setRangeGridlinePaint(Color.white);
    plot.setDomainCrosshairVisible(true);
    plot.setRangeCrosshairVisible(true);

    XYLineAndShapeRenderer renderer = new XYLineAndShapeRenderer();
    for(int i = 0; i < measures.length; i++) {
        renderer.setSeriesPaint(i, colors[i % colors.length]);
        renderer.setSeriesShapesVisible(i, false);
    }
    plot.setRenderer(renderer);

    NumberAxis rangeAxis = (NumberAxis) plot.getRangeAxis();
    rangeAxis.setAutoRangeIncludesZero(false);

    ChartPanel chartPanel = new ChartPanel(chart);
    chartPanel.setPreferredSize(new java.awt.Dimension(700, 400));
    // TODO: add chartPanel to your desired container
}
