import java.nio.ByteBuffer;
import java.nio.ByteOrder;

public static int getValueFromBuffer(ByteBuffer buffer, int index, PrimitiveType type, ByteOrder byteOrder) {
    int value;
    switch (type) {
        case INT:
            value = buffer.getInt(index);
            break;
        case SHORT:
            value = buffer.getShort(index);
            break;
        case LONG:
            value = (int) buffer.getLong(index);
            break;
        case BYTE:
            value = buffer.get(index);
            break;
        default:
        	throw new IllegalArgumentException("Unsupported PrimitiveType: " + type);
    }
    if (ByteOrder.BIG_ENDIAN == byteOrder) {
        return Integer.reverseBytes(value);
    } else {
        return value;
    }
}

enum PrimitiveType {
    INT, SHORT, LONG, BYTE
}
