public int findBOrder(Node node) {
    if (node instanceof Leaf) {
        int blockSize = ((Leaf) node).getBlockSize();
        return (int) ((blockSize * 8 * 1024 - 8) / (32 + 8 * blockSize));
    } else if (node instanceof Internal) {
        return ((Internal) node).getChild(0).getBOrder();
    }
    return -1;
}
