public List<String> getEjbReferences() {
    List<String> ejbRefs = new ArrayList<>();
    Context initialContext = null;

    try {
        initialContext = new InitialContext();
        String appName = (String) initialContext.lookup("java:app/AppName");
        String moduleName = (String) initialContext.lookup("java:module/ModuleName");

        // Get all ejb references configured for the component
        NamingEnumeration<RefAddr> ejbRefsEnum = initialContext.getEnvironment()
                .getRef(getComponentName()).getAll();
        while (ejbRefsEnum.hasMore()) {
            RefAddr refAddr = ejbRefsEnum.next();
            if ("Link".equals(refAddr.getType())) {
                String ejbRefName = refAddr.getContent().toString();
                ejbRefs.add(ejbRefName);
            }
        }
    } catch (NamingException e) {
        // Handle exception
    } finally {
        try {
            if (initialContext != null) {
                initialContext.close();
            }
        } catch (NamingException e) {
            // Handle exception
        }
    }

    return ejbRefs;
}
