public static List<Point> extractRoof(List<Point> polygon, double height) {
    List<Point> roof = new ArrayList<>();
    for (int i = 0; i < polygon.size() - 1; i++) {
        Point p1 = polygon.get(i);
        Point p2 = polygon.get(i + 1);
        double distance = Math.sqrt(Math.pow(p2.getX() - p1.getX(), 2) + Math.pow(p2.getY() - p1.getY(), 2));
        double xDiff = p2.getX() - p1.getX();
        if (xDiff == 0) {
            // vertical line case
            roof.add(new Point(p1.getX(), p1.getY() + height));
        } else {
            double slope = (p2.getY() - p1.getY()) / (p2.getX() - p1.getX());
            double yIntercept = p1.getY() - slope * p1.getX();
            double roofX = p1.getX() + ((height - p1.getY()) / slope);
            double roofY = height;
            if (roofX < Math.min(p1.getX(), p2.getX()) || roofX > Math.max(p1.getX(), p2.getX())) {
                // roof point is not on this segment
                continue;
            } else {
                roof.add(new Point(roofX, roofY));
            }
        }
    }
    return roof;
}
