public static String getFingerprint(String certificate, String requestedFingerprint) {
    try {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] certificateBytes = certificate.getBytes("UTF-8");
        byte[] hashBytes = md.digest(certificateBytes);

        StringBuilder result = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(b & 0xFF);
            if (hex.length() == 1) {
                result.append('0');
            }
            result.append(hex.toUpperCase());
        }

        return result.toString().replaceAll("[^0-9A-F]", "").substring(0, 2 * requestedFingerprint.length());
    } catch (NoSuchAlgorithmException | UnsupportedEncodingException ex) {
        throw new RuntimeException("Error calculating fingerprint", ex);
    }
}
