import java.io.File;
import java.io.FileFilter;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;

public class FileFinder {

    public static Map<File, File> findFiles(File directory, FileFilter filter, Consumer<File> fileOut, Consumer<File> listener) {
        Map<File,File> foundFiles = new HashMap<>();
        File[] files = directory.listFiles();

        if (files != null) {
            for (File file : files) {
                if (filter.accept(file)) {
                    foundFiles.put(file,directory);
                    fileOut.accept(file);
                } else if (file.isDirectory()) {
                    foundFiles.putAll(findFiles(file, filter, fileOut, listener));
                } else {
                    listener.accept(file);
                }
            }
        }

        return foundFiles;
    }

}
