public GeometryCollection parseGeometryCollection(JsonParser jp) throws IOException, SQLException {
    ArrayList<Geometry> geometriesArray = new ArrayList<>();
    JsonNode node = jp.getCodec().readTree(jp);
    JsonNode geometriesNode = node.get("geometries");
    GeometryFactory geometryFactory = new GeometryFactory();
    for (JsonNode geometryNode : geometriesNode) {
        String type = geometryNode.get("type").asText();
        switch (type) {
            case "Point":
                Point point = geometryFactory.createPoint(new Coordinate(geometryNode.get("coordinates").get(0).asDouble(), geometryNode.get("coordinates").get(1).asDouble()));
                geometriesArray.add(point);
                break;
            case "LineString":
                JsonNode coordinatesNode = geometryNode.get("coordinates");
                Coordinate[] coordinates = new Coordinate[coordinatesNode.size()];
                for (int i = 0; i < coordinatesNode.size(); i++) {
                    double x = coordinatesNode.get(i).get(0).asDouble();
                    double y = coordinatesNode.get(i).get(1).asDouble();
                    coordinates[i] = new Coordinate(x, y);
                }
                LineString lineString = geometryFactory.createLineString(coordinates);
                geometriesArray.add(lineString);
                break;
        }
    }
    Geometry[] geometries = geometriesArray.toArray(new Geometry[0]);
    return geometryFactory.createGeometryCollection(geometries);
}
