import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class LibSVMFileReader {
    public static List<LibSVMDataPoint> read(String filePath) throws IOException, InvalidInputDataException {
        List<LibSVMDataPoint> dataList = new ArrayList<>();

        try(BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;

            while ((line = reader.readLine()) != null) {
                String[] fields = line.split("\\s+");

                if (fields.length < 2) {
                    throw new InvalidInputDataException("Line has to contain at least 2 fields!");
                }

                double label = Double.parseDouble(fields[0]);
                List<LibSVMFeature> featureList = new ArrayList<>();

                for (int i = 1; i < fields.length; i++) {
                    String[] featureFields = fields[i].split(":");
                    if (featureFields.length != 2) {
                        throw new InvalidInputDataException("Wrong feature entry format: " + fields[i]);
                    }
                    int index = Integer.parseInt(featureFields[0]);
                    double value = Double.parseDouble(featureFields[1]);

                    featureList.add(new LibSVMFeature(index, value));
                }

                dataList.add(new LibSVMDataPoint(label, featureList));
            }
        } catch (IOException ex) {
            throw new IOException("Exception while reading file: " + ex.getMessage());
        } catch (NumberFormatException ex) {
            throw new InvalidInputDataException("Invalid number format: " + ex.getMessage());
        }

        return dataList;
    }
}
