public static List<Class<?>> sortDeclaredBeans(List<Class<?>> beans) {
    Map<Class<?>, Integer> beanIndices = new HashMap<>();
    int index = 0;

    for (Class<?> bean : beans) {
        beanIndices.put(bean, index++);
    }

    List<Class<?>> sortedBeans = new ArrayList<>(beans);

    Collections.sort(sortedBeans, new Comparator<Class<?>>() {
        public int compare(Class<?> bean1, Class<?> bean2) {
            return beanIndices.get(bean1).compareTo(beanIndices.get(bean2));
        }
    });

    return sortedBeans;
}
