public static String getNextValue(JSONTokener x) throws JSONException {
    char c;
    while ((c = x.next()) != '"' && c != '\'' && c != JSONTokener.EOF) {
        if (c != ' ' && c != '\t' && c != '\r' && c != '\n') {
            throw x.syntaxError("Missing quote");
        }
    }
    if (c == JSONTokener.EOF) {
        throw x.syntaxError("Missing value");
    }
    StringBuffer sb = new StringBuffer();
    char q = c;
    while (true) {
        c = x.next();
        if (c == q) {
            break;
        }
        if (c == '\\') {
            c = x.next();
            if (c == 'b') {
                sb.append('\b');
            } else if (c == 't') {
                sb.append('\t');
            } else if (c == 'n') {
                sb.append('\n');
            } else if (c == 'f') {
                sb.append('\f');
            } else if (c == 'r') {
                sb.append('\r');
            } else if (c == 'u') {
                sb.append((char) Integer.parseInt(x.next(4), 16));
            } else {
                sb.append(c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}
