import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

public class DateTimeParser {
    public static LocalDateTime parseDateTimeWrapper(String wrapperFormat, String dateTimeString) {
        // Get the positions of the date and time placeholders in the wrapper format
        int datePos = wrapperFormat.indexOf("{1}");
        int timePos = wrapperFormat.indexOf("{0}");
        // Create a DateTimeFormatter based on the CLDR dateTimeFormats for the current locale
        String pattern = DateTimeFormatterBuilder.getLocalizedDateTimePattern(
                null, null, DateTimeFormatter.ISO_LOCAL_TIME, null, Locale.getDefault());
        DateTimeFormatter dtf = DateTimeFormatter.ofPattern(pattern);
        // Extract the date and time strings from the input string
        String dateString = dateTimeString.substring(datePos, timePos);
        String timeString = dateTimeString.substring(timePos);
        // Parse the date and time strings and return a LocalDateTime object
        LocalDateTime dateTime = LocalDateTime.parse(dateString + " " + timeString, dtf);
        return dateTime;
    }
}
