public void bindAttributeAndValue(PreparedStatement stmt, int index, String attributeOrQuery, Object value, Class<?> cld) throws SQLException {
    if (cld == String.class) {
        stmt.setString(index, (String) value);
    } else if (cld == Integer.class || cld == int.class) {
        stmt.setInt(index, (int) value);
    } else if (cld == Long.class || cld == long.class) {
        stmt.setLong(index, (long) value);
    } else if (cld == Double.class || cld == double.class) {
        stmt.setDouble(index, (double) value);
    } else if (cld == Float.class || cld == float.class) {
        stmt.setFloat(index, (float) value);
    } else if (cld == Short.class || cld == short.class) {
        stmt.setShort(index, (short) value);
    } else if (cld == BigDecimal.class) {
        stmt.setBigDecimal(index, (BigDecimal) value);
    } else if (cld == Date.class || cld == java.sql.Date.class) {
        stmt.setDate(index, (java.sql.Date) value);
    } else if (cld == Time.class || cld == java.sql.Time.class) {
        stmt.setTime(index, (java.sql.Time) value);
    } else if (cld == Timestamp.class || cld == java.sql.Timestamp.class) {
        stmt.setTimestamp(index, (java.sql.Timestamp) value);
    } else if (cld == Boolean.class || cld == boolean.class) {
        stmt.setBoolean(index, (boolean) value);
    } else if (cld == Blob.class) {
        stmt.setBlob(index, (Blob) value);
    } else if (cld == Clob.class) {
        stmt.setClob(index, (Clob) value);
    } else if (cld == byte[].class) {
        stmt.setBytes(index, (byte[]) value);
    } else {
        throw new SQLException("Data type not supported for attribute: " + attributeOrQuery);
    }
}
