public static boolean checkArrowFunctionBodyStart(String code, boolean IN_FOR_INIT_CLAUSE) {
    // Check if code starts with an arrow function body
    boolean isArrowFunction = code.startsWith("=>");

    // If we are at the start of an arrow function body
    if (isArrowFunction) {
        // Check if object literals and object patterns have parentheses
        boolean hasParentheses = code.matches("^=>\\s*\\(.*?\\).*$");

        // Check if the IN_FOR_INIT_CLAUSE flag is being passed into subexpressions
        boolean isInForInitClause = code.matches("^=>\\s*\\(.*?\\)\s*[^(]*?[({] .*? ,.*,.*?[})]$");

        return hasParentheses && isInForInitClause;
    }

    return false;
}
