public void addUDFTypeToPMXML(List<UDFType> udfTypes, File pmXMLFile) throws Exception {
    DocumentBuilderFactory docFactory = DocumentBuilderFactory.newInstance();
    DocumentBuilder docBuilder = docFactory.newDocumentBuilder();
    Document doc = docBuilder.parse(pmXMLFile);

    Node root = doc.getFirstChild();
    Node udfTypesNode = null;

    NodeList nodeList = root.getChildNodes();
    for (int i = 0; i < nodeList.getLength(); i++) {
        Node node = nodeList.item(i);
        if (node.getNodeType() == Node.ELEMENT_NODE && node.getNodeName().equals("UDFTypes")) {
            udfTypesNode = node;
            break;
        }
    }

    if (udfTypesNode == null) {
        Element newUDFTypes = doc.createElement("UDFTypes");
        root.appendChild(newUDFTypes);
        udfTypesNode = newUDFTypes;
    }

    for (UDFType udfType : udfTypes) {
        Element newUDFType = doc.createElement("UDFType");
        newUDFType.setAttribute("name", udfType.getName());
        newUDFType.setAttribute("datatype", udfType.getDataType());
        newUDFType.setAttribute("type", udfType.getType());
        udfTypesNode.appendChild(newUDFType);
    }

    TransformerFactory transformerFactory = TransformerFactory.newInstance();
    Transformer transformer = transformerFactory.newTransformer();
    DOMSource source = new DOMSource(doc);
    StreamResult result = new StreamResult(pmXMLFile);
    transformer.transform(source, result);
}
