public File createDumpFile(String outputDir, String prefix, String extension) throws IOException {
    // Get the current timestamp
    String timeStamp = new SimpleDateFormat("yyyyMMddHHmmss").format(new Date());

    // Create the file object with a unique filename
    File file = new File(outputDir + File.separator + prefix + "_" + timeStamp + "." + extension);

