public InputStream copyResponseBody(InputStream is) throws FMSException{
        try {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            byte[] buffer = new byte[1024];
            int len;
            while ((len = is.read(buffer)) > -1 ) {
                baos.write(buffer, 0, len);
            }
            baos.flush();
            InputStream copy = new ByteArrayInputStream(baos.toByteArray());
            return copy;
        } catch (IOException e) {
            throw new FMSException("Error while copying response body input stream", e);
        }
    }
