public static double correlationCoefficient(double[] y1, double[] y2, int n) {
    double sumY1 = 0, sumY2 = 0, sumY1Y2 = 0, sqrSumY1 = 0, sqrSumY2 = 0;

    for (int i = 0; i < n; i++) {
        sumY1 += y1[i];
        sumY2 += y2[i];

        sumY1Y2 += y1[i] * y2[i];

        sqrSumY1 += y1[i] * y1[i];
        sqrSumY2 += y2[i] * y2[i];
    }

    double corrCoeff = (n * sumY1Y2 - sumY1 * sumY2)
            / (Math.sqrt((n * sqrSumY1 - sumY1 * sumY1) * (n * sqrSumY2 - sumY2 * sumY2)));

    return corrCoeff;
}
