public static String decrypt(String inputString, String encryptionPassword) {
    String decryptedString = "";
    try {
        Key key = new SecretKeySpec(encryptionPassword.getBytes(), "AES");
        Cipher cipher = Cipher.getInstance("AES");
        cipher.init(Cipher.DECRYPT_MODE, key);
        byte[] encryptedTextBytes = Base64.getDecoder().decode(inputString);
        byte[] decryptedTextBytes = cipher.doFinal(encryptedTextBytes);
        decryptedString = new String(decryptedTextBytes);
    } catch (NoSuchAlgorithmException | NoSuchPaddingException | InvalidKeyException | IllegalBlockSizeException | BadPaddingException e) {
        e.printStackTrace();
    }
    return decryptedString;
}
