import java.net.*;

public InetAddress findNonLoopbackAddress() throws SocketException {
    NetworkInterface networkInterface = NetworkInterface.getNetworkInterfaces();
    while (networkInterface.hasMoreElements()) {
        NetworkInterface ni = networkInterface.nextElement();
        if (ni.isLoopback() || ni.isVirtual() || ni.isPointToPoint()) {
            continue;
        }
        for (InterfaceAddress address : ni.getInterfaceAddresses()) {
            if (!(address.getAddress() instanceof Inet4Address)) {
                continue;
            }
            return address.getAddress();
        }
    }
    return null;
}
