public static void replaceSSTableReaders(List<SSTableReader> oldSSTables, List<SSTableReader> newSSTables) {
    assert oldSSTables.size() == newSSTables.size();

    // Replace the old SSTableReaders with the new ones
    for (int i = 0; i < oldSSTables.size(); i++) {
        SSTableReader oldSSTable = oldSSTables.get(i);
        SSTableReader newSSTable = newSSTables.get(i);

        // Replace the old index summary with the new index summary
        oldSSTable.descriptor.indexSummary.replace(newSSTable.descriptor.indexSummary);

        // Replace the old bloom filter with the new bloom filter
        oldSSTable.descriptor.bf_fp_chance = newSSTable.descriptor.bf_fp_chance;
        oldSSTable.bf = newSSTable.bf;

        // Replace the old table metadata with the new table metadata
        oldSSTable.metadata = newSSTable.metadata;
    }
}
