@Override
public void rollback(TransactionStatus status) throws TransactionException {
    DefaultTransactionStatus defStatus = (DefaultTransactionStatus) status;
    if (defStatus.isNewTransaction()) {
        doRollback(defStatus);
    } else if (defStatus.getTransaction() != null && defStatus.isCompleted()) {
        // Transaction is already completed, so do nothing.
    } else {
        doRollback(defStatus);
    }
}

protected void doRollback(DefaultTransactionStatus status) {
    try {
        if (status.getTransaction() != null) {
            rollback(status.getTransaction());
        }
    } catch (TransactionException ex) {
        throw ex;
    } catch (Exception ex) {
        throw new TransactionSystemException("Could not roll back transaction", ex);
    }
}
