public static boolean sparseCholRank1UpdateDowndate(SparseCholeskyFactorization L, int sigma, SparseVector C, int[] parent) {
    // check inputs
    if (L == null || C == null || parent == null) {
        return false;
    }
    if (C.size() != L.matrix().nrows()) {
        return false;
    }
    if (sigma != 1 && sigma != -1) {
        return false;
    }

    // perform rank-1 update/downdate
    int n = L.matrix().nrows();
    double[] x = new double[n]; // temporary array for L solve
    double[] y = new double[n]; // temporary array for L' solve
    double[] l = new double[n]; // temporary array for L traversal
    boolean[] marked = new boolean[n]; // temporary array for marking nodes in L traversal
    for (int k = 0; k < n; k++) {
        // traverse up the elimination tree and update/downdate nodes
        int j = L.mapping()[k];
        l[j] = C.get(j);
        marked[j] = true;
        for (int p = parent[j]; p != -1; p = parent[p]) {
            if (!marked[p]) {
                l[p] = 0.0;
            }
            double s = 0.0;
            for (int q = L.matrix().getp()[p]; q < L.matrix().getp()[p + 1]; q++) {
                int i = L.matrix().geti()[q];
                double v = L.matrix().getx()[q];
                if (i != j) {
                    s += v * l[i];
                }
            }
            if (sigma == 1) {
                l[p] -= s * L.matrix().getx()[L.matrix().getp()[j]];
                l[p] /= L.matrix().getx()[L.matrix().getp()[j + 1] - 1];
            } else {
                l[p] -= s * L.matrix().getx()[L.matrix().getp()[p]];
                l[p] /= L.matrix().getx()[L.matrix().getp()[p + 1] - 1];
            }
            marked[p] = true;
        }
        // update/downdate the factorization
        if (sigma == 1) {
            double d = l[j];
            double z = L.matrix().getx()[L.matrix().getp()[j]] + d * d;
            if (z <= 0.0) {
                return false;
            }
            L.matrix().getx()[L.matrix().getp()[j]] = z;
            L.matrix().getx()[L.matrix().getp()[j + 1] - 1] = d;
            for (int p = parent[j]; p != -1; p = parent[p]) {
                double v = l[p];
                double u = L.matrix().getx()[L.matrix().getp()[p]] * v;
                double s = 0.0;
                for (int q = L.matrix().getp()[p]; q < L.matrix().getp()[p + 1] - 1; q++) {
                    int i = L.matrix().geti()[q];
                    if (i != j) {
                        s += L.matrix().getx()[q] * x[i];
                    }
                }
                d = (v - s) / L.matrix().getx()[L.matrix().getp()[j + 1] - 1];
                x[j] += u;
                x[p] = d;
            }
            for (int p = parent[j]; p != -1; p = parent[p]) {
                double v = x[p] + l[p] * d;
                for (int q = L.matrix().getp()[p]; q < L.matrix().getp()[p + 1] - 1; q++) {
                    int i = L.matrix().geti()[q];
                    if (marked[i]) {
                        x[i] += L.matrix().getx()[q] * v;
                    }
                }
            }
        } else {
            double d = L.matrix().getx()[L.matrix().getp()[j + 1] - 1];
            double z = L.matrix().getx()[L.matrix().getp()[j]] - d * d;
            if (z <= 0.0) {
                return false;
            }
            L.matrix().getx()[L.matrix().getp()[j]] = z;
            L.matrix().getx()[L.matrix().getp()[j + 1] - 1] = 0.0;
            for (int p = parent[j]; p != -1; p = parent[p]) {
                double v = x[p];
                double u = L.matrix().getx()[L.matrix().getp()[p]] * v;
                double s = 0.0;
                for (int q = L.matrix().getp()[p]; q < L.matrix().getp()[p + 1] - 1; q++) {
                    int i = L.matrix().geti()[q];
                    if (i != j) {
                        s += L.matrix().getx()[q] * l[i];
                    }
                }
                double t = (v - s) / d;
                x[j] += u;
                x[p] = t;
            }
            for (int p = parent[j]; p != -1; p = parent[p]) {
                double v = x[p] + l[p] * x[j];
                for (int q = L.matrix().getp()[p]; q < L.matrix().getp()[p + 1] - 1; q++) {
                    int i = L.matrix().geti()[q];
                    if (marked[i]) {
                        x[i] += L.matrix().getx()[q] * v;
                    }
                }
            }
        }
        // clear temporary arrays
        for (int p = parent[j]; p != -1; p = parent[p]) {
            marked[p] = false;
        }
    }
    // update/downdate successful
    return true;
}
