public ObjectManagerByteArrayOutputStream[] serializeLogRecord(ByteArrayOutputStream byteArrayOutputStream) throws ObjectManagerException {
    try {
        LogRecord logRecord = new LogRecord();
        byte[] bytes = byteArrayOutputStream.toByteArray();
        logRecord.read(new ByteArrayInputStream(bytes));
        ObjectManagerByteArrayOutputStream[] results = new ObjectManagerByteArrayOutputStream[1];
        ObjectManagerByteArrayOutputStream ombaos = new ObjectManagerByteArrayOutputStream();
        ombaos.writeByte(0);
        ombaos.writeObject(logRecord);
        results[0] = ombaos;
        return results;
    } catch (IOException e) {
        throw new ObjectManagerException("Error serializing LogRecord", e);
    }
}
