import java.util.Calendar;
import java.util.Locale;
import java.time.format.DateTimeFormatter;
import javax.xml.bind.DatatypeConverter;

public interface TextStrategy {
    /**
     * Get the textual representation of a Calendar field
     * 
     * @param fieldValue
     *            the value of the Calendar field to format
     * @param locale
     *            the locale for which to obtain the text
     * @return the textual representation of the Calendar field
     */
    String getTextRepresentation(int fieldValue, Locale locale);

    /**
     * Get the pattern for a Calendar field
     * 
     * @return the pattern for the field
     */
    String getPattern();
}

public class CustomTextStrategy {
    public static TextStrategy buildTextStrategy(int field, Locale locale) {
        final Calendar calendar = Calendar.getInstance(locale);
        calendar.set(field, 0);
        final String pattern = DatatypeConverter.printDateTime(calendar);
        final DateTimeFormatter formatter = DateTimeFormatter.ofPattern(pattern, locale);
        final int maxLengthEstimate = (field == Calendar.YEAR) ? pattern.length()
                : (2 + (int) Math.floor(Math.log10(calendar.getActualMaximum(field) + 1)));
        return new TextStrategy() {
            @Override
            public String getTextRepresentation(int fieldValue, Locale locale) {
                return formatter.format(calendar.with(field, fieldValue).toInstant());
            }

            @Override
            public String getPattern() {
                return pattern;
            }
        };
    }
}
