public static Class<?> parseTextIntoJavaClass(String text, String fileName) throws Exception {
    JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
    DiagnosticCollector<JavaFileObject> diagnostics = new DiagnosticCollector<>();
    StandardJavaFileManager fileManager = compiler.getStandardFileManager(diagnostics, null, null);

    JavaFileObject fileObject = new SimpleJavaFileObject(URI.create("string:///" + fileName.replace('.', '/') + JavaFileObject.Kind.SOURCE.extension), JavaFileObject.Kind.SOURCE) {
        @Override
        public CharSequence getCharContent(boolean ignoreEncodingErrors) throws IOException {
            return text;
        }
    };

    Iterable<? extends JavaFileObject> sources = Collections.singletonList(fileObject);

    JavaCompiler.CompilationTask task = compiler.getTask(null, fileManager, diagnostics, null, null, sources);

    if (!task.call()) {
        throw new Exception("Compilation failed.");
    }

    MemoryClassLoader classLoader = new MemoryClassLoader();
    Class<?> clazz = classLoader.loadClass(fileName);

    return clazz;
}
