public final URL getResource(String name) {
    URL url = findResource(name);
    if (url == null) {
        ClassLoader parent = getParent();
        if (parent != null) {
            url = parent.getResource(name);
        }
    }
    if (url == null) {
        url = getCommonLibraryResource(name);
    }
    if (url != null && "jar".equalsIgnoreCase(url.getProtocol())) {
        String path = url.getPath();
        if (path.endsWith("!/")) {
            path = path.substring(0, path.length() - 2);
        }
        try {
            url = new URL(path);
        } catch (MalformedURLException e) {
            // ignore, return original URL
        }
    }
    return url;
}

private URL getCommonLibraryResource(String name) {
    for (ClassLoader cl : COMMON_LIBRARY_CLASSLOADERS) {
        URL url = cl.getResource(name);
        if (url != null) {
            return url;
        }
    }
    return null;
}
