public List<String> readLines(String resourceWithRestOrClasspathOrFilePath, String charsetName) throws IOException {
    List<String> lines = new ArrayList<>();
    InputStream inputStream = Thread.currentThread().getContextClassLoader().getResourceAsStream(resourceWithRestOrClasspathOrFilePath);
    if (inputStream == null) {
        File file = new File(resourceWithRestOrClasspathOrFilePath);
        if (file.exists()) {
            inputStream = new FileInputStream(file);
        } else {
            throw new FileNotFoundException("File not found: " + resourceWithRestOrClasspathOrFilePath);
        }
    }
    InputStreamReader inputStreamReader = new InputStreamReader(inputStream, Charset.forName(charsetName));
    BufferedReader bufferedReader = new BufferedReader(inputStreamReader);
    String line;
    while ((line = bufferedReader.readLine()) != null) {
        lines.add(line);
    }
    bufferedReader.close();
    return lines;
}
