public <T> List<T> findBeanCandidates(Class<T> beanType, BeanDefinition filter) {
    List<T> candidates = new ArrayList<>();
    for (String beanName : beanRegistry.getBeanDefinitionNames()) {
        BeanDefinition beanDef = beanRegistry.getBeanDefinition(beanName);
        if (beanDef.isAbstract() || beanDef.isPrototype()) {
            continue;
        }
        if (filter != null && beanDef.equals(filter)) {
            continue;
        }
        Class<?> clazz = null;
        try {
            clazz = Class.forName(beanDef.getBeanClassName());
        } catch (ClassNotFoundException e) {
            continue;
        }
        if (beanType.isAssignableFrom(clazz)) {
            T candidate = applicationContext.getBean(beanName, beanType);
            candidates.add(candidate);
        }
    }
    return candidates;
}
