public Cipher createReadCipher() throws NoSuchAlgorithmException, NoSuchPaddingException {
    // Create a new instance of the Cipher class with the specified transformation
    Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
    // Initialize the cipher in encryption mode with a newly generated secret key
    cipher.init(Cipher.ENCRYPT_MODE, generateSecretKey());
    // Return the cipher to the caller
    return cipher;
}

private SecretKey generateSecretKey() throws NoSuchAlgorithmException {
    // Generate a new AES key with a key size of 256 bits using a secure random number generator
    KeyGenerator keyGenerator = KeyGenerator.getInstance("AES");
    keyGenerator.init(256, new SecureRandom());
    return keyGenerator.generateKey();
}
