public double calculateModificationFunction(double[] gainValues, int[] gainChangePositions, int fragmentSize) {
    double[] modificationFunction = new double[fragmentSize];
    for (int i = 0; i < gainChangePositions.length - 1; i++) {
        double startGain = gainValues[i];
        double endGain = gainValues[i + 1];
        int startPosition = gainChangePositions[i];
        int endPosition = gainChangePositions[i+1];
        double gainDiff = endGain - startGain;
        double gainIncrement = gainDiff / (endPosition - startPosition);
        for (int j = startPosition; j < endPosition; j++) {
            double gainValue = startGain + (gainIncrement * (j - startPosition));
            modificationFunction[j] = gainValue;
        }
    }
    return modificationFunction[fragmentSize - 1];
}
