import org.apache.commons.math3.linear.Array2DRowRealMatrix;
import org.apache.commons.math3.linear.RealMatrix;

public RealMatrix createPermutationMatrix(int[] ipiv) {
    int n = ipiv.length;
    double[][] data = new double[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) {
                data[i][j] = 1.0;
            } else {
                data[i][j] = 0.0;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        if (ipiv[i] != i) {
            int j = ipiv[i];
            for (int k = 0; k < n; k++) {
                double temp = data[i][k];
                data[i][k] = data[j][k];
                data[j][k] = temp;
            }
        }
    }
    return new Array2DRowRealMatrix(data);
}
