@Override
protected void subAppend(LoggingEvent event) {
    if (isRollingFileExist() && isRollingNeededForEvent(event)) {
        rollOver();
    }
    super.subAppend(event);
}

private boolean isRollingFileExist() {
    File file = new File(getFile());
    return file.exists();
}

private boolean isRollingNeededForEvent(LoggingEvent event) {
    return ((CountingQuietWriter) qw).getCount() >= maxFileSize || super.isTriggeringEvent(event);
}

private void rollOver() {
    synchronized (this) {
        if (qw != null && isRollingFileExist()) {
            long logTimestamp = System.currentTimeMillis();
            File newFile = new File(getFile() + "." + logTimestamp);
            renameFile(newFile);
            try {
                setQWForNewFile(newFile.getAbsolutePath());
            } catch (IOException e) {
                errorHandler.error("setFile(" + fileName + ", false) call failed.", e, ErrorCode.FILE_OPEN_FAILURE);
            }
        }
    }
}

private void renameFile(File file) {
    new File(getFile()).renameTo(file);
}
