public static int[] nonZeroCountsAndPermute(int[] parent, int[][] ll) {
    int n = parent.length;
    int[] s = new int[n];
    int[] w = new int[n];
    int[] nonZeros = new int[n];
    Arrays.fill(nonZeros, 1);

    // Compute the non-zero counts of Householder vectors
    for (int i = n - 1; i >= 0; i--) {
        s[i] = 1;
        int k = ll[i].length;
        for (int p = 0; p < k; p++) {
            int j = ll[i][p];
            if (j > i) {
                s[i] += s[j];
            }
        }
        w[i] = nonZeros[i] / s[i];
        int tmp = 0;
        for (int p = 0; p < k; p++) {
            int j = ll[i][p];
            if (j > i) {
                nonZeros[j] += w[i];
                tmp += w[i];
            }
        }
        nonZeros[i] -= tmp;
    }

    // Compute the permutation matrix
    int[] perm = new int[n];
    for (int i = 0; i < n; i++) {
        perm[i] = i;
    }
    for (int i = n - 1; i >= 0; i--) {
        int k = 0;
        int max = -1;
        for (int p = 0; p < ll[i].length; p++) {
            int j = ll[i][p];
            if (j > i && s[j] > max) {
                max = s[j];
                k = j;
            }
        }
        if (parent[i] == k) {
            continue;
        }
        int tmp = perm[i];
        perm[i] = perm[k];
        perm[k] = tmp;
    }
    return nonZeros;
}
