public static void copyInstanceResourcesToDisk(Instance instance, Map<String, byte[]> fileNameToFileContent) throws IOException {
    File instanceResourcesDir = new File(instance.getResourcesDir());

    if(!instanceResourcesDir.exists()) {
        instanceResourcesDir.mkdir();
    }

    for(Map.Entry<String, byte[]> entry : fileNameToFileContent.entrySet()) {
        File file = new File(instanceResourcesDir.getAbsolutePath() + File.separator + entry.getKey());
        FileOutputStream output = new FileOutputStream(file);

        try {
            output.write(entry.getValue());
        } finally {
            output.close();
        }
    }
}
