public static void square(int x, int[] result) {
    int[] x2 = new int[10];
    int carry, t;
    int i, j;

    x2[0] = x + x;
    for (i = 0; i < 9; i++) {
        carry = 0;
        for (j = i + 1; j < 10; j++) {
            t = x2[i] * x2[j - i];
            t += carry + x2[j];
            x2[j] = t & 0xffff;
            carry = t >>> 16;
        }
        x2[i] = x2[i] * x2[i] + carry;
    }
    System.arraycopy(x2, 0, result, 0, 10);
}
