public static boolean isVersionNewer(String newer, String older) {
    String[] newerParts = newer.split("\\.");
    String[] olderParts = older.split("\\.");

    // iterate through each part and compare them
    int index = 0;
    while (index < newerParts.length && index < olderParts.length) {
        int newerPart = Integer.parseInt(newerParts[index]);
        int olderPart = Integer.parseInt(olderParts[index]);

        if (newerPart > olderPart) {
            return true;
        } else if (newerPart < olderPart) {
            return false;
        }

        index++;
    }

    // all parts up to this point are identical, so the version with more parts is newer
    return newerParts.length > olderParts.length;
}
