public Map<String, Integer> commonTags(List<Map<String, Integer>> tagList) {
    Map<String, Integer> commonTagsMap = new HashMap<>();
    if (tagList == null || tagList.isEmpty() || tagList.size() == 1) {
        return commonTagsMap;
    }
    Map<String, Integer> firstTagsMap = tagList.get(0);
    for (String tag : firstTagsMap.keySet()) {
        int count = 1;
        for (int i = 1; i < tagList.size(); i++) {
            Map<String, Integer> tempTagsMap = tagList.get(i);
            if (tempTagsMap.containsKey(tag)) {
                count++;
            }
        }
        if (count == tagList.size()) {
            commonTagsMap.put(tag, firstTagsMap.get(tag));
        }
    }
    return commonTagsMap;
}
