public static int encodeASN1Integer(int value, byte[] buf) {
    int pos = buf.length - 1;
    if (value < 0) {
        while (value != 0) {
            buf[pos--] = (byte)(value & 0xff);
            value >>= 8;
        }
        buf[pos--] = (byte) 0xff;
    } else {
        do {
            buf[pos--] = (byte)(value & 0xff);
            value >>= 8;
        } while (value != 0);
    }
    return buf.length - pos - 1;
}
