public static String trimLeadingCharacters(String input, String chars) {
    if (input == null || chars == null) {
        return input;
    }

    int inputLength = input.length();
    int charsToTrim = 0;

    while (charsToTrim < inputLength && chars.contains(String.valueOf(input.charAt(charsToTrim)))) {
        charsToTrim++;
    }

    return input.substring(charsToTrim);
}
