public byte[] readFromRingBufferOrReader(RingBuffer buffer, Reader reader) throws IOException {
    if(buffer.isNotEmpty()) {
        return buffer.read();
    } else {
        char[] charBuffer = new char[1024];
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();

        int readChars;
        while((readChars = reader.read(charBuffer, 0, charBuffer.length)) != -1) {
            byte[] byteArray = new String(charBuffer, 0, readChars).getBytes();
            outputStream.write(byteArray);
            if(buffer.hasFreeSpace(byteArray.length)) {
                buffer.write(byteArray);
                break;
            }
        }
        return outputStream.toByteArray();
    }
}
