public byte[] getPDF() throws IOException {
    ByteArrayOutputStream pdfStream = new ByteArrayOutputStream();
    Document pdfDoc = new Document();
    PdfWriter.getInstance(pdfDoc, pdfStream);
    pdfDoc.open();

    for (Iterator<PdfObject> it = this.listIterator(); it.hasNext(); ) {
        PdfObject pdfObj = it.next();
        if (pdfObj != null) {
            PdfIndirectReference ref = pdfObj.getIndRef();
            if (ref != null && !ref.getReader().isRebuilt()) {
                ref.getReader().unethicalreading = true;
                pdfDoc.add((Element) pdfObj);
            }
        }
    }

    pdfDoc.close();
    return pdfStream.toByteArray();
}
