public static int[] calculateFieldsFromJulianDay(int julianDay) {
    int j = julianDay + 1402;
    int k = (j - 1) / 1461;
    int l = j - 1461 * k;
    int n = (l - 1) / 365 - l / 1461;
    int i = l - 365 * n + n / 4;
    int j2 = i / 31;
    int k2 = i - 31 * j2;
    int l2 = (j2 - 1) / 10;
    int m = j2 - 12 * l2 + 2;
    return new int[]{k, n, m, k2, julianDay - 1721425 + 1, (julianDay + 1) % 7};
}
