public void liftConstructionNode(Node constructionNode, List<Node> orderComparators) {
    int idx = orderComparators.indexOf(constructionNode);
    if (idx > 0) {
        // Swap construction node with previous node
        Node temp = orderComparators.get(idx - 1);
        orderComparators.set(idx - 1, constructionNode);
        orderComparators.set(idx, temp);
    }
}
