public void generateDeletionQueries(int deleteCondition, int maxChunkSize) {
    // First query
    String query1 = "SELECT COUNT(*) FROM table WHERE condition = " + deleteCondition;
    int numRowsToDelete = executeQuery(query1);

    // Second query
    if (numRowsToDelete > maxChunkSize) {
        String query2 = "SELECT id FROM table WHERE condition = " + deleteCondition + " ORDER BY id LIMIT " + maxChunkSize + ", 1";
        int cutoffValue = executeQuery(query2);

        // Third query
        String query3 = "DELETE FROM table WHERE condition = " + deleteCondition + " AND id <= " + cutoffValue;
        executeQuery(query3);
    } else {
        // Third query
        String query3 = "DELETE FROM table WHERE condition = " + deleteCondition;
        executeQuery(query3);
    }
}

