public String cleanUp(Collection<String> values) {
    if(values == null || values.isEmpty()) {
        return "";
    }
    String regex = "[\\s\\-()]+";
    StringBuilder sb = new StringBuilder();
    for(String s : values) {
        if(s != null) {
            String cleanedUpString = s.replaceAll(regex, "");
            sb.append(cleanedUpString).append(" ");
        }
    }
    return sb.toString().trim();
}
