public List<Icon> getApplicationIcons() {
    List<Icon> icons = new ArrayList<>();

    try {
        ApplicationInfo appInfo = getPackageManager().getApplicationInfo(getPackageName(), PackageManager.GET_META_DATA);
        Bundle metaData = appInfo.metaData;

        if (metaData != null) {
            if (metaData.containsKey("fileIcon")) {
                int fileIconResId = metaData.getInt("fileIcon");
                icons.add(Icon.createWithResource(this, fileIconResId));
            }
            if (metaData.containsKey("colorIcon")) {
                int colorIconResId = metaData.getInt("colorIcon");
                icons.add(Icon.createWithResource(this, colorIconResId));
            }
            if (metaData.containsKey("adaptiveIcon")) {
                int adaptiveIconResId = metaData.getInt("adaptiveIcon");
                icons.add(Icon.createWithResource(this, adaptiveIconResId));
            }
            // add other icons as necessary
        }

    } catch (PackageManager.NameNotFoundException e) {
        e.printStackTrace();
    }

    return icons;
}
