public void writeTagsAsJavaScriptClasses(Writer writer, List<String> tags) throws IOException {
    for (String tag : tags) {
        writer.write("class " + tag + "Tag {\n");
        writer.write("  constructor(attributes) {\n");
        writer.write("    this.attributes = attributes;\n");
        writer.write("  }\n");
        writer.write("  render() {\n");
        writer.write("    return `<" + tag + " ${this.getAttributeString()}>${this.renderChildren()}</" + tag + ">`;\n");
        writer.write("  }\n");
        writer.write("  getAttributeString() {\n");
        writer.write("    let attributesArray = [];\n");
        writer.write("    for (const [key, value] of Object.entries(this.attributes)) {\n");
        writer.write("      attributesArray.push(`${key}=${value}`);\n");
        writer.write("    }\n");
        writer.write("    return attributesArray.join(' ');\n");
        writer.write("  }\n");
        writer.write("  renderChildren() {\n");
        writer.write("    return '';\n");
        writer.write("  }\n");
        writer.write("}\n\n");
    }
}
