public void uploadTextAsync(String text, ProgressListener progressListener, ResponseListener responseListener) {
    RequestBody requestBody = RequestBody.create(MediaType.parse("text/plain"), text);

    Request request = new Request.Builder()
            .post(requestBody)
            .url("https://example.com/upload")
            .build();

    OkHttpClient client = new OkHttpClient.Builder()
            .build();

    client.newCall(request).enqueue(new Callback() {
        @Override
        public void onFailure(Call call, IOException e) {
            responseListener.onFailure(e.getMessage());
        }

        @Override
        public void onResponse(Call call, Response response) throws IOException {
            if (response.isSuccessful()) {
                responseListener.onSuccess(response.body().string());
            } else {
                responseListener.onFailure("Upload failed");
            }
        }
    });
}
