public synchronized Buffer getBuffer() {
    // Check if there are any buffers available
    if (buffers.size() < _bufferCount) {
        // Create a new buffer and add it to the list of buffers
        Buffer buffer = new Buffer();
        buffers.add(buffer);
        return buffer;
    } else {
        // Get the least recently used buffer
        Buffer lruBuffer = buffers.get(0);
        long minTimestamp = lruBuffer.getLastUsedTimestamp();

        for (Buffer buffer : buffers) {
            if (buffer.getLastUsedTimestamp() < minTimestamp) {
                lruBuffer = buffer;
                minTimestamp = buffer.getLastUsedTimestamp();
            }
        }

        lruBuffer.clear();
        return lruBuffer;
    }
}
