import org.apache.tools.ant.filters.FilterSet;

public void filterInputStream(InputStream input, OutputStream output, FilterSet set) throws IOException {
    set.setProject(null);
    int ch = input.read();
    while (ch != -1) {
        byte b = (byte) ch;
        if (!set.filter(b)) {
            output.write((int) b);
        }
        ch = input.read();
    }
}
