public int getContributedElectrons(String atom) {
    int electrons = 0;
    switch(atom) {
        case "C":
        case "Si":
            electrons = 4;
            break;
        case "N":
        case "P":
            electrons = 5;
            break;
        case "O":
        case "S":
            electrons = 6;
            break;
        case "F":
        case "Cl":
            electrons = 7;
            break;
        default:
            throw new IllegalArgumentException("Invalid atom type.");
    }
    return electrons;
}
