public String parseBackwards(String statement) {
    // Find last occurrence of '('
    int lastOpenParenthesisIndex = statement.lastIndexOf('(');
    if (lastOpenParenthesisIndex == -1) {
        // No more parentheses to parse
        return statement;
    }

    // Find corresponding closing parenthesis by counting parentheses after lastOpenParenthesisIndex
    int openParenthesisCount = 1; // Start at 1 to account for first parenthesis
    int closingParenthesisIndex = lastOpenParenthesisIndex;
    while (openParenthesisCount > 0) {
        closingParenthesisIndex--;
        char currentChar = statement.charAt(closingParenthesisIndex);
        if (currentChar == ')') {
            openParenthesisCount++;
        } else if (currentChar == '(') {
            openParenthesisCount--;
        }
    }
    // Parse the expression inside parentheses recursively
    String expression = statement.substring(lastOpenParenthesisIndex + 1, closingParenthesisIndex);
    String parsedExpression = parseBackwards(expression);

    // Replace expression in original statement and return
    String result = statement.substring(0, lastOpenParenthesisIndex) + parsedExpression + statement.substring(closingParenthesisIndex + 1);
    return parseBackwards(result);
}
