public static String parseDataset(String path) throws IOException {
    String data = "";
    BufferedReader reader = null;
    try {
        reader = new BufferedReader(new FileReader(path));
        String line = "";
        while ((line = reader.readLine()) != null) {
            data += line + "\n";
        }
    } finally {
        if (reader != null) {
            reader.close();
        }
    }
    return data;
}
