public Map<String, Integer> computeDistribution(String f1, String f2) {
    Map<String, Integer> distribution = new HashMap<>();

    // Factorize f1
    while (!f1.equals("")) {
        int index = f1.indexOf("*");
        if (index != -1) {
            String factor = f1.substring(0, index);
            f1 = f1.substring(index + 1);
            if (distribution.containsKey(factor)) {
                distribution.put(factor, distribution.get(factor) + 1);
            } else {
                distribution.put(factor, 1);
            }
        } else {
            if (distribution.containsKey(f1)) {
                distribution.put(f1, distribution.get(f1) + 1);
            } else {
                distribution.put(f1, 1);
            }
            f1 = "";
        }
    }

    // Factorize f2
    while (!f2.equals("")) {
        int index = f2.indexOf("*");
        if (index != -1) {
            String factor = f2.substring(0, index);
            f2 = f2.substring(index + 1);
            if (distribution.containsKey(factor)) {
                distribution.put(factor, distribution.get(factor) + 1);
            } else {
                distribution.put(factor, 1);
            }
        } else {
            if (distribution.containsKey(f2)) {
                distribution.put(f2, distribution.get(f2) + 1);
            } else {
                distribution.put(f2, 1);
            }
            f2 = "";
        }
    }

    return distribution;
}
