public String formatFileSize(long fileSize, String units) {
    String[] sizes = {"B", "KB", "MB", "GB", "TB"};
    int index = 0;
    double size = fileSize;
    while (size >= 1024 && index < sizes.length - 1) {
        size /= 1024;
        index++;
    }
    return String.format("%.2f %s", size, sizes[index]);
}
