import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import javax.imageio.ImageIO;

public static byte[] drawCoverageTile(short[][] pixelValues) throws IOException {
    int width = pixelValues[0].length;
    int height = pixelValues.length;

    BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
    Graphics2D g2d = image.createGraphics();

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int pixelValue = pixelValues[y][x] & 0xFFFF; // Convert the unsigned short to int
            Color color = new Color(pixelValue, pixelValue, pixelValue);
            g2d.setColor(color);
            g2d.drawLine(x, y, x, y);
        }
    }

    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    ImageIO.write(image, "png", outputStream);

    return outputStream.toByteArray();
}
