public List<Env<AttrContext>> attributeParseTrees(List<JCCompilationUnit> parseTrees, Context context) {
    List<Env<AttrContext>> envs = new ArrayList<>();
    SourceCompleter completer = new SourceCompleter(context);
    try {
        for (JCCompilationUnit parseTree : parseTrees) {
            Env<AttrContext> env = completer.enterTrees(parseTree);
            env.toplevel.complete();
            env.toplevel.attribute();
            envs.add(env);
        }
    } catch (Symbol.CompletionFailure e) {
        // ignore and continue with other entries
    }
    return envs;
}
