public XMethod findMethod(Class<?> javaClass, String methodName, String methodSig, JavaClassAndMethodChooser chooser) {
    Method[] methods = javaClass.getDeclaredMethods();
    for (Method method : methods) {
        if (method.getName().equals(methodName) && Arrays.equals(method.getParameterTypes(), getParameterTypes(methodSig))) {
            XMethod xMethod = chooser.chooseMethod(javaClass.getName(), method.getName(), methodSig);
            if (xMethod != null) {
                return xMethod;
            }
        }
    }
    return null;
}

private Class<?>[] getParameterTypes(String methodSig) {
    // Parse methodSig to get the parameter types and return them as an array of Class objects
    // Example implementation:
    String[] sigParts = methodSig.split(":");
    List<Class<?>> paramTypes = new ArrayList<>();
    for (String sigPart : sigParts) {
        if (sigPart.equals("I")) {
            paramTypes.add(int.class);
        } else if (sigPart.equals("J")) {
            paramTypes.add(long.class);
        } else if (sigPart.equals("Z")) {
            paramTypes.add(boolean.class);
        } else if (sigPart.equals("Ljava/lang/String;")) {
            paramTypes.add(String.class);
        } // ... and so on for other possible parameter types
    }
    return paramTypes.toArray(new Class<?>[0]);
}
