import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.Iterator;
import java.util.function.BiConsumer;

public void importData(Iterator<?> iter, int offset, int count, String filter, PreparedStatement stmt, int batchSize,
                        long batchInterval, BiConsumer<PreparedStatement, ?> stmtSetter) {
    try {
        Connection conn = stmt.getConnection();
        while (iter.hasNext()) {
            Object obj = iter.next();
            if ((offset--) > 0) {
                continue;
            }
            if ((count--) == 0) {
                break;
            }
            if (filter != null && !filter.isEmpty()) {
                if (!obj.toString().matches(filter)) {
                    continue;
                }
            }
            stmtSetter.accept(stmt, obj);
            stmt.addBatch();
            if (batchSize > 0 && stmt.getBatchSize() == batchSize) {
                stmt.executeBatch();
                stmt.clearBatch();
                conn.commit();
                if (batchInterval > 0) {
                    try {
                        Thread.sleep(batchInterval);
                    } catch (InterruptedException e) {
                        throw new UncheckedSQLException(e);
                    }
                }
            }
        }
        if (stmt.getBatchSize() > 0) {
            stmt.executeBatch();
            stmt.clearBatch();
            conn.commit();
        }
    } catch (SQLException e) {
        throw new UncheckedSQLException(e);
    }
}
