public static void sortByDivider(List<Sortable> list, Object divider) {
    Collections.sort(list, (o1, o2) -> {
        if (o1.getDivider() == null && o2.getDivider() == null) {
            return 0;
        } else if (o1.getDivider() == null) {
            return 1;
        } else if (o2.getDivider() == null) {
            return -1;
        } else if (o1.getDivider().equals(divider) && !o2.getDivider().equals(divider)) {
            return -1;
        } else if (!o1.getDivider().equals(divider) && o2.getDivider().equals(divider)) {
            return 1;
        } else {
            return o1.compareTo(o2);
        }
    });
}
