public ContentTree getFrameDetails() {

    ContentTree tree = new ContentTree();

    // get all frames in the document
    Frame[] frames = Frame.getFrames();

    // iterate over all frames to get their sizes and contents
    for (int i = 0; i < frames.length; i++) {
        int frameWidth = frames[i].getWidth();
        int frameHeight = frames[i].getHeight();
        String frameContents = frames[i].getContents();

        // create a new content node for the current frame
        ContentNode node = new ContentNode();
        node.addProperty("width", frameWidth);
        node.addProperty("height", frameHeight);
        node.addProperty("contents", frameContents);

        // add the new node to the content tree
        tree.addChild(node);
    }

    return tree;
}
