public static void printBeautifulLogs(VoltLogger vLogger, String msg, String level) {
    int maxLength = vLogger.getMaxLineLength() - 4; // considering 4 spaces for padding

    String[] words = msg.split(" ");
    StringBuilder sb = new StringBuilder();
    sb.append(level).append(":");
    int currentLength = level.length() + 1;

    for (String word : words) {
        if (currentLength + word.length() + 1 > maxLength) {
            vLogger.log(sb.toString());
            sb = new StringBuilder();
            sb.append("    "); // padding
            currentLength = 4;
        }
        sb.append(" ").append(word);
        currentLength += word.length() + 1;
    }

    vLogger.log(sb.toString());
}
