public static InetAddress[] resolveCname(String hostname) throws NamingException {
    InitialDirContext context = new InitialDirContext();
    Attributes attrs;
    Attribute attr;
    String cname = hostname;
    while ((attrs = context.getAttributes(cname, new String[] {"CNAME"})) != null) {
        attr = attrs.get("CNAME");
        if (attr == null) {
            break;
        }
        cname = (String) attr.get();
    }
    return InetAddress.getAllByName(cname);
}
