public static double[] applyPowerNormalization(double[] vector, double aParameter) {
    double norm = 0;
    for (int i = 0; i < vector.length; i++) {
        norm += Math.pow(Math.abs(vector[i]), aParameter);
    }
    norm = Math.pow(norm, 1.0 / aParameter);
    for (int i = 0; i < vector.length; i++) {
        vector[i] = vector[i] / norm;
    }
    return vector;
}
