public ScopeBlock getAssignedScopeBlock(ScopeBlock sb, int pc) {
    ScopeBlock result = null;
    for (Variable var : sb.getVariables()) {
        if (var.getPC() == pc) {
            return sb;
        }
    }
    for (ScopeBlock child : sb.getChildren()) {
        result = getAssignedScopeBlock(child, pc);
        if (result != null) {
            return result;
        }
    }
    return result;
}
