public static void savePropertiesInAscendingOrder(Properties props, OutputStream out) throws IOException {
    // Get the keys and sort them in ascending order
    List<String> keys = new ArrayList<>(props.stringPropertyNames());
    Collections.sort(keys);

    // Write the properties to the output stream in ascending order
    for (String key : keys) {
        String value = props.getProperty(key);
        out.write((key + "=" + value + "\n").getBytes());
    }
}
