public Fst composeFst(Fst fst1, Fst fst2, Semiring semiring) {
    // Augmenting fst1 and fst2 to avoid multiple epsilon paths in the resulting Fst
    fst1 = fst1.arcsort();
    fst1 = fst1.rmepsilon();
    fst1 = fst1.determinize();
    fst2 = fst2.arcsort();
    fst2 = fst2.rmepsilon();
    fst2 = fst2.determinize();

    // Composing the two Fsts using the semiring provided
    Fst composedFst = new Fst();
    composedFst.setSemiring(semiring);
    composedFst = fst1.compose(fst2);

    // Returning the composed Fst
    return composedFst;
}
