public class EntityUtils {

    public static Map<String, Attribute> deepCopyAttributes(EntityType entityType, EntityType entityTypeCopy, AttributeFactory attrFactory) {
        Map<String, Attribute> attrMap = new LinkedHashMap<>();
        for (Attribute attribute : entityType.getAttributes()) {
            Attribute copy = attrFactory.create(attribute.getType());
            copy.setName(attribute.getName());
            copy.setDescription(attribute.getDescription());
            copy.setRequired(attribute.isRequired());
            copy.setDefaultValue(attribute.getDefaultValue());
            copy.setMinValue(attribute.getMinValue());
            copy.setMaxValue(attribute.getMaxValue());
            copy.setLength(attribute.getLength());
            copy.setPrecision(attribute.getPrecision());
            copy.setScale(attribute.getScale());
            copy.setIsTitle(attribute.isTitle());
            copy.setIsUnique(attribute.isUnique());
            copy.setIsIndex(attribute.isIndex());
            copy.setIsReadOnly(attribute.isReadOnly());
            entityTypeCopy.addAttribute(copy);
            attrMap.put(attribute.getId(), copy);
        }
        return attrMap;
    }
}
