public double computeMaxSpiralRadius(int dimension, int[] start) {
    int startX = start[0];
    int startY = start[1];
    double maxRadius = 0;
    int x, y, dx, dy;
    for (int i = 0; i < dimension; i++) {
        x = startX + i;
        y = startY;
        maxRadius = Math.max(maxRadius, Math.sqrt(Math.pow(x - startX, 2) + Math.pow(y - startY, 2)));
        for (int j = 0; j < i; j++) {
            dx = startX + i - j;
            dy = startY + j;
            maxRadius = Math.max(maxRadius, Math.sqrt(Math.pow(dx - startX, 2) + Math.pow(dy - startY, 2)));
            dx = startX - i + j;
            dy = startY - j;
            maxRadius = Math.max(maxRadius, Math.sqrt(Math.pow(dx - startX, 2) + Math.pow(dy - startY, 2)));
            dx = startX - j;
            dy = startY + i - j;
            maxRadius = Math.max(maxRadius, Math.sqrt(Math.pow(dx - startX, 2) + Math.pow(dy - startY, 2)));
            dx = startX + j;
            dy = startY - i + j;
            maxRadius = Math.max(maxRadius, Math.sqrt(Math.pow(dx - startX, 2) + Math.pow(dy - startY, 2)));
        }
    }
    return maxRadius;
}
