public LoginContext getLoginContext(Object credential) throws GeneralSecurityException {
    LoginContext lc = null;
    try {
        lc = new LoginContext("MyLoginContext", new CredentialHandler(credential));
        lc.login();
    } catch (LoginException e) {
        throw new GeneralSecurityException("Unable to obtain login context", e);
    }
    return lc;
}

class CredentialHandler implements javax.security.auth.callback.CallbackHandler {
    private Object credential;

    public CredentialHandler(Object credential) {
        this.credential = credential;
    }

    @Override
    public void handle(javax.security.auth.callback.Callback[] callbacks) {
        javax.security.auth.callback.NameCallback nc = (javax.security.auth.callback.NameCallback) callbacks[0];
        nc.setName(credential.toString());
    }
}
