public static <T> Stream<T> createCloseHandlingProxy(Stream<T> targetStream, Runnable closeHandler) {
        Objects.requireNonNull(targetStream);
        Objects.requireNonNull(closeHandler);

        class CloseHandlingProxy implements InvocationHandler {

            private final Stream<T> targetStream;

            public CloseHandlingProxy(Stream<T> targetStream) {
                this.targetStream = targetStream;
            }

            @Override
            public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
                if (method.getName().equals("close")) {
                    closeHandler.run();
                }
                return method.invoke(targetStream, args);
            }
        }

        CloseHandlingProxy closeHandlingProxy = new CloseHandlingProxy(targetStream);
        Class<?>[] interfaces = {Stream.class};
        return (Stream<T>) Proxy.newProxyInstance(targetStream.getClass().getClassLoader(), interfaces, closeHandlingProxy);
    }
