public void addValueToMap(Map<Object, Object> map, Object key, Object value) {
    if (map.containsKey(key)) {
        Object previousValue = map.get(key);
        if (previousValue instanceof List) {
            ((List<Object>)previousValue).add(value);
        } else {
            List<Object> values = new ArrayList<>();
            values.add(previousValue);
            values.add(value);
            map.put(key, values);
        }
    } else {
        map.put(key, value);
    }
}
