public static IsoEra determinePreferredEra(LocalDate date) {
    if (date.isBefore(LocalDate.of(1,1,1))) {
        throw new IllegalArgumentException("Date out of range");
    } else if (date.isBefore(LocalDate.of(1582,10,15))) {
        return IsoEra.BCE;
    } else {
        return IsoEra.CE;
    }
}
