    if(client == null) {
        throw new IllegalArgumentException("Client cannot be null.");
    }

    Paginator<Record> paginator = currentPage.getPaginator();
    if(paginator == null) {
        throw new IllegalArgumentException("Current page does not have a paginator.");
    }

    if(!paginator.hasPreviousPage()) {
        throw new TwilioException("Current page does not have a previous page.");
    }

    return paginator.previousPage();
}
