public static String substituteSystemProperties(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int i = 0;
    int j;
    while ((j = input.indexOf("${", i)) >= 0) {
        sb.append(input.substring(i, j));
        int k = input.indexOf('}', j + 2);
        if (k < 0) {
            throw new IllegalArgumentException(
                    "Missing closing brace at position " + j + ": "
                            + input);
        }
        String key = input.substring(j + 2, k);
        String value = System.getProperty(key);
        if (value == null) {
            value = "";
        }
        sb.append(value);
        i = k + 1;
    }
    sb.append(input.substring(i));
    return sb.toString();
}
