@Override
public int boundaryForComputingSegment(int start, int end, int blockSize) {
    int boundary = end;
    if (start + blockSize < end) {
        boundary = start + blockSize;
        while (boundary < end && !isBoundaryCharacter(characters[boundary])) {
            boundary++;
        }
    }
    return boundary;
}

private boolean isBoundaryCharacter(int c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r';
}
