public static double calculateStdDeviation(double[] values, double mean) {
    double sum = 0.0;
    for (double value : values) {
        sum += Math.pow(value - mean, 2);
    }
    double variance = sum / (double) (values.length - 1);
    return Math.sqrt(variance);
}
