public static int lastIndexOfIgnoreCase(String src, String subS, int startIndex) {
      if (subS.length() == 0) {
          return startIndex >= src.length() ? src.length() : startIndex;
      }
      for (int i = startIndex; i < src.length() - subS.length() + 1; i++) {
          if (src.substring(i, i + subS.length()).equalsIgnoreCase(subS)) {
              return i;
          }
      }
      return -1;
  }
