private void getWeeklyDates(Calendar calendar, int frequency, List<Date> dates)
   {
      int currentDay = calendar.get(Calendar.DAY_OF_WEEK);
      while (moreDates(calendar, dates))
      {
         int offset = 0;
         for (int dayIndex = 0; dayIndex < 7; dayIndex++)
         {
            if (getWeeklyDay(Day.getInstance(currentDay)))
            {
               if (offset != 0)
               {
                  calendar.add(Calendar.DAY_OF_YEAR, offset);
                  offset = 0;
               }
               if (!moreDates(calendar, dates))
               {
                  break;
               }
               dates.add(calendar.getTime());
            }
            ++offset;
            ++currentDay;
            if (currentDay > 7)
            {
               currentDay = 1;
            }
         }
         if (frequency > 1)
         {
            offset += (7 * (frequency - 1));
         }
         calendar.add(Calendar.DAY_OF_YEAR, offset);
      }
   },0

public List<String> concatenate(List<String> sequence, List<Integer> featureLocations) throws IllegalStateException {
    List<String> splicedData = new ArrayList<>();
    int start = featureLocations.get(0);
    int end = featureLocations.size() == 1 ? sequence.size() : featureLocations.get(1);
    for (int i = 1; i < featureLocations.size(); i++) {
        if (featureLocations.get(i) <= featureLocations.get(i - 1)) {
            throw new IllegalStateException("Out of order FeatureI locations.");
        }
        if (end > featureLocations.get(i)) {
            throw new IllegalStateException("Overlapping FeatureI locations detected.");
        }
        splicedData.add(String.join("", sequence.subList(start, end)));
        start = featureLocations.get(i);
        end = i == featureLocations.size() - 1 ? sequence.size() : featureLocations.get(i + 1);
    }
    splicedData.add(String.join("", sequence.subList(start, end)));
    return splicedData;
}
