public DescriptionStrategy createMonthDescriptionStrategy(Locale bundle, CronFieldExpression expression) {
    DescriptionStrategy descriptionStrategy = new DescriptionStrategy(bundle, expression);
    descriptionStrategy.setNthFieldValueNameProvider(new NthFieldValueNameProvider(bundle));
    descriptionStrategy.setTimeZone(TimeZone.getDefault());
    descriptionStrategy.setExpressionValidator(new MonthValueValidator());
    descriptionStrategy.setSingleItemDescriptionGenerator(new SingleMonthDescriptionGenerator(bundle));
    descriptionStrategy.setIntervalDescriptionGenerator(new IntervalMonthDescriptionGenerator(bundle));
    descriptionStrategy.setRangeDescriptionGenerator(new RangeMonthDescriptionGenerator(bundle));
    descriptionStrategy.setLastDayOffsetDescriptionGenerator(new LastDayOfMonthDescriptionGenerator(bundle));
    descriptionStrategy.setNthDayOfWeekDescriptionGenerator(new NthDayOfMonthDescriptionGenerator(bundle));
    descriptionStrategy.setNearestWeekdayDescriptionGenerator(new NearestWeekdayOfMonthDescriptionGenerator(bundle));
    descriptionStrategy.setWeekdayRangeDescriptionGenerator(new WeekdayRangeOfMonthDescriptionGenerator(bundle));
