public String getPath(String filename) {
   int lastSlashIndex = filename.lastIndexOf("/");
   if (lastSlashIndex == -1) { // No slash found
       return "";
   } else if (lastSlashIndex == 0) { // Slash in first position
       return "/";
   } else { // Found slash somewhere else in the string
       return filename.substring(0, lastSlashIndex);
   }
}
