public GeneralSubtrees union(GeneralSubtrees other) {
    List<GeneralSubtree> allSubtrees = new ArrayList<>();

    // Add all subtrees from this GeneralSubtrees
    for (GeneralSubtree subtree : this.subtrees) {
        allSubtrees.add(subtree);
    }

    // Add subtrees from the other GeneralSubtrees not already present
    for (GeneralSubtree subtree : other.subtrees) {
        if (!allSubtrees.contains(subtree)) {
            allSubtrees.add(subtree);
        }
    }

    return new GeneralSubtrees(allSubtrees.toArray(new GeneralSubtree[allSubtrees.size()]));
}
