        case RUNNING:
            return OldJobRunState.RUNNING;
        case SUCCEEDED:
            return OldJobRunState.COMPLETED;
        case FAILED:
        case ERROR:
            return OldJobRunState.FAILED;
        case KILLED:
            return OldJobRunState.KILLED;
        default:
            throw new IllegalArgumentException("Invalid new job runstate: " + newState);
    }
}
