public void replaceExternalCSS(Document doc, String basePath) {
    NodeList linkNodes = doc.getElementsByTagName("link");

    for (int i = 0; i < linkNodes.getLength(); i++) {
        Node node = linkNodes.item(i);

        if (node.getAttributes().getNamedItem("rel").getNodeValue().equals("stylesheet") 
           && node.getAttributes().getNamedItem("href") != null) {

            String cssPath = node.getAttributes().getNamedItem("href").getNodeValue();
            String cssData = getCSSData(cssPath, basePath); // Fetch the CSS data from file

            Element styleNode = doc.createElement("style");
            styleNode.appendChild(doc.createTextNode(cssData));

            node.getParentNode().replaceChild(styleNode, node); // Replace <link> with <style> node
        }
    }
}

