public List<Grant> readGrantsFromJSONStream(CoronaSerializer coronaSerializer) throws IOException {
    List<Grant> grants = new ArrayList<>();
    JsonReader jsonReader = new JsonReader(new InputStreamReader(coronaSerializer.getJSONInputStream()));
    jsonReader.beginArray();
    while (jsonReader.hasNext()) {
        Grant grant = new Grant();
        jsonReader.beginObject();
        while (jsonReader.hasNext()) {
            String name = jsonReader.nextName();
            switch (name) {
                case "id":
                    grant.setId(jsonReader.nextInt());
                    break;
                case "name":
                    grant.setName(jsonReader.nextString());
                    break;
                case "description":
                    grant.setDescription(jsonReader.nextString());
                    break;
                case "amount":
                    grant.setAmount(jsonReader.nextInt());
                    break;
                case "deadline":
                    grant.setDeadline(LocalDate.parse(jsonReader.nextString()));
                    break;
                default:
                    jsonReader.skipValue();
                    break;
            }
        }
        jsonReader.endObject();
        grants.add(grant);
    }
    jsonReader.endArray();
    jsonReader.close();
    return grants;
}
