public static <T> T[] shuffle(T[] out, java.util.Random random) {
    for (int i = out.length - 1; i > 0; i--) {
        int index = random.nextInt(i + 1);
        T temp = out[index];
        out[index] = out[i];
        out[i] = temp;
    }
    return out;
}
