public HtmlTag loadHtmlTemplateStrict(InputStream inputStream) throws IOException, Mixer2JAXBException {
    try {
        JAXBContext jaxbContext = JAXBContext.newInstance(HtmlDocument.class);
        Unmarshaller unmarshaller = jaxbContext.createUnmarshaller();

        DocumentBuilderFactory docBuilderFactory = DocumentBuilderFactory.newInstance();
        docBuilderFactory.setNamespaceAware(true);

        DocumentBuilder docBuilder = docBuilderFactory.newDocumentBuilder();
        Document doc = docBuilder.parse(inputStream);

        return ((JAXBElement<HtmlDocument>) unmarshaller.unmarshal(doc)).getValue().getBody().getContent().get(0);

    } catch (JAXBException e) {
        throw new Mixer2JAXBException("Failed to parse xhtml.", e);
    } catch (ParserConfigurationException e) {
        throw new Mixer2JAXBException("A parser configuration exception has occurred.", e);
    } catch (SAXException e) {
        throw new Mixer2JAXBException("A SAX exception has occurred.", e);
    }
}
