public Iterator<Integer> descendingIterator(List<Integer> list) {
    final int size = list.size();
    return new Iterator<Integer>() {
        int current = size - 1;
        Set<Integer> seen = new HashSet<>();

        @Override
        public boolean hasNext() {
            return current >= 0;
        }

        @Override
        public Integer next() {
            if (current < 0) {
                throw new NoSuchElementException();
            }
            Integer result = list.get(current--);
            seen.add(result);
            while (current >= 0 && seen.contains(list.get(current))) {
                current--;
            }
            return result;
        }
    };
}
