import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ICUFormatter {
    private static final Pattern MESSAGE_PATTERN = Pattern.compile("\\{(\\d+)\\}");

    public static String formatICUMessage(String message) {
        StringBuilder result = new StringBuilder();
        Matcher matcher = MESSAGE_PATTERN.matcher(message);
        int lastIndex = 0;
        while (matcher.find()) {
            result.append(message.substring(lastIndex, matcher.start()));
            result.append('{').append(matcher.group(1)).append("}");
            lastIndex = matcher.end();
        }
        result.append(message.substring(lastIndex));
        return result.toString();
    }

    public static boolean isICUMessage(String message) {
        return message.contains("{") && message.contains("}") && MESSAGE_PATTERN.matcher(message).find();
    }
}
