public String quoteString(String s) {
    if (s == null || s.isEmpty()) {  // check if string is empty
        return "\"\"";  // return empty quoted string
    }

    boolean quoteRequired = false;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '"' || c == '\'') {  // check for quote characters
            quoteRequired = true;
            break;
        }
    }

    if (!quoteRequired) {
        return s;  // return original string if no quoting is required
    }

    StringBuilder sb = new StringBuilder();
    sb.append('"');  // add opening quote
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '"' || c == '\\') {  // escape quote and backslash characters
            sb.append('\\');
        }
        sb.append(c);
    }
    sb.append('"');  // add closing quote
    return sb.toString();
}
