public boolean linkLast(Node node) {
    if (size >= capacity) {
        return false; // Full, cannot link node
    }
    if (head == null) {
        head = node;
        tail = node;
    } else {
        tail.next = node;
        node.prev = tail;
        tail = node;
    }
    size++;
    return true; // Node linked successfully
}
