public ConsistentHash updateMembers(ConsistentHash baseCH, List<Address> actualMembers) {
    Set<Address> newMembers = new HashSet<Address>(actualMembers);
    ConsistentHash updatedCH = baseCH;

    for (Iterator<Address> it = updatedCH.getMembers().iterator(); it.hasNext(); ) {
        Address oldAddress = it.next();
        if (!newMembers.contains(oldAddress)) {
            it.remove();
        }
    }

    for (Address member : newMembers) {
        if (!updatedCH.getMembers().contains(member)) {
