import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.util.Objects;

public <T> T createObject(Class<T> className, Object... initargs) throws SetupException {
    try {
        Objects.requireNonNull(className, "className cannot be null");
        Constructor<T> constructor = className.getConstructor(getTypes(initargs));
        return constructor.newInstance(initargs);
    } catch (NoSuchMethodException | SecurityException | InstantiationException | IllegalAccessException | IllegalArgumentException | InvocationTargetException e) {
        throw new SetupException("Error creating object for class " + className.getName() + " with constructor arguments " + Arrays.toString(initargs), e);
    }
}

private Class<?>[] getTypes(Object[] initargs) {
    if (initargs == null) {
        return new Class<?>[0];
    }
    return Arrays.stream(initargs).map(Object::getClass).toArray(Class<?>[]::new);
}

public static class SetupException extends Exception {
    public SetupException(String message) {
        super(message);
    }

    public SetupException(String message, Throwable cause) {
