public byte[] addDoubleToArray(double[] array, double value) {
    int len = array.length;
    byte[] result = new byte[len * 8];
    for (int i = 0; i < len; i++) {
        long longBits = Double.doubleToLongBits(array[i]);
        for (int j = 0; j < 8; j++) {
            result[8 * i + j] = (byte) ((longBits >> (j * 8)) & 0xFF);
        }
    }
    long longBits = Double.doubleToLongBits(value);
    for (int j = 0; j < 8; j++) {
        result[8 * len + j] = (byte) ((longBits >> (j * 8)) & 0xFF);
    }
    return result;
}
