public static byte[] bigIntegerToByteArray(BigInteger bigInteger, boolean remainder) {
    byte[] bytes = bigInteger.toByteArray();
    if (remainder && bytes[0] < 0) {
        byte[] result = new byte[bytes.length + 1];
        result[0] = (byte) 0x80;
        System.arraycopy(bytes, 0, result, 1, bytes.length);
        return result;
    } else {
        return bytes;
    }
}
