public void writeZeroBranchSize(OutputStream out, int value, int max, int bits) throws IOException {
    int val = (value <= max) ? value : max;
    int shift = bits - 1;
    while (shift > 0) {
        if ((val & (1 << shift)) == 0) {
            out.write(0);
        } else {
            out.write(1);
            break;
        }
        shift--;
    }
    while (shift >= 0) {
        if ((val & (1 << shift)) == 0) {
            out.write(0);
        } else {
            out.write(1);
        }
        shift--;
    }
}
