public static Map<String,Object> readFileAttributes(Path filePath){

    Map<String,Object> fileAttributes = new HashMap<String,Object>();

    try {
        BasicFileAttributes attributes = Files.readAttributes(filePath, BasicFileAttributes.class);

        fileAttributes.put("creationTime", attributes.creationTime());
        fileAttributes.put("lastAccessTime", attributes.lastAccessTime());
        fileAttributes.put("lastModifiedTime", attributes.lastModifiedTime());
        fileAttributes.put("isDirectory", attributes.isDirectory());
        fileAttributes.put("isOther", attributes.isOther());
        fileAttributes.put("isRegularFile", attributes.isRegularFile());
        fileAttributes.put("isSymbolicLink", attributes.isSymbolicLink());
        fileAttributes.put("size", attributes.size());

    } catch (Exception e) {
        e.printStackTrace();
    }

    return fileAttributes;
}
