public void readFully(byte[] buf, int offset, int len) throws IOException {
    int bytesToRead = len;
    while (bytesToRead > 0) {
        int bytesRead = read(buf, offset, bytesToRead);
        if (bytesRead == -1) {
            throw new EOFException(
                "EOF reached before reading fully.");
        }
        bytesToRead -= bytesRead;
        offset += bytesRead;
    }
}
