public static void printProgress(int counter, int size, int step, String mode, String text) {
    int part = size/step;
    int progress = counter/part;
    String progressBar = "[";

    for(int i=0; i<step; i++){
        if(i<=progress){
            progressBar += "#";
        } else {
            progressBar += " ";
        }
    }
    progressBar += "]";

    if(mode.equals("percentage")){
        System.out.println(text + " " + (progress*100/step) + "% " + progressBar);
    } else if(mode.equals("fraction")){
        System.out.println(text + " " + progress + "/" + step + " " + progressBar);
    } else {
        System.out.println(text + " " + progressBar);
    }
}
