public RollStrategy getRollStrategy(Properties properties) {
    RollStrategy rollStrategy = null;
    TimeUnit timeUnit = TimeUnit.MINUTES; // start with per-minute strategy
    while (rollStrategy == null && timeUnit != null) {
        String unit = timeUnit.toString().toLowerCase();
        if (properties.containsKey("roll." + unit)) {
            rollStrategy = RollStrategy.valueOf(properties.getProperty("roll." + unit));
        }
        timeUnit = TimeUnit.values()[timeUnit.ordinal() + 1]; // check next time unit
    }
    return rollStrategy != null ? rollStrategy : RollStrategy.ERROR_STRATEGY;
}
