public Matrix inverse() throws MatrixException {
    if (!isSquare()) {
        throw new MatrixException("Matrix is not square, cannot compute inverse");
    }
    int n = getNumRows();
    Matrix identity = Matrix.identity(n);
    Matrix copy = copy();
    for (int i = 0; i < n; i++) {
        if (copy.get(i, i) == 0.0) {
            throw new MatrixException("Matrix is not invertible");
        }
        double divisor = copy.get(i, i);
        for (int j = 0; j < n; j++) {
            copy.set(i, j, copy.get(i, j) / divisor);
            identity.set(i, j, identity.get(i, j) / divisor);
        }
        for (int j = 0; j < n; j++) {
            if (i == j) {
                continue;
            }
            double factor = copy.get(j, i);
            for (int k = 0; k < n; k++) {
                copy.set(j, k, copy.get(j, k) - factor * copy.get(i, k));
                identity.set(j, k, identity.get(j, k) - factor * identity.get(i, k));
            }
        }
    }
    return identity;
}
