public static String methodSignature(Method overridenMethod) throws NotFoundException {
  Class<?>[] parameterClasses = overridenMethod.getParameterTypes();
  String[] parameterTypes = new String[parameterClasses.length];
  for (int i = 0; i < parameterClasses.length; i++) {
    parameterTypes[i] = parameterClasses[i].getName();
  }
  String[] exceptionTypes = new String[overridenMethod.getExceptionTypes().length];
  for (int i = 0; i < overridenMethod.getExceptionTypes().length; i++) {
    exceptionTypes[i] = overridenMethod.getExceptionTypes()[i].getName();
  }
  return overridenMethod.getModifiers() + " " + overridenMethod.getReturnType().getName() + " " + overridenMethod.getName() + "(" + String.join(", ", parameterTypes) + ")" + (exceptionTypes.length > 0 ? " throws " + String.join(", ", exceptionTypes) : "");
}
