private static boolean Verify(InputStream isSignature, InputStream isMessage, InputStream isPublicKey) throws LRException
    {

		PGPPublicKeyRingCollection pgpRings = null;

		try
		{
			 pgpRings = new PGPPublicKeyRingCollection(PGPUtil.getDecoderStream(isPublicKey));
		}
		catch (Exception e)
		{
			throw new LRException(LRException.INVALID_PUBLIC_KEY);
		}


		Security.addProvider(new BouncyCastleProvider());


		boolean verify = false;
		int ch;
		ByteArrayOutputStream bOut = new ByteArrayOutputStream();
		ArmoredInputStream aIn  = null;

		try
		{
			aIn = new ArmoredInputStream(isMessage);


			while ((ch = aIn.read()) >= 0 && aIn.isClearText())
			{
				bOut.write((byte)ch);
			}

			bOut.close();
		}
		catch (Exception e)
		{
			throw new LRException(LRException.MESSAGE_INVALID);
		}


		Object o = null;
		try
		{
			PGPObjectFactory pgpFact = new PGPObjectFactory(PGPUtil.getDecoderStream(isSignature));
			o = pgpFact.nextObject();
		}
		catch (Exception e)
		{
			throw new LRException(LRException.SIGNATURE_INVALID);
		}


		try
		{
			if (o instanceof PGPSignatureList)
			{
				PGPSignatureList list = (PGPSignatureList)o;
				if (list.size() > 0)
				{
					PGPSignature sig = list.get(0);

					PGPPublicKey publicKey = pgpRings.getPublicKey(sig.getKeyID());
					sig.init(new JcaPGPContentVerifierBuilderProvider().setProvider("BC"), publicKey);

					sig.update(bOut.toByteArray());
					verify = sig.verify();
				}
			}
		}
		catch (Exception e)
		{
			throw new LRException(LRException.SIGNATURE_NOT_FOUND);
		}

		return verify;
	},0

private void fsyncImpl(Result<Boolean> result, FsyncType fsyncType)
  {
    try {
      flushData();

      ArrayList<SegmentFsyncCallback> fsyncListeners
        = new ArrayList<>(_fsyncListeners);
      _fsyncListeners.clear();

      Result<Boolean> resultNext = result.then((v,r)->
        afterDataFsync(r, _position, fsyncType, fsyncListeners));

      if (_isDirty || ! fsyncType.isSchedule()) {
        _isDirty = false;

        try (OutStore sOut = _readWrite.openWrite(_segment.extent())) {
          if (fsyncType.isSchedule()) {
            sOut.fsyncSchedule(resultNext);
          }
          else {
            sOut.fsync(resultNext);
          }
        }
      }
      else {
        resultNext.ok(true);
      }
    } catch (Throwable e) {
      e.printStackTrace();
      result.fail(e);
    }
