public static Rectangle scaleRectangle(Rectangle rectToFitIn, Rectangle toScale) {
    double scaleWidth = rectToFitIn.getWidth() / toScale.getWidth();
    double scaleHeight = rectToFitIn.getHeight() / toScale.getHeight();
    double scale = Math.min(scaleWidth, scaleHeight);
    int width = (int) (toScale.getWidth() * scale);
    int height = (int) (toScale.getHeight() * scale);
    int x = (int) (rectToFitIn.getX() + (rectToFitIn.getWidth() - width) / 2);
    int y = (int) (rectToFitIn.getY() + (rectToFitIn.getHeight() - height) / 2);
    return new Rectangle(x, y, width, height);
}
