public void removeFromSession(RouteContext routeContext) {
    // get the current session
    HttpSession session = routeContext.getRequest().getSession(false);

    if (session != null) {
        // retrieve the flash instance from the session
        Flash flash = (Flash) session.getAttribute(Flash.class.getName());

        if (flash != null) {
            // remove the flash instance from the session
            session.removeAttribute(Flash.class.getName());
            // bind the flash instance to the route context
            routeContext.setFlash(flash);
        }
    }

    // create a new flash instance and set it to the route context
    Flash newFlash = new Flash();
    routeContext.setFlash(newFlash);
}
