public VM readExpectedVM(Model mo, Object o, String id) throws JSONConverterException {
    if (!(o instanceof Map)) {
        throw new JSONConverterException("Invalid input: expected a map");
    }

    Map<Object, Object> map = (Map<Object, Object>) o;
    Object vmId = map.get(id);
    if (vmId == null || !(vmId instanceof String)) {
        throw new JSONConverterException("Invalid input: missing or invalid VM identifier");
    }

    String vmName = (String) vmId;
    VM vm = mo.getVM(vmName);
    if (vm == null) {
        throw new JSONConverterException("Invalid input: VM not found in model");
    }

    return vm;
}
