public synchronized Object waitForValue(long timeout) throws InterruptedException {
    if (timeout == 0) {
        while (value == null) {
            wait();
        }
    } else {
        long endTime = System.currentTimeMillis() + timeout;
        long remainingTime = timeout;
        while ((value == null) && (remainingTime > 0)) {
            wait(remainingTime);
            remainingTime = endTime - System.currentTimeMillis();
        }
    }
    if (value == null) {
        throw new InterruptedException("Timeout expired");
    }
    Object currentValue = value;
    value = null;
    return currentValue;
}
