public List<String> getArgumentsList(String command, int n) {
    List<String> words = Arrays.asList(command.split(" "));
    if (words.size() <= n) {
        return Collections.emptyList();
    } else {
        List<String> arguments = words.subList(n, words.size());
        if (arguments.isEmpty() || arguments.get(arguments.size() - 1).isEmpty()) {
            arguments = arguments.subList(0, arguments.size() - 1);
        }
        return arguments;
    }
}
