public StringBuilder trimBuilder(StringBuilder builder) {
    int start = 0;
    int end = builder.length() - 1;
    while (start <= end && Character.isWhitespace(builder.charAt(start))) {
        start++;
    }
    while (end > start && Character.isWhitespace(builder.charAt(end))) {
        end--;
    }
    builder.setLength(end + 1);
    builder.delete(0, start);
    return builder;
}
