import java.nio.file.Paths;
import java.util.Optional;

public class BlackDuckSignatureScanner {

    private static final String SERVER_URL = "http://example.com/blackduckscannerserver";
    private static final String INSTALL_LOCATION = "/usr/local/blackduckscanner";

    public static Optional<String> downloadScanner() {
        try {
            URL url = new URL(SERVER_URL + "/blackducksignaturescanner.jar");
            URLConnection conn = url.openConnection();
            conn.connect();
            int contentLength = conn.getContentLength();
            Path installPath = Paths.get(INSTALL_LOCATION, "blackducksignaturescanner.jar");
            if (Files.exists(installPath) && Files.size(installPath) == contentLength) {
                return Optional.of(installPath.toString());
            }
            try (FileOutputStream fos = new FileOutputStream(installPath.toFile())) {
                Files.copy(conn.getInputStream(), fos);
            }
            return Optional.of(installPath.toString());
        } catch (Exception e) {
            System.err.println("Failed to download or install blackduckscanner: " + e.getMessage());
            return Optional.empty();
        }
    }
}
