public static String getPhantomJSLocation() {
    String systemProperty = System.getProperty("os.name").toLowerCase();
    if (systemProperty.contains("win")) {
        String[] paths = {"C:/phantomjs/phantomjs.exe", "C:/Program Files/phantomjs/phantomjs.exe", "C:/PhantomJS/phantomjs.exe"};
        return findPathInPaths(paths);
    } else if (systemProperty.contains("mac")) {
        String[] paths = {"/usr/local/bin/phantomjs", "/usr/bin/phantomjs", "/usr/bin/local/phantomjs"};
        return findPathInPaths(paths);
    } else if (systemProperty.contains("nix") || systemProperty.contains("nux") || systemProperty.contains("aix")) {
        String[] paths = {"/usr/local/bin/phantomjs", "/usr/bin/phantomjs", "/bin/phantomjs"};
        return findPathInPaths(paths);
    } else if (systemProperty.contains("sunos")) {
        String[] paths = {"/usr/local/bin/phantomjs", "/usr/bin/phantomjs", "/opt/csw/bin/phantomjs"};
        return findPathInPaths(paths);
    } else {
        return "";
    }
}

private static String findPathInPaths(String[] paths) {
    for (String path : paths) {
        File file = new File(path);
        if (file.exists()) {
            return path;
        }
    }
    return "";
}
