    // iterate over the stack trace of the thread
    for (StackTraceElement element : stackTrace) {
        // check if any element has a breakpoint at the same line
        if (element != null && element.getLineNumber() != -1 && 
            Debug.getBreakpoint(element.getLineNumber()) != null) {
            return true;
        }
    }

    return false;
}
