public class FunctionalInterfaceBuilder<T> {
    private Function<T, ?> implementation;
    private Consumer<Function<T, ?>> consumer;

    public FunctionalInterfaceBuilder<T> implementation(Function<T, ?> implementation) {
        this.implementation = implementation;
        return this;
    }

    public FunctionalInterfaceBuilder<T> consumer(Consumer<Function<T, ?>> consumer) {
        this.consumer = consumer;
        return this;
    }

    public Function<T, ?> build() {
