import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.ByteBuffer;
import java.io.IOException;

public class DatabaseValidator {
    private static final byte[] SQLITE_MAGIC_HEADER = {
        0x53, 0x51, 0x4c, 0x69, 0x74, 0x65, 0x20, 0x66,
        0x6f, 0x72, 0x6d, 0x61, 0x74, 0x20, 0x33, 0x00
    };

    public static boolean isSqliteDatabase(Path database) throws IOException {
        byte[] header = Files.readAllBytes(database);
        if (header.length < SQLITE_MAGIC_HEADER.length) {
            return false;
        }

        ByteBuffer dbBuffer = ByteBuffer.wrap(header, 0, SQLITE_MAGIC_HEADER.length);
        ByteBuffer magicBuffer = ByteBuffer.wrap(SQLITE_MAGIC_HEADER);
        return dbBuffer.compareTo(magicBuffer) == 0;
    }
}
