public List<Node> getLeavesInOrder(Node root) {
    List<Node> leaves = new ArrayList<>();
    if (root == null) {
        return leaves;
    }
    if (root.left == null && root.right == null) {
        leaves.add(root);
    }
    leaves.addAll(getLeavesInOrder(root.left));
    leaves.addAll(getLeavesInOrder(root.right));
    return leaves;
}
