class Main {
  public static Map<Integer, List<List<Integer>>> reconstructAndGroup(List<List<Integer>> relevant) {

    Map<Integer, List<List<Integer>>> cyclesByWeight = new HashMap<>();

    for(List<Integer> cycle: relevant){

        int weight = cycle.size();

        List<List<Integer>> cycles = cyclesByWeight.getOrDefault(weight, new ArrayList<>());

        cycles.add(cycle);

        cyclesByWeight.put(weight, cycles);
    }

    return cyclesByWeight;
  }

  public static void main(String[] args) {
    List<List<Integer>> relevant = new ArrayList<>();
    relevant.add(Arrays.asList(1,2,3));
    relevant.add(Arrays.asList(4,5,6,7));
    relevant.add(Arrays.asList(8,9));

    Map<Integer, List<List<Integer>>> result = reconstructAndGroup(relevant);

    System.out.println(result);
  }
}
