import java.beans.IntrospectionException;
import java.beans.Introspector;
import java.beans.PropertyDescriptor;

public StringBuilder printBean(StringBuilder sb, Object bean, int level) throws IntrospectionException {
    if (bean == null) {
        return sb;
    }

    PropertyDescriptor[] propertyDescriptors = Introspector.getBeanInfo(bean.getClass()).getPropertyDescriptors();

    for (PropertyDescriptor prop : propertyDescriptors) {
        String propName = prop.getName();
        if (propName.equals("class")) {
            continue;
        }

        sb.append("\n");
        for (int i = 0; i < level; i++) {
            sb.append(" ");
        }
        sb.append(propName).append(": ");

        try {
            Object value = prop.getReadMethod().invoke(bean);

            if (value != null) {
                Class<?> valueType = value.getClass();
                if (valueType.isPrimitive() || valueType == String.class) {
                    sb.append(value);
                } else {
                    printBean(sb, value, level + 1);
                }
            }
        } catch (Exception e) {
            throw new IntrospectionException(prop.getName());
        }
    }

    return sb;
}
