public static <T> T executeInTransaction(Callable<T> statements) throws Exception {
    Connection connection = null;
    T result = null;
    try {
        connection = getConnection();
        connection.setAutoCommit(false);
        result = statements.call();
        connection.commit();
    } catch (Exception e) {
        if (connection != null) {
            connection.rollback();
        }
        throw e;
    } finally {
        if (connection != null) {
            connection.close();
        }
    }
    return result;
}

