public List<Atom> selectIons(ChargedFragment frag, int sign) {
    List<Atom> selectedAtoms = new ArrayList<>();
    for (Bond bond : frag.getChargeSeparatedBonds()) {
        Atom atom1 = bond.getAtom1();
        Atom atom2 = bond.getAtom2();
        if (atom1.getCharge() == sign && !selectedAtoms.contains(atom1)) {
            selectedAtoms.add(atom1);
        }
        if (atom2.getCharge() == sign && !selectedAtoms.contains(atom2)) {
            selectedAtoms.add(atom2);
        }
    }
    for (Atom atom : frag.getAtoms()) {
        int atomCharge = atom.getCharge();
        if (atomCharge == sign || atomCharge == sign * 2 || atomCharge == sign * -2) {
            if (!selectedAtoms.contains(atom)) {
                if (atomCharge == sign * 2 || atomCharge == sign * -2) {
                    selectedAtoms.add(atom);
                } else {
                    List<Bond> bonds = frag.getBonds(atom);
                    boolean chargeSeparated = false;
                    for (Bond bond : bonds) {
                        if (frag.getChargeSeparatedBonds().contains(bond)) {
                            chargeSeparated = true;
                            break;
                        }
                    }
                    if (!chargeSeparated) {
                        selectedAtoms.add(atom);
                    }
                }
            } else if (atomCharge == sign * 2 || atomCharge == sign * -2) {
                selectedAtoms.add(atom);
            }
        }
    }
    return selectedAtoms;
}
