public int compareTo(FDBigInt other) {
    int len1 = this.nWords;
    int len2 = other.nWords;

    if (len1 != len2) {
        return len1 - len2;
    }

    // Compare the words in the reverse order
    for (int i = len1 - 1; i >= 0; i--) {
        long d1 = this.data[i] & UNSIGNED_MASK;
        long d2 = other.data[i] & UNSIGNED_MASK;

        if (d1 != d2) {
            return (d1 < d2 ? -1 : 1);
        }
    }

    return 0; // equal
}
