import java.util.LinkedList;

public class DiffAlgorithm {
    public LinkedList<DiffBase> diffMain(String text1, String text2) {
        // Implementation of the 'middle snake' algorithm according to Myers 1986 paper
        // Split the problem in two and return recursively constructed diff

        // Initialize empty linked list to be returned
        LinkedList<DiffBase> diffs = new LinkedList<>();

        // Base case of recursion
        if (text1.equals(text2)) {
            if (text1.length() != 0) {
                diffs.add(new DiffEqual(text1));
            }
            return diffs;
        }

        // Trim off common suffix and prefix
        int commonLength = getCommonPrefixLength(text1, text2);
        String commonPrefix = text1.substring(0, commonLength);
        text1 = text1.substring(commonLength);
        text2 = text2.substring(commonLength);

        commonLength = getCommonSuffixLength(text1, text2);
        String commonSuffix = text1.substring(text1.length() - commonLength);
        text1 = text1.substring(0, text1.length() - commonLength);
        text2 = text2.substring(0, text2.length() - commonLength);

        // Check for empty string cases
        if (text1.length() == 0) {
            diffs.add(new DiffInsert(commonPrefix + text2 + commonSuffix));
            return diffs;
        }

        if (text2.length() == 0) {
            diffs.add(new DiffDelete(commonPrefix + text1 + commonSuffix));
            return diffs;
        }

        // Find the middle snake and recursively call diff on each side
        SnakeInfo snake = getMiddleSnake(text1, text2);
        LinkedList<DiffBase> diffs1 = diffMain(text1.substring(0, snake.x), text2.substring(0, snake.y));
        LinkedList<DiffBase> diffs2 = diffMain(text1.substring(snake.x, text1.length()), text2.substring(snake.y, text2.length()));

        // Merge the two linked lists of diffs
        diffs.addAll(diffs1);
        diffs.add(new DiffEqual(snake.text));
        diffs.addAll(diffs2);

        return diffs;
    }

    private int getCommonPrefixLength(String text1, String text2) {
        int n = Math.min(text1.length(), text2.length());
        for (int i = 0; i < n; i++) {
            if (text1.charAt(i) != text2.charAt(i)) {
                return i;
            }
        }
        return n;
    }

    private int getCommonSuffixLength(String text1, String text2) {
        int n = Math.min(text1.length(), text2.length());
        for (int i = 1; i <= n; i++) {
            if (text1.charAt(text1.length() - i) != text2.charAt(text2.length() - i)) {
                return i - 1;
            }
        }
        return n;
    }

    private SnakeInfo getMiddleSnake(String text1, String text2) {
        int m = text1.length();
        int n = text2.length();
        int maxD = (m + n + 1) / 2;
        int[] v1 = new int[2 * maxD];
        int[] v2 = new int[2 * maxD];
        for (int i = 0; i < v1.length; i++) {
            v1[i] = -1;
            v2[i] = -1;
        }
        v1[maxD + 1] = 0;
        v2[maxD + 1] = 0;
        int delta = m - n;
        boolean odd = (delta & 1) != 0;
        for (int d = 0; d < maxD; d++) {
            for (int k = -d; k <= d; k += 2) {
                int x, y;
                // find the end point of furthest snake with diagonal k+1 from snake d-1 on the left
                if (k == -d || k != d && v1[maxD + k - 1] < v1[maxD + k + 1]) {
                    x = v1[maxD + k + 1];
                } else {
                    x = v1[maxD + k - 1] + 1;
                }
                // y coordinate is derived from x
                y = x - k;
                // find the end point of furthest snake with diagonal k+1 from snake d-1 on the right
                while (x < m && y < n && text1.charAt(x) == text2.charAt(y)) {
                    x++;
                    y++;
                }
                v1[maxD + k] = x;
                // check for overlap
                if (odd && k >= delta - (d - 1) && k <= delta + (d - 1)) {
                    if (v1[maxD + k] >= v2[maxD + k]) {
                        SnakeInfo result = new SnakeInfo();
                        result.text = text1.substring((v2[maxD + k] + 1) - delta, v1[maxD + k] + 1);
                        result.x = v1[maxD + k];
                        result.y = v2[maxD + k];
                        return result;
                    }
                }
            }
            for (int k = -d; k <= d; k += 2) {
                int x, y;
                // find the end point of furthest snake with diagonal k from snake d-1 on the left
                if (k == -d || k != d && v2[maxD + k - 1] < v2[maxD + k + 1]) {
                    x = v2[maxD + k + 1];
                } else {
                    x = v2[maxD + k - 1] + 1;
                }
                // y coordinate is derived from x
                y = x - k;
                // find the end point of furthest snake with diagonal k from snake d-1 on the right
                while (x < m && y < n && text1.charAt(m - x - 1) == text2.charAt(n - y - 1)) {
                    x++;
                    y++;
                }
                v2[maxD + k] = x;
                // check for overlap
                if (!odd && k >= delta - d && k <= delta + d) {
                    if (v1[maxD + k] >= v2[maxD + k]) {
                        SnakeInfo result = new SnakeInfo();
                        result.text = text1.substring((m - v1[maxD + k]) - delta, m - v2[maxD + k]);
                        result.x = m - v1[maxD + k] - 1;
                        result.y = n - v2[maxD + k] - 1;
                        return result;
                    }
                }
            }
        }
        // Should never get here
        System.err.println("Could not find a middle snake!");
        return null;
    }

    private static class SnakeInfo {
        String text;
        int x, y;
    }
}
