public static BufferedImage createQRCode(int[] numbers) throws WriterException, IOException {
    String content = "";
    for(int i=0;i<numbers.length;i++){
        content += String.valueOf(numbers[i]);
    }

    // Create the QR code
    Map<EncodeHintType, Object> hintMap = new HashMap<EncodeHintType, Object>();
    hintMap.put(EncodeHintType.CHARACTER_SET, "UTF-8");

    QRCodeWriter qrCodeWriter = new QRCodeWriter();
    BitMatrix bitMatrix = qrCodeWriter.encode(content, BarcodeFormat.QR_CODE, 200, 200, hintMap);

    // Convert the bit matrix to buffered image
    BufferedImage bufferedImage = MatrixToImageWriter.toBufferedImage(bitMatrix);

    return bufferedImage;
}
