public List<Object> loadAllServicesAndEntities(List<String> moduleNames) throws ClassNotFoundException, IOException {
    List<Object> servicesAndEntities = new ArrayList<>();
    for (String moduleName : moduleNames) {
        ClassPath classpath = ClassPath.from(getClass().getClassLoader());
        ImmutableSet<ClassInfo> classes = classpath.getTopLevelClassesRecursive(moduleName);
        for (ClassInfo classInfo : classes) {
            Class<?> clazz = classInfo.load();
            if (clazz.isAnnotationPresent(Service.class) || clazz.isAnnotationPresent(Entity.class)) {
                Object instance = clazz.newInstance();
                servicesAndEntities.add(instance);
            }
        }
    }
    return servicesAndEntities;
}
