public static double[] softmax(double[] inputs) {
    double[] outputs = new double[inputs.length];
    double maxInput = Arrays.stream(inputs).max().getAsDouble();
    double denominator = 0.0;
    for (int i = 0; i < inputs.length; i++) {
        double output = Math.exp(inputs[i] - maxInput);
        outputs[i] = output;
        denominator += output;
    }
    for (int i = 0; i < inputs.length; i++) {
        outputs[i] /= denominator;
    }
    return outputs;
}
