public boolean parseCommandLineArguments(PrintStream messageStream, String[] args, CallerArguments callerArguments) throws CommandLineException {
    boolean shouldRun = true;
    for (int i = 0; i < args.length; i++) {
        switch (args[i]) {
            case "--help":
                messageStream.println("Help message here.");
                shouldRun = false;
                break;
            case "--version":
                messageStream.println("Version message here.");
                shouldRun = false;
                break;
            case "--input":
                if (i + 1 < args.length) {
                    callerArguments.setInput(args[i + 1]);
                    i++;
                } else {
                    throw new CommandLineException("Missing input value.");
                }
                break;
            case "--output":
                if (i + 1 < args.length) {
                    callerArguments.setOutput(args[i + 1]);
                    i++;
                } else {
                    throw new CommandLineException("Missing output value.");
                }
                break;
            default:
                throw new CommandLineException("Invalid option: " + args[i]);
        }
    }
    return shouldRun;
}
