public Set<String> findComponentAndFacetNames(Object instance) {
    Set<String> result = new HashSet<>();

    if (instance != null) {
        Class<?> cls = instance.getClass();
        BeanInfo info;
        try {
            info = Introspector.getBeanInfo(cls);
        } catch (IntrospectionException e) {
            throw new RuntimeException("Could not get bean info for class " + cls.getName(), e);
        }

        for (PropertyDescriptor pd : info.getPropertyDescriptors()) {
            Method getter = pd.getReadMethod();
            if (getter != null) {
                String name = pd.getName();
                if (!"class".equals(name)) { // exclude the "class" property
                    String componentName = null;
                    String facetName = null;
                    Annotation[] annotations = getter.getAnnotations();
                    for (Annotation annotation : annotations) {
                        if (annotation instanceof Component) {
                            componentName = ((Component) annotation).value();
                        } else if (annotation instanceof Facet) {
                            facetName = ((Facet) annotation).value();
                        }
                    }
                    if (componentName == null) {
                        componentName = name;
                    }
                    if (facetName == null) {
                        result.add(componentName);
                    } else {
                        result.add(componentName + "." + facetName);
                    }
                }
            }
        }
    }

    return result;
}
