public double getDoubleValue(int recnum, Member m) throws ForbiddenConversionException {
    DataType dataType = m.getDataType();
    if (!dataType.isNumeric()) {
        throw new ForbiddenConversionException("Data type is not numeric");
    }

    ArrayStructure arrayStructure = getArrayStructure();
    StructureData structureData = arrayStructure.getStructureData(recnum);
    Number number = structureData.getScalarNumber(m);
    if (number == null) {
        throw new ForbiddenConversionException("Value is null");
    }

    if (dataType == DataType.DOUBLE) {
        return number.doubleValue();
    } else if (dataType == DataType.FLOAT) {
        return number.floatValue();
    } else if (dataType == DataType.LONG) {
        return (double) number.longValue();
    } else if (dataType == DataType.INT) {
        return (double) number.intValue();
    } else if (dataType == DataType.SHORT) {
        return (double) number.shortValue();
    } else if (dataType == DataType.BYTE) {
        return (double) number.byteValue();
    }

    throw new ForbiddenConversionException("Data type is not convertible to double");
}
