public static double toNumber(String s) {
        final int len = s.length();

        int start = 0;
        char startChar;
        for (;;) {
            if (start == len) {

                return +0.0;
            }
            startChar = s.charAt(start);
            if (!ScriptRuntime.isStrWhiteSpaceChar(startChar)) {

                break;
            }
            start++;
        }

        int end = len - 1;
        char endChar;
        while (ScriptRuntime.isStrWhiteSpaceChar(endChar = s.charAt(end))) {
            end--;
        }









        final Context cx = Context.getCurrentContext();
        final boolean oldParsingMode =
                cx == null || cx.getLanguageVersion() < Context.VERSION_ES6;

        if (startChar == '0') {
            if (start + 2 <= end) {
                final char radixC = s.charAt(start + 1);
                int radix = -1;
                if (radixC == 'x' || radixC == 'X') {
                    radix = 16;
                } else if (!oldParsingMode && (radixC == 'o' || radixC == 'O')) {
                    radix = 8;
                } else if (!oldParsingMode && (radixC == 'b' || radixC == 'B')) {
                    radix = 2;
                }
                if (radix != -1) {
                    if (oldParsingMode) {
                        return stringPrefixToNumber(s, start + 2, radix);
                    }
                    return stringToNumber(s, start + 2, end, radix);
                }
            }
        } else if (oldParsingMode && (startChar == '+' || startChar == '-')) {

            if (start + 3 <= end && s.charAt(start + 1) == '0') {
                final char radixC = s.charAt(start + 2);
                if (radixC == 'x' || radixC == 'X') {
                    double val = stringPrefixToNumber(s, start + 3, 16);
                    return startChar == '-' ? -val : val;
                }
            }
        }
        if (endChar == 'y') {

            if (startChar == '+' || startChar == '-') {
                start++;
            }
            if (start + 7 == end && s.regionMatches(start, "Infinity", 0, 8)) {
                return startChar == '-'
                        ? Double.NEGATIVE_INFINITY
                        : Double.POSITIVE_INFINITY;
            }
            return NaN;
        }


        String sub = s.substring(start, end+1);


        for (int i = sub.length() - 1; i >= 0; i--) {
            char c = sub.charAt(i);
            if (('0' <= c && c <= '9') || c == '.' ||
                    c == 'e' || c == 'E'  ||
                    c == '+' || c == '-')
                continue;
            return NaN;
        }
        try {
            return Double.parseDouble(sub);
        } catch (NumberFormatException ex) {
            return NaN;
        }
    },0

import java.io.IOException;
import java.util.Properties;
import org.apache.hadoop.conf.Configuration;

public Properties parseCommandLineArgs(Class<?> caller, String[] args, Configuration conf) throws IOException {
    Properties properties = new Properties();
    try {
        CommandLineParser parser = new BasicParser();
        CommandLine commandLine = parser.parse(new Options(), args);
        if (commandLine.hasOption("jobconfig")) {
            properties = new Properties();
            File jobConfigFile = new File(commandLine.getOptionValue("jobconfig"));
            if (jobConfigFile.exists() && jobConfigFile.isFile()) {
                properties.load(new FileInputStream(jobConfigFile));
            } else {
                throw new IOException(
                        "Job configuration file not provided in command line or does not exist!");
            }
        } else {
            throw new IOException("Job configuration file not provided in command line!");
        }
    } catch (ParseException pe) {
        throw new IOException(pe);
    }
    return properties;
}
