import java.time.MonthDay;
import java.util.Random;

public class MonthDayUtils {
    public static MonthDay getRandomMonthDayAfter(MonthDay after, boolean includeLeapDay) {
        if (after == null || after.equals(MonthDay.of(12, 31))) {
            throw new IllegalArgumentException("Invalid argument: after must not be null and must not be December 31st.");
        }
        Random random = new Random();
        int currentYear = java.time.LocalDate.now().getYear();
        int maxDay = includeLeapDay && after.getMonthValue() == 2 ? after.getMonth().length(java.time.Year.of(currentYear).isLeap()) : after.getMonth().length(false);
        int randomDay = random.nextInt(maxDay - after.getDayOfMonth()) + after.getDayOfMonth() + 1;
        if (randomDay > maxDay) {
            return MonthDay.of(after.getMonth().plus(1), 1);
        }
        return MonthDay.of(after.getMonth(), randomDay);
    }
}
