public void parseRule(String rule, String defaultConsequence, Map<String, String> namedConsequences) {
    String[] tokens = rule.split(" ");

    String rhs = defaultConsequence;

    int i = 0;
    while (i < tokens.length) {
        if (tokens[i].startsWith("~END")) {
            break;
        } else if (tokens[i].equals(defaultConsequence)) {
            i++;
        } else {
            namedConsequences.put(tokens[i], tokens[i + 1]);
            i += 2;
        }
    }
}
