public static <C> PortableClassAccess<C> getClassAccess(final Class<C> clazz) {
    PortableClassAccess<C> access = new PortableClassAccess<>(clazz);
    try {
        access.checkAccess();
    } catch (final SecurityException e) {
        // no access then create a specialized subclass
        access = AccessController.doPrivileged(new PrivilegedAction<PortableClassAccess<C>>() {
            @Override
            public PortableClassAccess<C> run() {
                return new PortableClassAccess<>(clazz);
            }
        });
        access.checkAccess();
    }
    return access;
}
