public void readFully(InputStream inputStream, byte[] buffer, int offset, int length) throws IOException {
    int bytesRead = 0;
    while (bytesRead < length) {
        int count = inputStream.read(buffer, offset + bytesRead, length - bytesRead);
        if (count == -1) {
            throw new EOFException("End of stream reached before reading fully.");
        }
        bytesRead += count;
    }
}
