public List<NsConfResource> fetchFilteredNsConf(String filterString) {
    List<NsConfResource> results = new ArrayList<>();

    // parse filter string as JSON
    JsonObject filterJson = Json.parse(filterString).asObject();

    // build query from filter JSON
    QueryBuilder queryBuilder = new QueryBuilder();
    for (String key : filterJson.names()) {
        JsonValue value = filterJson.get(key);

        if (value.isString()) {
            // treat as exact match
            queryBuilder.and(key).is(value.asString());
        } else if (value.isArray()) {
            // treat as list of exact matches
            JsonArray array = value.asArray();
            for (JsonValue elem : array) {
                queryBuilder.and(key).is(elem.asString());
            }
        } else {
            throw new IllegalArgumentException("Invalid filter value type");
        }
    }

    // run query
    List<NsConfResource> allResources = NsConfResource.getAll();
    for (NsConfResource resource : allResources) {
        if (queryBuilder.test(resource)) {
            results.add(resource);
        }
    }

    return results;
}
