public static int encodeVByte(long x, OutputStream os) throws IOException {
    int count = 0;
    while (true) {
        ++count;
        if ((x & ~0x7F) == 0) {
            os.write((byte) x);
            return count;
        } else {
            os.write((byte) ((x & 0x7F) | 0x80));
            x >>>= 7;
        }
    }
}
