        this.privateKey = privateKey;
    }

    String getCertificate() {
        return certificate;
    }

    String getPrivateKey() {
        return privateKey;
    }
}

public static TLSCertificateKeyPair createTLSServerCertificateKeyPair(String subjectAlternativeName) 
            throws NoSuchAlgorithmException, NoSuchProviderException, IOException, CertificateEncodingException, OperatorCreationException,
            InvalidAlgorithmParameterException, CertificateException {

        KeyPair keyPair = generateKeyPair();
        PKCS10CertificationRequest csr = generateCSR(keyPair, subjectAlternativeName);

        X509Certificate serverCert = generateCertificate(csr, keyPair.getPrivate(), getValidity());
        String certStr = pemEncode(serverCert);
        String privateKeyStr = pemEncode(keyPair.getPrivate());

        return new TLSCertificateKeyPair(certStr, privateKeyStr);
    }

    private static KeyPair generateKeyPair() throws NoSuchAlgorithmException, InvalidAlgorithmParameterException, NoSuchProviderException {
        // Generate an EC key pair using the secp256r1 curve
        ECGenParameterSpec ecSpec = new ECGenParameterSpec("secp256r1");
        KeyPairGenerator keyPairGenerator = KeyPairGenerator.getInstance("EC");
        keyPairGenerator.initialize(ecSpec);
        return keyPairGenerator.generateKeyPair();
    }

    private static PKCS10CertificationRequest generateCSR(KeyPair keyPair, String subjectAlternativeName) 
            throws IOException, OperatorCreationException {
        JcaPKCS10CertificationRequestBuilder csrBuilder = new JcaPKCS10CertificationRequestBuilder(
                new X500Name("CN=example.com"), keyPair.getPublic());

        GeneralName sanName = new GeneralName(GeneralName.dNSName, subjectAlternativeName);
        GeneralNames subjectAltName = new GeneralNames(sanName);
        Extension extension = new Extension(Extension.subjectAlternativeName, false, subjectAltName);
        csrBuilder.addAttribute(PKCSObjectIdentifiers.pkcs_9_at_extensionRequest, new Extensions(extension));

        ContentSigner signer = new JcaContentSignerBuilder("SHA256withECDSA").build(keyPair.getPrivate());
        return csrBuilder.build(signer);
    }

    private static X509Certificate generateCertificate(PKCS10CertificationRequest csr, PrivateKey signingKey, Duration validity) 
            throws IOException, OperatorCreationException, CertificateException {
        Instant now = Instant.now();
        X509v3CertificateBuilder certBuilder = new X509v3CertificateBuilder(
                new X500Name("CN=example.com"), 
                BigInteger.valueOf(now.toEpochMilli()), 
                Date.from(now), 
                Date.from(now.plus(validity)), 
                csr.getSubject(), 
                csr.getSubjectPublicKeyInfo()
        );

        // Add the basic constraints extension
        certBuilder.addExtension(Extension.basicConstraints, true, new BasicConstraints(false));

        // Sign the certificate
        ContentSigner signer = new BcRSAContentSignerBuilder(
                new AlgorithmIdentifier(AlgorithmId.RSAEncryption_oid), 
                new AlgorithmIdentifier(AlgorithmId.SHA256_oid),
                new JcaContentSignerExtensionBuilder()
                        .setProvider(BouncyCastleProvider.PROVIDER_NAME)
                        .build(signingKey)
        ).build(signingKey);

        X509CertificateHolder holder = certBuilder.build(signer);
        return new JcaX509CertificateConverter().getCertificate(holder);
    }

    private static String pemEncode(Object obj) throws IOException {
        PemObject pemObject = new PemObject("CERTIFICATE", obj.getEncoded());
        StringWriter sw = new StringWriter();
        try (PemWriter pw = new PemWriter(sw)) {
            pw.writeObject(pemObject);
        }
        return sw.toString();
    }

    private static Duration getValidity() {
        return Duration.ofDays(365);
    }
