import java.util.Iterator;

public class ArrayIteratorWrapper {

    public static <T> Iterator<T> getIteratorWrapper(T[] array, Class<T> declaredType, Class<T> valueType) {
        if (array == null || declaredType == null || valueType == null) throw new NullPointerException();
        if (!declaredType.isArray() || !declaredType.getComponentType().isAssignableFrom(valueType)) {
            throw new IllegalArgumentException();
        }
        return new Iterator<T>() {
            int index = 0;
            @Override
            public boolean hasNext() {
                return index < array.length;
            }

            @Override
            public T next() {
                if (!hasNext()) throw new IndexOutOfBoundsException();
                return valueType.cast(array[index++]);
            }
        };
    }
}
