public int getFileFormatVersion(String filename) {
    int version = 0;
    try {
        FileInputStream fis = new FileInputStream(filename);
        byte[] buffer = new byte[4];
        fis.read(buffer);
        version = (buffer[0] << 24) + (buffer[1] << 16) + (buffer[2] << 8) + buffer[3];
        fis.close();
    } catch (IOException ex) {
        ex.printStackTrace();
    }
    return version;
}
