private Interval getNextBestIntervalAtMaxLevel(MaxHeap heap) {
    if (heap.isEmpty()) {
        return null;
    }
    Interval interval = heap.poll();
    if (interval.getMaxLevel() == 0) {
        return interval;
    }
    List<Interval> subIntervals = interval.split();
    heap.addAll(subIntervals);
    return getNextBestIntervalAtMaxLevel(heap);
}
