public static Map<String, List<String>> extractHeaderAndValues(Map<String, String> headersMap, String rowDelimiter, String columnDelimiter) throws Exception {
    List<String> headerNames = new ArrayList<>();
    List<String> headerValues = new ArrayList<>();
    for (Map.Entry<String, String> entry : headersMap.entrySet()) {
        String headerName = entry.getKey();
        String headerValue = entry.getValue();
        if (headerName.contains(columnDelimiter) || headerName.contains(rowDelimiter)
                || headerValue.contains(columnDelimiter) || headerValue.contains(rowDelimiter)) {
            throw new Exception("Invalid header or value containing forbidden delimiter");
        }
        headerNames.add(headerName);
        headerValues.add(headerValue);
    }
    Map<String, List<String>> headerAndValues = new HashMap<>();
    headerAndValues.put("headerNames", headerNames);
    headerAndValues.put("headerValues", headerValues);
    return headerAndValues;
}
