public static void printMatrix(PrintStream out, double[][] mat, String format) {
    if (format.equals("matlab")) {
        out.print("[");
        for (double[] row : mat) {
            out.print(Arrays.toString(row)
                    .replace("[", "")
                    .replace("]", ""));
            out.print(";");
        }
        out.print("]");
    } else if (format.equals("java")) {
        out.print("{");
        for (double[] row : mat) {
            out.print(Arrays.toString(row) + ",");
        }
        out.print("}");
    } else {
        for (double[] row : mat) {
            out.print(String.format(format, row));
            out.print("\n");
        }
    }
}
