public static <T extends Number> T coerceNumber(Object value, Class<T> type) {
    if (value == null) {
        return null;
    }

    if (type.isInstance(value)) {
        return type.cast(value);
    }

    if (value instanceof Number) {
        Number number = (Number) value;
        if (type == Byte.class) {
            return type.cast(number.byteValue());
        } else if (type == Short.class) {
            return type.cast(number.shortValue());
        } else if (type == Integer.class) {
            return type.cast(number.intValue());
        } else if (type == Long.class) {
            return type.cast(number.longValue());
        } else if (type == Float.class) {
            return type.cast(number.floatValue());
        } else if (type == Double.class) {
            return type.cast(number.doubleValue());
        }
    }

    throw new IllegalArgumentException("Cannot coerce " + value + " to " + type.getSimpleName());
}
