public static boolean registerWithEpmd(String node) throws IOException {
    String command = "register " + node + " " + "0 " + "0";
    try (Socket socket = new Socket("localhost", 4369);
         BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
         BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()))) {

        writer.write(command + "\n");
        writer.flush();

        String response = reader.readLine();

        if(response.equals("ok")) {
            return true;
        }
        else if (response.equals("already_registered")) {
            return false;
        }
    }
    throw new IOException("No response from name server");
}
