import java.io.*;

enum FileFormat {
    UNKNOWN,
    ACSM,
    ENDNOTE,
    BIBTEX,
    RIS
}

public static FileFormat determineFileFormat(File bibfile) throws FileNotFoundException, IOException {
    FileFormat format = FileFormat.UNKNOWN;
    try (BufferedReader reader = new BufferedReader(new FileReader(bibfile))) {
        char[] first100KB = new char[100_000];
        int charsRead = reader.read(first100KB);

        if (charsRead != -1) {
            String data = new String(first100KB, 0, charsRead);
            if (data.contains("<DOCTYPE xml>")) {
                format = FileFormat.ACSM;
            } else if (data.contains("%0 Journal Article")) {
                format = FileFormat.ENDNOTE;
            } else if (data.contains("@ARTICLE{") || data.contains("@Article{")) {
                format = FileFormat.BIBTEX;
            } else if (data.contains("TY  - JOUR")) {
                format = FileFormat.RIS;
            }
        }
    }
    return format;
}
