public Properties loadConfig(String configFile, boolean useSystemEnvironment) throws IOException {
    Properties props = new Properties();
    try (InputStream inputStream = new FileInputStream(configFile)) {
        props.load(inputStream);
    }
    if (useSystemEnvironment) {
        for (String key : props.stringPropertyNames()) {
            String value = props.getProperty(key);
            String resolvedValue = resolveVariable(value);
            props.setProperty(key, resolvedValue);
        }
    }
    return props;
}

private String resolveVariable(String value) {
    Pattern pattern = Pattern.compile("\\$\\{(.+?)}");
    Matcher matcher = pattern.matcher(value);
    StringBuffer buffer = new StringBuffer();
    while (matcher.find()) {
        String envKey = matcher.group(1);
        String envValue = System.getenv(envKey);
        if (envValue == null) {
            envValue = "";
        }
        matcher.appendReplacement(buffer, envValue);
    }
    matcher.appendTail(buffer);
    return buffer.toString();
}
