public void averageModels(DeepWaterTask other) {
   if (this.getGeo() != other.getGeo()) {
      throw new IllegalArgumentException("Cannot average models with different geometries");
   }

   double[][] thisModels = this.getModels();
   double[][] otherModels = other.getModels();

   for (int i = 0; i < thisModels.length; i++) {
      for(int j = 0; j < thisModels[i].length; j++) {
         thisModels[i][j] = (thisModels[i][j] + otherModels[i][j]) / 2.0;
      }
   }

   this.setModels(thisModels);
   other.setModels(thisModels);
}
