public void insertChildNode(Node node, int index) {
    if (index < 0 || index > getChildCount()) {
        throw new IndexOutOfBoundsException("Invalid index for inserting child node.");
    }
    if (node == null) {
        throw new NullPointerException("Node cannot be null.");
    }
    // If index is -1, append node at the end
    if (index == -1) {
        addChildNode(node);
    } else {
        getChildNodes().add(index, node);
    }
}
