public static double convertS390toIEEE(double s390Value) {
    // Extract the sign, exponent, and mantissa from the S390 value
    int sign = (int) (s390Value >>> 63) & 1;
    int exponent = (int) ((s390Value >>> 52) & 0x7FF) - 64;
    long mantissa = s390Value & 0xFFFFFFFFFFFFFL;

    // Convert the mantissa to an unsigned long and multiply by 16^exponent
    double ieeeMantissa = mantissa / Math.pow(2, 52);
    ieeeMantissa *= Math.pow(16, exponent);

    // Shift the mantissa up to three places left to normalize it
    while (ieeeMantissa < Math.pow(2, 52)) {
        ieeeMantissa *= 2;
    }

    // Combine the sign, exponent, and mantissa into the IEEE 754 representation
    long ieeeSign = (long) sign << 63;
    long ieeeExponent = (long) ((exponent + 1023) & 0x7FF) << 52;
    long ieeeMantissaBits = (long) ieeeMantissa;
    long ieeeMantissaMask = 0xFFFFFFFFFFFFFL >> 12;
    long ieeeMantissa = ieeeMantissaBits & ieeeMantissaMask;

    return Double.longBitsToDouble(ieeeSign | ieeeExponent | ieeeMantissa);
}
