public double[][] randomNormal(int rows, int columns, long seed) {
    double[][] result = new double[rows][columns];
    Random rand = new Random(seed);

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < columns; j++) {
            result[i][j] = rand.nextGaussian();
        }
    }

    return result;
}
