public int countGroups(Object structure) {
    int groupCount = 0;
    if (structure instanceof List<?>) {
        List<?> list = (List<?>) structure;
        for (Object o : list) {
            groupCount += countGroups(o);
        }
    } else if (structure instanceof Map<?, ?>) {
        Map<?, ?> map = (Map<?, ?>) structure;
        for (Object o : map.values()) {
            groupCount += countGroups(o);
        }
    } else {
        groupCount += 1;
    }
    return groupCount;
}
