import de.learnlib.datastructure.impl.BasicAlphabet;
import de.learnlib.datastructure.impl.BasicAutomata;
import de.learnlib.datastructure.impl.DefaultQuery;
import de.learnlib.oracle.equivalence.AbstractTestQuery;
import de.learnlib.oracle.equivalence.RandomWordsEQOracle;
import de.learnlib.oracle.membership.SimulatorOracle.DFASimulatorOracle;
import de.learnlib.util.Experiment.MealyExperiment;

import java.util.Random;

public class ICGenerator {

    public static ICAutomatonGenerator<String, Boolean> createRandomICGenerator() {
        Random random = new Random();

        BasicAlphabet<String> alphabet = new BasicAlphabet<>();
        for (int i = 0; i < 10; i++) {
            alphabet.addSymbol("symbol" + i);
        }

        int numStates = random.nextInt(10) + 1;

        BasicAutomata.DFA<String> dfa = BasicAutomata.randomDFA(alphabet, numStates);

        DFASimulatorOracle<String> oracle = new DFASimulatorOracle<>(dfa);
        AbstractTestQuery<String, Boolean> ce = RandomWordsEQOracle.computeCE(oracle, alphabet, 10);

        MealyExperiment<String, Boolean> experiment = new MealyExperiment<>(new ICADFAGenerator<>(alphabet), oracle, ce);

        return new ICGenerativeSUL<>(experiment);
    }

}
