public static long floorMod(long x, long y) {
    if (y == 0) {
        throw new ArithmeticException("/ by zero");
    }
    long mod = x % y;
    if ((mod ^ y) < 0 && mod != 0) {
        mod += y;
    }
    return mod;
}
