public static INDArray convertFieldVectorToColumnVector(INDArray fieldVector, DataType type) {
    if(fieldVector.rank() != 1){
        throw new IllegalArgumentException("Input array must be a vector");
    }
    // Create a column vector with the specified data type
    INDArray columnVector = Nd4j.create(fieldVector.length(), 1, type);

    // Copy the elements from the field vector into the column vector
    for (int i = 0; i < fieldVector.length(); i++) {
        columnVector.put(i, 0, fieldVector.getDouble(i));
    }

    return columnVector;
}
