public Identity createExtendedIdentity(String extendedIdentifier, Charset c) throws IfmapException {
    try {
        byte[] bytes = extendedIdentifier.getBytes(c);
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        ByteArrayInputStream input = new ByteArrayInputStream(bytes);
        Document doc = builder.parse(input);
        return new ExtendedIdentityImpl(doc.getDocumentElement());
    } catch (Exception e) {
        throw new IfmapException("Failed to create extended identity: " + e.getMessage());
    }
}
