public List<Atom> findTerminalAtoms(Container container) {
    List<Atom> peripheralAtoms = container.getPeripheralAtoms();
    List<Atom> terminalAtoms = new ArrayList<>();

    for (Atom atom : peripheralAtoms) {
        List<Bond> bonds = atom.getBonds();
        if (bonds.size() == 1) {
            terminalAtoms.add(atom);
            if (terminalAtoms.size() == 2) {
                break;
            }
        }
    }

    return terminalAtoms;
}
