public Double getResidual(List<Double> newMessage, List<Double> oldMessage) {
    Double residual = 0.0;
    for (int i = 0; i < newMessage.size(); i++) {
        Double diff = Math.abs(Math.log(newMessage.get(i)) - Math.log(oldMessage.get(i)));
        if (diff > residual) {
            residual = diff;
        }
    }
    return residual;
}
