public double rmsdCAs(Protein inputPro, Protein pro, int res1, int res2) {
    double[] xInput = new double[2];
    double[] yInput = new double[2];
    double[] zInput = new double[2];
    double[] xPro = new double[2];
    double[] yPro = new double[2];
    double[] zPro = new double[2];

    for (int i = 0; i < 2; i++) {
        Atom inputAtom = inputPro.getAtom("CA", res1 + i);
        Atom proAtom = pro.getAtom("CA", res1 + i);
        xInput[i] = inputAtom.getX();
        yInput[i] = inputAtom.getY();
        zInput[i] = inputAtom.getZ();
        xPro[i] = proAtom.getX();
        yPro[i] = proAtom.getY();
        zPro[i] = proAtom.getZ();
    }

    double[] rmsd = new double[1];
    KabschAlignment align = new KabschAlignment();
    align.calcRMS(xInput, yInput, zInput, xPro, yPro, zPro, 2, rmsd);
    return rmsd[0];
}
