public static int getEncodedSizeOfBitString(byte[] value, int nbits) {
    int numBytes = (nbits + 7) / 8;
    int lastByteBits = nbits % 8;
    if (lastByteBits == 0) {
        lastByteBits = 8;
    }
    int lengthBytes = 1 + numBytes;
    int totalBits = lengthBytes * 8;
    int paddingBits = totalBits - nbits - 1;
    if (paddingBits < 0) {
        paddingBits = 0;
    }
    int totalLength = lengthBytes;
    if (paddingBits > 0) {
        totalLength += 1;
    }
    return totalLength;
}
