public static long getTimeInNanoseconds(String time) {
    String[] split = time.split(":");
    int hour = Integer.parseInt(split[0]);
    int minute = Integer.parseInt(split[1]);
    double second = Double.parseDouble(split[2]);
    long nanoseconds = (long) (TimeUnit.HOURS.toNanos(hour) + TimeUnit.MINUTES.toNanos(minute) + TimeUnit.SECONDS.toNanos((long) second) + TimeUnit.NANOSECONDS.toNanos((long) ((second - (long) second) * 1_000_000_000)));
    return nanoseconds;
}
