public List<Feature> extractFeatures(BufferedImage intensity, int maxFeatures) {
    List<Feature> features = new ArrayList<>();

    for (int x = 1; x < intensity.getWidth() - 1; x++) {
        for (int y = 1; y < intensity.getHeight() - 1; y++) {
            double center = intensity.getRGB(x, y) & 0xff;
            boolean isMax = true;
            boolean isMin = true;

            for (int i = -1; i <= 1; i++) {
                for (int j = -1; j <= 1; j++) {
                    if (i == 0 && j == 0) {
                        continue;
                    }
                    double neighbor = intensity.getRGB(x + i, y + j) & 0xff;

                    if (center <= neighbor) {
                        isMax = false;
                    }
                    if (center >= neighbor) {
                        isMin = false;
                    }
                }
            }

            if (isMax || isMin) {
                Feature feature = new Feature(x, y, center);
                features.add(feature);
            }
        }
    }

    Collections.sort(features);

    if (features.size() > maxFeatures) {
        features = features.subList(0, maxFeatures);
    }

    return features;
}
