public List<XsdAttribute> removeDuplicates(List<XsdAttribute> attributes) {
    Set<String> seenNames = new HashSet<>();
    List<XsdAttribute> distinctAttributes = new ArrayList<>();
    for (XsdAttribute attribute : attributes) {
        if (!seenNames.contains(attribute.getName())) {
            seenNames.add(attribute.getName());
            distinctAttributes.add(attribute);
        }
    }
    return distinctAttributes;
}
